  ["_CeladonGymAfterBattleText5"] = "Nella\nnostra PAL. usiamo\11solo POKéMON di\ntipo Erba! Li\11usiamo anche per\ncomposizioni\11floreali!",
  ["_CeladonGymAfterBattleText6"] = "La\nnostra CAPOPAL.\11ERIKA puo'\nsembrare quieta,\11ma é anche molto\nabile!",
  ["_CeladonGymAfterBattleText7"] = "Ho\nun appuntamento al\11buio. Devo\nimparare a essere\11educata.",
