  ["_CeladonGymBattleText2"] = "Ehi!\nNon puoi entrare\11qui!",
  ["_CeladonGymBattleText3"] = "Cominciavo\na annoiarmi.",
  ["_CeladonGymBattleText4"] = "Non\nsarai mica un\11voyeur?",
  ["_CeladonGymBattleText5"] = "Guarda\ni miei POKéMON\11Erba! é cosi'\nfacile allevarli!",
  ["_CeladonGymBattleText6"] = "Non\nportare POKéMON\11Insetto o Fuoco\nqui dentro!",
  ["_CeladonGymBattleText7"] = "Piacere\ndi conoscerti. Il\11mio hobby é\nl'allenamento\11POKéMON.",
  ["_CeladonGymBattleText8"] = "Benvenuto\nnella PALESTRA DI\11AZZURROPOLI!\nFaresti meglio a\11non sottovalutare\nle ragazze!",
  ["_CeladonGymEndBattleText2"] = "Sei\ntroppo rozzo!",
  ["_CeladonGymEndBattleText3"] = "Il\nmio trucco!",
  ["_CeladonGymEndBattleText4"] = "Sono\nchoc!",
  ["_CeladonGymEndBattleText5"] = "No!",
  ["_CeladonGymEndBattleText6"] = "Oh!\nTu!",
  ["_CeladonGymEndBattleText7"] = "Oh!\nSplendido!",
  ["_CeladonGymEndBattleText8"] = "Oh!\nBattuta!",
  ["_CeladonGymErikaPostBattleAdviceText"] = "Cataloghi i\nPOKéMON? Devo dire\11che sono\nimpressionata. Non\11collezionerei mai\nPOKéMON poco\11attraenti.",
  ["_CeladonGymErikaPreBattleText"] = "Salve. Che\nbel tempo, vero? é\11cosi' piacevole.\n...Oh cielo... Mi\11sono appisolata.\nBenvenuto. Mi\11chiamo ERIKA. Sono\nla CAPOPALESTRA di\11AZZURROPOLI.\nInsegno l'arte\11dell'ikebana. I\nmiei POKéMON sono\11di tipo Erba. Oh,\nperdona, non\11sapevo volessi\nsfidarmi. Va bene,\11ma non terro'\ntesta bassa.",
  ["_CeladonGymErikaReceivedRainbowBadgeText"] = "Oh! Ammetto la\nsconfitta. Sei\11davvero molto\nforte. Devo\11conferirti il\nMEDAGLIA\11ARCOBALENO.",
  ["_CeladonGymRainbowBadgeInfoText"] = "Il MEDAGLIA\nARCOBALENO fara'\11ubbidire i POKéMON\nfino al Lv. 50.\11Permette anche di\nusare FORZA dentro\11e fuori la lotta.\nPrendi anche\11questo con te.",
  ["_CeladonGymReceivedTM21Text"] = "{PLAYER} ha\nricevuto\11{RAM:wStringBuffer}!",
  ["_CeladonGymTM21NoRoomText"] = "Dovresti fare\nspazio per questo.",
  ["_CeladonHotelBeautyText"] = "Sono in vacanza\ncon mio fratello e\11il mio ragazzo.\nAZZURROPOLI é una\11citta' cosi'\ncarina!",
  ["_CeladonHotelGrannyText"] = "POKéMON? No,\nquesto é un hotel\11per persone. Siamo\nal completo.",
  ["_CeladonHotelSuperNerdText"] = "Perché si é\nportata dietro il\11fratello?",
