  ["_CeladonMansion1FGrannyText"] = "I miei cari\nPOKéMON mi fanno\11compagnia. MEOWTH\nporta anche a casa\11dei soldi!",
  ["_CeladonMansion1FManagersSuiteSignText"] = "VILLA AZZURROPOLI\nSuite del Manager",
