  ["_CeladonMansion3FPlayingGamePCText"] = "Qualcuno sta\ngiocando invece di\11lavorare!",
  ["_CeladonMansion3FProgrammerText"] = "Io? Sono il\nprogrammatore!",
  ["_CeladonMansion3FWriterText"] = "Ho scritto la\nstoria! Non é\11carina ERIKA? Mi\npiace molto anche\11MISTY! Oh, e\nSABRINA, lei mi\11piace!",
  ["_CeladonMansionRoofHouseHikerText"] = "So tutto sul mondo\ndei POKéMON nel\11tuo GAME BOY!\nIncontrati con gli\11amici e scambia\nPOKéMON!",
  ["_CeladonMansionRoofHouseSignText"] = "SO TUTTO!",
  ["_CeladonMart1FCurrentFloorSignText"] = "1P: BANCO\nINFORMAZIONI",
  ["_CeladonMart1FDirectorySignText"] = "1P: BANCO INFO 2P:\nMERCATO ALLENATORI\113P: NEGOZIO\nVIDEOGIOCHI 4P:\11REGALI SAGGI 5P:\nERBORISTERIA\11REPARTO SUL TETTO:\nDISTRIBUTORI",
  ["_CeladonMart1FReceptionistText"] = "Salve! Benvenuto\nal GRANDE MAG. Il\11cartello a destra\nindica i reparti.",
  ["_CeladonMart2FCurrentFloorSignText"] = "Strumenti top per\nallenatori! P:\11MERCATO ALLENATORI",
  ["_CeladonMart2FGirlText"] = "Per le lunghe\nuscite dovresti\11comprare una\nREVIVASPEC.",
  ["_CeladonMart2FMiddleAgedManText"] = "SUPERREPELLENTE\ntiene lontani i\11POKéM. piu'\ndeboli... Mh, é un\11REPELLENTE piu'\npotente!",
  ["_CeladonMart3FClerkReceivedTM18Text"] = "{PLAYER} ha\nricevuto\11{RAM:wStringBuffer}!",
  ["_CeladonMart3FClerkTM18ExplanationText"] = "La MT18 é\nCONTROPIEDE! Non\11quella a cui mi\nappoggio io,\11ovviamente!",
  ["_CeladonMart3FClerkTM18NoRoomText"] = "Il tuo zaino é\npieno di\11strumenti!",
  ["_CeladonMart3FClerkTM18PreReceiveText"] = "Oh, ciao! Ho\nfinalmente finito\11i POKé! Non hai\nancora finito?\11Questo potrebbe\nesserti utile!",
  ["_CeladonMart3FCurrentFloorSignText"] = "3P: NEGOZIO\nVIDEOGIOCHI",
  ["_CeladonMart3FFightingGameText"] = "Un picchiaduro!\nSembra difficile!",
  ["_CeladonMart3FGameBoyKid1Text"] = "I POKéMON\ncatturati\11registrano un Num.\nID e AO, il nome\11dell'Allenatore\nOriginale che li\11ha catturati!",
  ["_CeladonMart3FGameBoyKid2Text"] = "Bene! Il mio amico\nmi scambia il suo\11KANGASKHAN per il\nmio GRAVELER!",
  ["_CeladonMart3FGameBoyKid3Text"] = "Forza GRAVELER!\nAdoro GRAVELER! Li\11colleziono! Eh?\nGRAVELER si é\11trasformato in un\naltro POKéMON!",
  ["_CeladonMart3FLittleBoyText"] = "Puoi identificare\ni POKéMON presi\11negli scambi dal\nloro Numero ID!",
  ["_CeladonMart3FPokemonPosterText"] = "Rosso e Blu! Sono\nentrambi POKéMON!",
  ["_CeladonMart3FPuzzleGameText"] = "Un puzzle game!\nCrea dipendenza!",
  ["_CeladonMart3FRPGText"] = "Un GdR! Non c'é\ntempo per quello!",
  ["_CeladonMart3FSNESText"] = "é un Super NES!",
  ["_CeladonMart3FSportsGameText"] = "Un gioco di sport!\nAl babbo piacera'!",
  ["_CeladonMart4FCurrentFloorSignText"] = "Esprimiti con i\nregali! 4P: REGALI\11SAGGI Speciale\nEvoluzione! PIETRE\11elementari in\nofferta!",
  ["_CeladonMart4FSuperNerdText"] = "Prendo una BAMBOLA\nPOKé per la mia\11ragazza!",
  ["_CeladonMart4FYoungsterText"] = "Ho sentito una\ncosa utile. Puoi\11fuggire dai\nPOKéMON selvatici\11distraendoli con\nuna BAMBOLA POKé!",
  ["_CeladonMart5FCurrentFloorSignText"] = "5P: ERBORISTERIA",
  ["_CeladonMart5FGentlemanText"] = "I potenziatori di\nstatistiche si\11comprano solo qui.\nUsa CALCIO per\11aumentare le\nabilita' SPECIALI.\11Usa CARBURANTE per\naumentare la\11VELOCITA'.",
  ["_CeladonMart5FSailorText"] = "Sono qui per i\npotenziatori!\11PROTEINA aumenta\nil Attacco. FERRO\11aumenta la DIFESA!",
  ["_CeladonMartRoofCurrentFloorSignText"] = "REPARTO SUL TETTO:\nDISTRIBUTORI",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "Ho sete! Voglio\nqualcosa da bere!\11Le dai da bere?",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "Quale bibita le\ndai?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "No, grazie! Alla\nfine non ho piu'\11sete!",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "Ho sete! Voglio\nqualcosa da bere!",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "Non hai spazio per\nquesto!",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER} ha\nricevuto\11{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER} ha\nricevuto\11{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER} ha\nricevuto MT49!",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "{RAM:wStringBuffer}\ncontiene\11GELOPUNTO! A volte\npuo' congelare il\11bersaglio!",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "{RAM:wStringBuffer}\ncontiene FRANA! A\11volte puo'\nspaventare il\11bersaglio!",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "La MT49 contiene\nTRIPLICE ATTACCO!",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "Evviva! ACQUA\nFRESCA! Grazie!\11Puoi prendere\nquesto da parte\11mia!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "Evviva! LIMONATA!\nGrazie! Puoi\11prendere questo da\nparte mia!",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "Evviva! BIBITA!\nGrazie! Puoi\11prendere questo da\nparte mia!",
  ["_CeladonMartRoofSuperNerdText"] = "Mia sorella é\nun'allenatrice ci\11credi o no. Ma é\ncosi' immatura che\11mi fa impazzire!",
  ["_CeladonPokecenterBeautyText"] = "Ho pedalato in\nsalita sulla PISTA\11CICLABILE da\nFUCSIAPOLI!",
  ["_CeladonPokecenterGentlemanText"] = "Il FLAUTO POKé\nsveglia i POKéMON\11con un suono che\nsentono solo loro!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "L'ATTACCO di tutti\ni POKéMON aumenta\11un pochino.\nPermette anche di\11usare FLASH ogni\nvolta che lo\11desideri.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "I POKéMON fino al\nLv. 30\11ubbidiranno. Piu'\nalti, diventeranno\11insoffrenti!\nPermette anche di\11usare TAGLIO fuori\ndallotta.",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "Tutti i POKéMON ti\nubbidiranno!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "I POKéMON fino al\nLv. 70\11ubbidiranno. Piu'\nalti, diventeranno\11insoffrenti!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "Le MEDAGLIE\nPOKéMON sono\11possedute solo da\nesperti. Vedo che\11ne hai almeno una.\nQuelle medaglie\11hanno segreti\nincredibili!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Vieni a trovarmi\nquando vuoi.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Dunque... Quale\ndelle 8 medaglie\11devo descrivere?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "I POKéMON fino al\nLv. 50\11ubbidiranno. Piu'\nalti, diventeranno\11insoffrenti!\nPermette anche di\11usare FORZA fuori\ndalla lotta.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "La DIFESA di tutti\ni POKéMON aumenta\11un pochino.\nPermette anche di\11usare SURF fuori\ndalla lotta.",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "La VELOCITA' di\ntutti i POKéMON\11aumenta un\npochino. Permette\11anche di usare\nVOLO fuori dalla\11lotta.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Le abilita'\nSPECIALI dei tuoi\11POKéMON aumentano\nun po'.",
  ["_CeruleanCityBikeShopSign"] = "Erba e grotte\naffrontate facili!\11NEGOZIO BICI",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "Pugno SLOWBRO! No!\nHai sbagliato di\11nuovo!",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "Ok! SLOWBRO! Usa\nSONICBOOM! Forza,\11SLOWBRO presta\nattenzione!",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "SLOWBRO, RITIRATA!\nNo! é sbagliato! é\11cosi' difficile\ncontrollare i\11POKéMON!\nL'ubbidienza\11dipende 膵dalle tue\nabilita' di\11allenatore!",
  ["_CeruleanCityCooltrainerF2Text"] = "Voglio una\nBICICLETTA rosso\11fuoco! La terro'\nin casa cosi' non\11si sporca!",
  ["_CeruleanCityCooltrainerMText"] = "Sei un allenatore\nanche tu?\11Collezionare e\nlottare é dura.",
  ["_CeruleanCityGuardText"] = "La gente qui é\nstata rapinata. é\11ovvio che il TEAM\nROCKET é dietro\11questo efferato\ncrimine! Anche la\11POLIZIA ha\nproblemi con i\11ROCKET!",
  ["_CeruleanCityGymSign"] = "CELESTOPOLI\nPALESTRA POKéMON\11CAPOPALESTRA:\nMISTY La Sirenetta\11Sanguigna",
  ["_CeruleanCityRivalDefeatedText"] = "Ehi! Calma! Hai\ngia' vinto!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: Ehi,\nsapevi? Sono\11andato da BILL e\nmi ha fatto vedere\11i suoi rari\nPOKéMON! Ha\11aggiunto molte\npagine al mio\11POKéDEX!\nD'altronde, BILL é\11famoso nel mondo\ncome POKéMANIAC!\11Ha inventato il\nSistema Memoria\11POKéMON su PC!\nVisto che usi il\11suo sistema,\nringrazialo! Beh,\11devo filare! Ci\nbecchiamo!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}:\nEhi! {PLAYER}! Te\11la strascichi\nancora qui dietro?\11Io me la cavo alla\ngrande! Ho\11catturato un bel\npo' di POKéMON\11forti e\nintelligenti!\11Ecco, fammi vedere\ncosa hai\11catturato,\n{PLAYER}!",
  ["_CeruleanCityRivalVictoryText"] = "Heh! Non sei alla\naltezza del mio\11genio!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "Devo proprio\nmuovermi! Ciao!",
  ["_CeruleanCityRocketIGiveUpText"] = "Fermati! Mi\narrendo! Me ne\11vado quatto\nquatto!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "Ok! Resituiro' la\nMT che ho rubato!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER} ha\nrecuperato la\11MT28!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "Fai spazio per\nquesto! Non posso\11muovermi finché\nnon te la do!",
  ["_CeruleanCityRocketText"] = "Ehi! Fuori! Não é\nil tuo cortile!\11Eh? Io? Sono un\ninnocente\11passante! Non mi\ncredi?",
  ["_CeruleanCitySignText"] = "CELESTOPOLI\nUn'aura blu e\11misteriosa la\ncirconda",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "SLOWBRO ha\nignorato gli\11ordini...",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "SLOWBRO ciondola\nin giro...",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "SLOWBRO si é fatto\nun sonnellino...",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "SLOWBRO si é\ngirato dall'altra\11parte...",
  ["_CeruleanCitySuperNerd1Text"] = "Quel cespuglio\ndavanti al negozio\11é d'intralcio.\nForse c'é una via\11alternativa.",
  ["_CeruleanCitySuperNerd2Text"] = "Stai facendo un\nenciclopedia sui\11POKéMON?\nInteressante.",
  ["_CeruleanCitySuperNerd3Text"] = "Questa é la GROTTA\nCELESTE! Ci vivono\11POKéMON\nfortissimi! Solo\11il campione della\nLEGA POKéMON puo'\11entrare!",
  ["_CeruleanCityTrainerTipsText"] = "CONSIGLI UTILI\nPremere il\11pulsante B durante\nl'evoluzione\11annulla l'intero\nprocesso.",
  ["_CeruleanGymAfterBattleText1"] = "Devi\naffrontare altri\11allenatori per\nscoprire quanto\11vali davvero.",
  ["_CeruleanGymAfterBattleText2"] = "MISTY\ncontinuera' a\11migliorare! Non\nperdera' con uno\11come te!",
  ["_CeruleanGymBattleText1"] = "Valgo\nmolto piu' di te!\11MISTY puo'\naspettare!",
  ["_CeruleanGymBattleText2"] = "Splash!\nSono il primo!\11Facciamolo!",
  ["_CeruleanGymEndBattleText1"] = "Mi\nhai sopraffatto!",
  ["_CeruleanGymEndBattleText2"] = "Non\npuo' essere!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "Hai battuto MISTY!\nChe ti avevo\11detto? Io e te,\nragazzo, siamo una\11bella squadra!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "Ehi! Futuro\ncampione! Ecco il\11mio consiglio! La\nCAPOPALESTRA MISTY\11é un asso dei\nPOKéMON Acqua!\11Puoi prosciugarli\ncon i POKéMON\11Pianta! O\nfulminarli con\11l'elettricita'!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "La MEDAGLIA\nCASCATA fa\11ubbidire i POKéMON\nfino al Lv. 30!\11Inclusi quelli\nscambiati! C'é di\11piu': ora puoi\nusare TAGLIO! Puoi\11tagliare i piccoli\ncespugli per\11aprire vie! Prendi\nanche la mi MT\11preferita!",
  ["_CeruleanGymMistyPreBattleText"] = "Ciao, sei\nuna faccia nuova!\11Gli allenatori che\nvogliono diventare\11pro devono avere\nuna politica sui\11POKéMON! Qual é il\ntuo approccio\11quando catturi i\nPOKéMON? La mia\11politica é\nun'offensiva\11totale con POKéMON\nAcqua!",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "Acciderboli! Ci\nsai fare! Va bene!\11Prendi la MEDAGLIA\nCASCATA. per\11dimostrare che mi\nhai battuta!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER} ha\nricevuto la MT11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "La MT11 insegna\nBOLLARAGGIO! Usala\11su un POKéMON\nacquatico!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "Faresti meglio a\nfare spazio!",
  ["_CeruleanMartCooltrainerFText"] = "Hai visto qualche\nCARAM. RARA?\11Dovrebbe far\nsalire i POKéMON\11di un livello!",
  ["_CeruleanMartCooltrainerMText"] = "Usa REPELLENTE per\ntenere insetti e\11POKéM. deboli alla\nlarga. Metti il\11tuo POKéMON piu'\nforte in cima alla\11lista per\nrisultati\11ottimali!",
  ["_CeruleanPokecenterGentlemanText"] = "Hai sentito\nparlare di BILL?\11Tutti lo chiamano\nPOKéMANIAC! Penso\11che la gente sia\nsolo gelosa di\11BILL. Chi non\nvorrebbe vantarsi\11dei propri\nPOKéMON?",
  ["_CeruleanPokecenterGuyText"] = "BILL ha un sacco\ndi POKéMON!\11Colleziona anche\nquelli rari!",
  ["_CeruleanPokecenterSuperNerdText"] = "Quel BILL! Ho\nsentito che fara'\11di tutto per avere\nPOKéMON rari!",
  ["_CeruleanTradeHouseGrannyText"] = "A mio marito\npiacciono\11scambiare POKéMON.\nSe sei un\11collezionista, ti\nandrebbe di\11scambiare con lui?",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "Miserabili ROCKET!\nGuarda che cosa\11hanno combinato!\nHanno rubato una\11MT per insegnare a\nscavare a un\11POKéMON! Mi é\ncostata un occhio\11della testa!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "Quel che é perso,\né perso! Ho deciso\11di insegnare a\nDIGLETT a scavare\11senza MT!",
  ["_CeruleanTrashedHouseGirlText"] = "Il TEAM ROCKET\nstara' cercando di\11scavarsi un varco!",
  ["_CeruleanTrashedHouseWallHoleText"] = "Il TEAM ROCKET ha\nlasciato una via\11d'uscita!",
  ["_ChampionsRoomOakComeWithMeText"] = "OAK: {PLAYER}!\nCapisci che la tua\11vittoria non é\ndovuta solo a te!\11Il legame con i\ntuo POKéMON é\11meraviglioso!\n{PLAYER}! Vieni con\11me!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "OAK: Hai vinto!\nComplimenti! Sei\11il nuovo campione\ndella LEGA\11POKéMON! Sei\ncresciuto molto da\11quando sei partito\ncon {RAM:wNameBuffer}!\11{PLAYER}, sei\ndiventato grande!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "OAK: {RIVAL}! Sono\ndeluso! Sono\11venuto quando ho\nsaputo che avevi\11battuto i\nSUPERQUATTRO! Ma\11quando sono\narrivato, avevi\11gia' perso!\n{RIVAL}! Capisci\11perché hai perso?\nHai dimenticato di\11tratte i tuoi\nPOKéMON con amore\11e fiducia! Senza\ndi essi, non\11diventerai mai un\ncampione!",
  ["_ChampionsRoomOakText"] = "OAK: {PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "Perché?\nPerché ho perso?\11Non ho mai\ncommesso errori\11crescendo i miei\nPOKéMON...\11Dannazione! Sei tu\nil nuovo campione\11della LEGA\nPOKéMON! Anche se\11faccio fatica ad\nammetterlo.",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: Ehi! Non\nvedevo l'ora di\11vederti, {PLAYER}!\nIl mio rivale deve\11essere forte!\nMentre completavo\11il POKéDEX, ho\ncercato ovunque\11POKéMON forti! Non\nsolo, ho creato\11squadre in grado\ndi battere ogni\11tipo! Ed ora! Sono\nil campione della\11LEGA POKéMON!\n{PLAYER}! Sai cosa\11significa? Te lo\ndico io! Sono\11l'allenatore piu'\nforte del mondo!",
  ["_ChanseyDexEntry"] = "Un POKéMON raro e\nsfuggente, che si\ndice porti\12felicita' a chi\nriesce a\ncatturarlo.",
  ["_ChargeMoveEffectText"] = "{USER}",
  ["_CharizardDexEntry"] = "Sputa fuoco capace\ndi fondere i\nmassi. A volte\12causa incendi\nboschivi senza\nvolerlo.",
  ["_CharmanderDexEntry"] = "Preferisce i\nluoghi caldi.\nQuando piove, la\12punta della sua\ncoda emette\nvapore.",
  ["_CharmeleonDexEntry"] = "Quando agita la\ncoda infuocata,\nalza la\12temperatura a\nlivelli\ninsopportabili.",
  ["_ChooseABoxText"] = "Scegli un BOX\nPOKéMON.",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "FUOCOBOMBA é\nl'ultima tecnica\11di fuoco! Non\nsprecarla sui\11POKéMON Acqua!",
  ["_CinnabarGymBlainePreBattleText"] = "Ah! Sono\nBLAINE! Sono il\11CAPOPALESTRA di\nISOLA CANNELLA! I\11miei POKéMON di\nfuoco\11inceneriranno gli\nsfidanti! Ha!\11Faresti meglio\navere\11ANTISCOTTATURA!",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER} ha\nricevuto\11{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "Sono esaurito! Hai\nconquistato la\11MEDAGLIA VULCANO!",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "La MT38 contiene\nFUOCOBOMBA!\11Insegnala ai\nPOKéMON di tipo\11Fuoco! CHARMELEON\no PONYTA sono\11ottime scelte!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "Fai spazio per il\nmio regalo!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "Ah! La MEDAGLIA\nVULCANO accresce\11le abilita'\nSPECIALI dei\11POKéMON! Tieni,\npuoi avere anche\11questo!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}! Hai\nbattuto quel\11testardo!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "Ehi! Futuro\ncampione!\11L'irascibile\nBLAINE é un\11esperto di POKéM.\nFuoco! Spenta il\11suo spirito con\nl'acqua! Meglio\11prendere delle\nANTISCOTTATURA!",
  ["_CinnabarGymQuizCorrectText"] = "Risposta esatta!\nAvanti, passa\11pure!",
  ["_CinnabarGymQuizIncorrectText"] = "Spiacente!\nSbagliato!",
  ["_CinnabarGymQuizIntroText"] = "Quiz sui POKéMON!\nRispondi bene e la\11porta si aprira'!\nSbaglia e dovrai\11affrontare un\nallenatore! Se\11vuoi conservare i\ntuoi POKéMON per\11il CAPOPALESTRA...\nRispondi bene! Si\11comincia!",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Il\nfuoco, o per\11essere precisi, la\ncombustione...\11Blah, blah, blah,\nblah...",
  ["_CinnabarGymSuperNerd1BattleText"] = "Sai\nquanto puo'\11scaldarsi il fuoco\ndi un POKéMON?",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "Urca!\nChe calore!",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "Non\nriesco a fare a\11meno di rubare i\nPOKéMON altrui!",
  ["_CinnabarGymSuperNerd2BattleText"] = "Ero un\nladro, ma ho messo\11la testa a posto\ncome allenatore!",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "Mi\narrendo!",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "Le mie\nteorie sono troppo\11complesse per te!",
  ["_CinnabarGymSuperNerd3BattleText"] = "Non\npuoi vincere! Ho\11studiato i POKéMON\na fondo!",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "Waaa! I\nmiei studi!",
  ["_CinnabarGymSuperNerd4AfterBattleText"] = "Vorrei\ntanto che\11esistesse un\nPOKéMON ladro! Lo\11userei!",
  ["_CinnabarGymSuperNerd4BattleText"] = "Adoro\nusare i POKéMON di\11fuoco!",
  ["_CinnabarGymSuperNerd4EndBattleText"] = "Troppo\ncaldo da gestire!",
  ["_CinnabarGymSuperNerd5AfterBattleText"] = "BLAINE\nsi era perso tra i\11monti quando\napparve un POKéMON\11volatile\ninfuocato. La sua\11luce aiuto' BLAINE\na trovare la via\11d'uscita!",
  ["_CinnabarGymSuperNerd5BattleText"] = "So\nperché BLAINE é\11diventato\nallenatore!",
  ["_CinnabarGymSuperNerd5EndBattleText"] = "Ahi!",
