  ["_CinnabarLabFossilRoomScientist1NoFossilsText"] = "No! Che peccato!",
  ["_CinnabarLabFossilRoomScientist1SeesFossilText"] = "Oh! Quello é\n{RAM:wNameBuffer}! é il\11fossile di\n{RAM:wStringBuffer}, un\11POKéMON estinto!\nLa mia Macchina\11della Resurrezione\nlo fara' rivivere!",
