  ["_CinnabarLabMetronomeRoomScientist1TM35ExplanationText"] = "Tch-tch-tch! é il\nsuono del\11METRONOMO!\nStuzzica il\11cervello del\nPOKéMON facendogli\11usare mosse che\nnon conosce!",
  ["_CinnabarLabMetronomeRoomScientist1TM35NoRoomText"] = "Lo zaino é pieno\nzeppo!",
