  ["_FuchsiaBillsGrandpasHouseMiddleAgedWomanText"] = "Il GUARDIANO é\nvecchio,\11ma\arzillo! Ha\ntutti i denti\11finti pero'.",
  ["_FuchsiaBillsGrandpasHouseYoungsterText"] = "BILL archivia i\nsuoi dati POKéMON\11sul suo PC! Te li\nha mostrati?",
  ["_FuchsiaCityChanseySignText"] = "Nome: CHANSEY\nCatturarne uno é\11solo questione di\nfortuna.",
  ["_FuchsiaCityErikText"] = "ERIK: Dov'é SARA?\nHo detto che\11l'avrei incontrata\nqui.",
  ["_FuchsiaCityFossilSignKabutoText"] = "Nome: KABUTO Un\nPOKéMON\11resuscitato da un\nfossile.",
  ["_FuchsiaCityFossilSignOmanyteText"] = "Nome: OMANYTE Un\nPOKéMON\11resuscitato da un\nfossile.",
  ["_FuchsiaCityFossilSignUndeterminedText"] = "...",
  ["_FuchsiaCityGamblerText"] = "La ZONA SAFARI ha\nuno zoo\11all'ingresso. Sul\nretro c'é il GIOCO\11SAFARI per\ncatturare POKéMON.",
  ["_FuchsiaCityGymSignText"] = "FUCSIAPOLI\nPALESTRA POKéMON\11CAPOPALESTRA: KOGA\nIl Maestro Ninja\11Velenoso",
  ["_FuchsiaCityKangaskhanSignText"] = "Nome: KANGASKHAN\nUn POKéMON materno\11che alleva i\npiccoli nel\11marsupio sul\nventre.",
  ["_FuchsiaCityLaprasSignText"] = "Nome: LAPRAS Il re\ndei mari.",
  ["_FuchsiaCityPokecenterGuyText"] = "Se studi i\nPOKéMON, visita la\11ZONA SAFARI. Ci\nsono ogni sorta di\11POKéMON rari.",
  ["_FuchsiaCityPokemonText"] = "!",
  ["_FuchsiaCitySafariGameSignText"] = "GIOCO SAFARI\nCATTURA-POKéMON!",
  ["_FuchsiaCitySafariZoneSignText"] = "PARADISO POKéMON\nZONA SAFARI",
  ["_FuchsiaCitySignText"] = "FUCSIAPOLI Ecco il\nrosa passione!",
  ["_FuchsiaCitySlowpokeSignText"] = "Nome: SLOWPOKE\nAmichevole e molto\11lento nei\nmovimenti.",
  ["_FuchsiaCityVoltorbSignText"] = "Nome: VOLTORB\nL'esatta immagine\11di una POKé BALL.",
  ["_FuchsiaCityWardensHomeSignText"] = "ZONA SAFARI CASA\nDEL GUARDIA",
  ["_FuchsiaCityYoungster1Text"] = "Hai provato il\nGIOCO SAFARI?\11Alcuni POKéMON si\ntrovano solo li'.",
  ["_FuchsiaCityYoungster2Text"] = "Quella Poké Ball\nper terra é in\11realta' un\nPOKéMON.",
  ["_FuchsiaGoodRodHouseFishingGuruHowAreTheFishText"] = "Salve, {PLAYER}!\nCome abboccano i\11pesci?",
  ["_FuchsiaGoodRodHouseFishingGuruNoRoomText"] = "Oh no! Non hai\nspazio per il mio\11regalo!",
  ["_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText"] = "Ottimo! Mi piace\nil tuo stile!\11Prendi questo e\npesca, giovanotto!\11{PLAYER} ha\nricevuto un\11{RAM:wStringBuffer}!",
  ["_FuchsiaGoodRodHouseFishingGuruText"] = "Sono il fratello\nmaggiore del GURU\11PESCATORE! Adoro\nletteralmente\11pescare! Ti piace\npescare?",
  ["_FuchsiaGoodRodHouseFishingGuruThatsSoDisappointingText"] = "Oh... Che\ndelusione...",
  ["_FuchsiaGymGymGuideBeatKogaText"] = "é incredibile come\ni ninja\11terrorizzino\nancora oggi!",
  ["_FuchsiaGymGymGuideChampInMakingText"] = "Ehi! Futuro\ncampione! La\11PALESTRA DI\nFUCSIAPOLI é un\11labirinto di muri\ninvisibili! KOGA\11sembra vicino, ma\né bloccato! Devi\11trovare i varchi\nnei muri per\11raggiungerlo!",
  ["_FuchsiaGymKogaBeforeBattleText"] = "KOGA:\nFwahahaha! Un\11semplice bambino\ncome te osa\11sfidarmi? Molto\nbene, ti mostrero'\11il terrore di un\nmaestro ninja!\11Proverai la\ndisperazione di\11veleno e sonno!",
  ["_FuchsiaGymKogaPostBattleAdviceText"] = "Se colpiti da\nTOSSINA, i POKéMON\11soffrono sempre\npiu' con\11l'avanzare della\nlotta!\11Terrorizzera' di\ncerto i nemici!",
  ["_FuchsiaGymKogaReceivedSoulBadgeText"] = "Uhm! Hai\ndimostrato il tuo\11valore! Tieni!\nPrendi la MEDAGLIA\11ANIMA!",
  ["_FuchsiaGymKogaReceivedTM06Text"] = "{PLAYER} ha\nricevuto\11{RAM:wStringBuffer}!",
  ["_FuchsiaGymKogaSoulBadgeInfoText"] = "Ora che possiedi\nla MEDAGLIA ANIMA,\11la DIFESA dei tuoi\nPOKéMON aumenta!\11Ti permette anche\ndi usare SURF\11fuori dallotta!\nAh, prendi anche\11questo!",
  ["_FuchsiaGymKogaTM06ExplanationText"] = "La MT06 contiene\nTOSSINA! é una\11tecnica segreta\nvecchia di oltre\11400 anni!",
  ["_FuchsiaGymKogaTM06NoRoomText"] = "Fa' spazio per\nquesto, ragazzo!",
  ["_FuchsiaGymRocker1AfterBattleText"] = "Quindi\nunisci la forza\11all'ingegno? Buona\nstrategia!",
  ["_FuchsiaGymRocker1BattleText"] = "La forza\nnon é il fattore\11chiave per i\nPOKéMON! é la\11strategia! Ti\nmostrero' come\11battere la forza\nbruta!",
  ["_FuchsiaGymRocker1EndBattleText"] = "Cosa?\nStraordinario!",
  ["_FuchsiaGymRocker2AfterBattleText"] = "Continuero'\nad allenarmi sotto\11KOGA, il mio\nmaestro ninja!",
  ["_FuchsiaGymRocker2BattleText"] = "Volevo\ndiventare un\11ninja, cosi' sono\nentrato in\11PALESTRA!",
  ["_FuchsiaGymRocker2EndBattleText"] = "Sono\nfritto!",
  ["_FuchsiaGymRocker3AfterBattleText"] = "Adoro\nveleno e tecniche\11di sonno, perché\npersistono dopo la\11lotta!",
  ["_FuchsiaGymRocker3BattleText"] = "Vediamo se\nbatti le mie\11tecniche speciali!",
  ["_FuchsiaGymRocker3EndBattleText"] = "Mi hai\ningannato!",
  ["_FuchsiaGymRocker4AfterBattleText"] = "Mi hai\nimpressionato!\11Ecco un indizio!\nCerca con\11attenzione i\nvarchi nei muri\11invisibili!",
  ["_FuchsiaGymRocker4BattleText"] = "Fermati\nli'! I nostri muri\11invisibili ti\nfanno impazzire?",
  ["_FuchsiaGymRocker4EndBattleText"] = "Urca! Ci é\nriuscito!",
  ["_FuchsiaGymRocker5AfterBattleText"] = "Ho ancora\nmolto da imparare!",
  ["_FuchsiaGymRocker5BattleText"] = "Studio la\nvia dei ninja col\11maestro KOGA! I\nninja usano gli\11animali da sempre!",
  ["_FuchsiaGymRocker5EndBattleText"] = "Awoo!",
  ["_FuchsiaGymRocker6AfterBattleText"] = "Dove c'é\nluce, c'é ombra!\11Luce e ombra!\nQuale scegli?",
  ["_FuchsiaGymRocker6BattleText"] = "Il maestro\nKOGA discende da\11una stirpe di\nlunghi ninja! Tu\11da chi discendi?",
  ["_FuchsiaGymRocker6EndBattleText"] = "Ho perso i\ngettoni!",
  ["_FuchsiaMartCooltrainerFText"] = "Hai provato\nVELOCITA' X?\11Accelera un\nPOKéMON in lotta!",
  ["_FuchsiaMartMiddleAgedManText"] = "Hai una bandiera\ndella ZONA SAFARI?\11E carte o\ncalendari?",
  ["_FuchsiaMeetingRoomSafariZoneWorker1"] = "Soprannominammo il\nGUARDIA SLOWPOKE.\11Lui e il GUARDIA\nsembrano svagati!",
  ["_FuchsiaMeetingRoomSafariZoneWorker2"] = "Il GUARDIA sa\nmoltissimo sui\11POKéMON! Ha\npersino fossili di\11rari POKéMON\nestinti!",
  ["_FuchsiaMeetingRoomSafariZoneWorker3"] = "Il GUARDIA é\nentrato, ma non si\11capiva. Credo\nabbia un problema\11di parlato!",
  ["_FuchsiaPokecenterCooltrainerFText"] = "C'é uno stretto\nsentiero a ovest\11di SMERALDOPOLI.\nPorta al quartier\11generale della\nLEGA. Il Q.G.\11governa tutti gli\nallenatori.",
  ["_FuchsiaPokecenterRockerText"] = "Non puoi vincere\ncon un solo\11POKéMON forte. é\ndura, ma devi\11crescerli in modo\nequilibrato.",
  ["_FullHealText"] = "La salute di\n{RAM:wNameBuffer} é\11tornata!",
  ["_FullyParalyzedText"] = "{USER} é\ncompletamente\11paralizzato!",
  ["_GainedText"] = "{RAM:wNameBuffer} ha\nguadagnato",
  ["_GameCornerBeauty1Text"] = "Benvenuto! Puoi\nscambiare i\11gettoni per\nfavolosi premi\11nella porta\naccanto.",
  ["_GameCornerBeauty2Text"] = "Penso che queste\nmacchine abbiano\11probabilita'\ndiverse.",
