  ["_GameCornerClerk1CoinCaseIsFullText"] = "Ops! Il\nSALVADANAIO é\11pieno.",
  ["_GameCornerClerk1DoYouNeedSomeGameCoinsText"] = "Benvenuto alla\nSALA GETTONI\11ROCKET! Ti servono\ngettoni? Il costo\11é di ¥1000 per 50\ngettoni. Vuoi\11acquistarli?",
  ["_GameCornerClerk1DontHaveCoinCaseText"] = "Non hai il\nSALVADANAIO!",
  ["_GameCornerClerk1PleaseComePlaySometimeText"] = "No? Torna a\ngiocare qualche\11volta!",
