  ["_GameCornerFishingGuruWinsComeAndGoText"] = "Le vittorie vanno\ne vengono.",
  ["_GameCornerGamblerText"] = "I giochi fanno\npaura! é facile\11diventarne\ndipendenti!",
  ["_GameCornerGentlemanCloselyWatchTheReelsText"] = "Il trucco é\nosservare i rulli\11da vicino!",
  ["_GameCornerGentlemanReceived20CoinsText"] = "{PLAYER} ha\nricevuto 20\11gettoni!",
  ["_GameCornerGentlemanThrowingMeOffText"] = "Ehi, che fai? Mi\ndistrai! Prendi\11dei gettoni,\nsgombra il campo!",
  ["_GameCornerGentlemanYouGotYourOwnCoinsText"] = "Hai gia' i tuoi\ngettoni!",
  ["_GameCornerGymGuideChampInMakingText"] = "Ehi! Hai cose\nmigliori da fare,\11futuro campione!\nLa CAPOPALESTRA di\11CELASTOPOLI é\nERIKA! Usa POKéMON\11Erba! Sembra\ndocile, ma non\11farti ingannare!",
