  ["_GastlyDexEntry"] = "Quasi invisibile,\nquesto POKéMON\ngassoso avvolge il\12bersaglio e lo\naddormenta senza\npreavviso.",
  ["_GengarDexEntry"] = "Con la luna piena,\nquesto POKéMON\nadora imitare\12l'ombra delle\npersone e ridere\ndella loro paura.",
  ["_GeodudeDexEntry"] = "Si trova nei campi\ne sui monti.\nScambiandolo per\12un masso, la gente\nvi inciampa\nspesso.",
