  ["_GroundRoseText"] = "Il terreno si é\nsollevato altrove!",
  ["_GrowlitheDexEntry"] = "Molto protettivo\nverso il suo\nterritorio. Abbaia\12e morde per\nrespingere gli\nintrusi.",
  ["_GyaradosDexEntry"] = "Raro da vedere in\nnatura. Enorme e\nferoce, é in grado\12di radere al suolo\nintere citta' in\nun raptus.",
  ["_GymStatueText1"] = "{RAM:wGymCityName}\nPALESTRA POKéMON\11CAPOPALESTRA:\n{RAM:wGymLeaderName}\11ALLENATORI\nVINCENTI: {RIVAL}",
  ["_GymStatueText2"] = "{RAM:wGymCityName}\nPALESTRA POKéMON\11CAPOPALESTRA:\n{RAM:wGymLeaderName}\11ALLENATORI\nVINCENTI: {RIVAL}\11{PLAYER}",
  ["_HMCantDeleteText"] = "Le tecniche MN non\nsi cancellano!",
  ["_HallOfFameOakText"] = "OAK: Ekhm!\nCongratulazioni\11{PLAYER}! Questo\npiano é la SALA\11D'ONORE POKéMON! I\ncampioni della\11LEGA POKéMON\nvengono onorati\11qui per le loro\nimprese! Anche i\11loro POKéMON sono\nregistrati nella\11SALA MAGNA!\n{PLAYER}! Hai\11lottato duro per\ndiventare il nuovo\11campione!\nCongratulazioni,\11{PLAYER}, tu e i\ntuoi POKéMON\11entrate nella\nSALA!",
  ["_HasSubstituteText"] = "{USER} ha un\nSOSTITUTO!",
  ["_HaunterDexEntry"] = "Grazie alla sua\ncapacita' di\nattraversare i\12muri, si dice\nprovenga da altra\ndimensione.",
  ["_HereYouGoText"] = "Prego!",
  ["_HiddenItemBagFullText"] = "Ma {PLAYER} non ha\npiu' spazio per\11altri strumenti!",
  ["_HisNameIsText"] = "Esatto! Ora\nricordo! Si chiama\11{RIVAL}!",
  ["_HitWithRecoilText"] = "{USER} subisce\ncontraccolpo!",
  ["_HitXTimesText"] = "Colpito\n{NUM:wEnemyNumHits,\111, 1} volte!",
  ["_HitmonchanDexEntry"] = "Senza apparente\nmovimento, sferra\nraffiche di pugni\12cosi' veloci da\nessere impossibili\nda vedere.",
  ["_HitmonleeDexEntry"] = "Quando ha fretta,\nle sue zampe si\nallungano\12progressivamente,\npercorrendo lunghi\npassi fluidi.",
  ["_HookedMonAttackedText"] = "Il {RAM:wEnemyMonNick}\nallamato ha\11attaccato!",
  ["_HorseaDexEntry"] = "Noto per abbattere\ninsetti volanti\ncon precisione\12grazie a getti di\ninchiostro\ndall'acqua.",
  ["_HurtByBurnText"] = "{USER} é ferito\ndalla scottatura!",
  ["_HurtByLeechSeedText"] = "PARASSITA\nprosciuga {USER}!",
  ["_HurtByPoisonText"] = "{USER} é ferito\ndal veleno!",
  ["_HurtItselfText"] = "Si é ferito da\nsolo nella\11confusione!",
  ["_HypnoDexEntry"] = "Quando fissa un\nnemico, usa varie\nmosse PSI come\12IPNOSI e\nCONFUSIONE.",
  ["_IceHealText"] = "{RAM:wNameBuffer} é\nscongelato!",
  ["_IgnoredOrdersText"] = "{RAM:wBattleMonNick} ignora\ngli ordini!",
  ["_IndigoPlateauHQText"] = "Altopiano INDACO\nSEDE LEGA POKéMON",
  ["_IndigoPlateauLobbyCooltrainerFText"] = "Da qui in poi,\naffronterai i\11SUPER QUATTRO uno\na uno! Se vinci,\11si apre la porta\nper il successivo!\11Buona fortuna!",
  ["_IndigoPlateauLobbyGymGuideText"] = "Ehila'! Campione\nin erba! Alla LEGA\11POKéMON devi\naffrontare i SUPER\11QUATTRO. Se perdi,\nricominci da capo!\11Ci siamo! Dacci\ndentro!",
  ["_IndigoPlateauStatuesText1"] = "ALTOPIANO INDACO",
