  ["_JynxDexEntry"] = "Ancheggia\nsaduttivamente\nmentre cammina,\12inducendo la gente\na ballare in\nsintonia con lui.",
  ["_KabutoDexEntry"] = "Un POKéMON risorto\nda un fossile\ntrovato molto\12tempo fa nel fondo\noceanico.",
  ["_KabutopsDexEntry"] = "La sua forma\nsaffilata é ideale\nper nuotare.\12Taglia la preda\ncon gli artigli e\nne beva i fluidi.",
  ["_KabutopsFossilText"] = "Fossile KABUTOPS\nUn POKéMON\11primitivo e raro.",
  ["_KadabraDexEntry"] = "Emette speciali\nonde alfa dal\ncorpo che causano\12emicrania a chi si\ntrova nelle\nvicinanze.",
  ["_KakunaDexEntry"] = "Quasi incapace di\nmuoversi, puo'\nsolo indurire il\12guscio per\nproteggersi dai\npredatori.",
  ["_KangaskhanDexEntry"] = "Il piccolo esce\nraramente dalla\ntasca protettiva\12della madre finché\nnon compie 3 anni.",
  ["_KeptGoingAndCrashedText"] = "{USER} continua e\nsi schianta!",
  ["_KinglerDexEntry"] = "La chela grande ha\nuna potenza di\nschiacciamento.\12Tuttavia, le\ngrandi dimensioni\nla rendono\12pesante.",
  ["_KoffingDexEntry"] = "Poiché immagazzina\nvari gas tossici\nnel corpo, rischia\12di esplodere senza\nalcun preavviso.",
  ["_KrabbyDexEntry"] = "Le sue chele non\nsono solo potenti\narmi, ma servono\12per mantenere\nl'equilibrio\ncamminando.",
  ["_LancesRoomLanceAfterBattleText"] = "Non posso\nancora credere che\11i miei draghi\nabbiano perso,\11{PLAYER}! Ora sei\ntu il campione\11della LEGA\nPOKéMON! O meglio,\11lo saresti se non\navessi un ultimo\11ostacolo. Devi\naffrontare un\11altro allenatore!\nIl suo nome é...\11{RIVAL}! Ha\nbattuto i SUPER\11QUATTRO prima di\nte! é lui il vero\11campione della\nLEGA POKéMON!",
  ["_LancesRoomLanceBeforeBattleText"] = "Ah! Ho\nsentito parlare di\11te! Io sono il\ncapo dei SUPER\11QUATTRO! Mi chiamo\nLANCE e addestro\11draghi! Sai che i\ndraghi sono\11POKéMON\nmitologici! Sono\11difficili da\ncatturare, ma la\11loro potenza é\nsuperiore! Sono\11praticamente\nindistruttibili!\11Bene, pronto a\nperdere? La tua\11sfida finisce qui,\n{PLAYER}!",
  ["_LancesRoomLanceEndBattleText"] = "Basta! Odio\nammetterlo, ma sei\11un maestro di\nPOKéMON!",
  ["_LaprasDexEntry"] = "Un POKéMON\ncacciato quasi\nfino\12all'estinzione.\nPuo' traghettare\nle persone\12sull'acqua.",
  ["_LavenderCuboneHouseBrunetteGirlGhostIsGoneText"] = "Il FANTASMA della\nTORRE POKéMON é\11sparito! Qualcuno\ndeve aver placato\11la sua anima\nirrequieta!",
  ["_LavenderCuboneHouseBrunetteGirlPoorCubonesMotherText"] = "Odio quei orribili\nROCKET! La madre\11di quel povero\nCUBONE... é stata\11uccisa cercando di\nfuggire dal TEAM!",
  ["_LavenderCuboneHouseCuboneText"] = "CUBONE: Kyarugoo!",
  ["_LavenderMartBaldingGuyText"] = "Cerco strumenti\nche aumentano le\11abilita' dei\nPOKéMON durante\11una lotta. ATTACCO\nX, DIFESA X,\11VELOCITA' X e\nSPECIAL X. Sai\11dove trovarli?",
  ["_LavenderMartCooltrainerMNuggetText"] = "Ho trovato una\nPEPITA sui monti.\11Pensavo fosse\ninutile, ma l'ho\11venduta a ¥5000!",
  ["_LavenderMartCooltrainerMReviveText"] = "Conosci\nREVITALIZ.?\11Rivitalizza\nqualsiasi POKéMON\11esausto!",
  ["_LavenderPokecenterGentlemanText"] = "Il TEAM ROCKET\nfarebbe di tutto\11per il denaro!",
  ["_LavenderPokecenterGuyText"] = "I CUBONE portano i\nteschi, vero? La\11gente li paga\nmolto!",
  ["_LavenderPokecenterLittleGirlText"] = "Ho visto la madre\ndi CUBONE morire\11sfuggendo al TEAM\nROCKET!",
  ["_LavenderTownCooltrainerMText"] = "Questa citta' é\nnota come il\11cimitero dei\nPOKéMON. Si\11tengono\ncommemorazioni\11nella TORRE.",
  ["_LavenderTownLittleGirlDoYouBelieveInGhostsText"] = "Credi nei\nFANTASMI?",
  ["_LavenderTownLittleGirlHaHaGuessNotText"] = "Ahahah, immagino\ndi no. Quella mano\11bianca sulla tua\nspalla, non é\11vera.",
  ["_LavenderTownLittleGirlSoThereAreBelieversText"] = "Davvero? Quindi ci\nsono credenti...",
  ["_LavenderTownPokemonHouseSignText"] = "CASA POKéMON\nVOLONTARI DI\11LAVANDONIA",
  ["_LavenderTownPokemonTowerSignText"] = "Che le anime dei\nPOKéMON riposino\11TORRE POKéMON",
  ["_LavenderTownSignText"] = "LAVANDONIA La\nnobile citta'\11violacea",
  ["_LavenderTownSilphScopeSignText"] = "Nuovo\nSPETTROSONDA!\11Rendi l'invisibile\nvisibile agli\11occhi! SILPH\nS.P.A.",
  ["_LavenderTownSuperNerdText"] = "I FANTASMI sono\napparsi nella\11TORRE. Credo siano\ngli spiriti dei\11POKéMON uccisi dai\nROCKET.",
  ["_LearnedMove1Text"] = "{RAM:wLearnMoveMonName} ha\nimparato\11{RAM:wStringBuffer}!",
  ["_LickitungDexEntry"] = "La lingua puo'\nessere estesa come\nquella di un\12camaleonte. Lascia\nun formicolio\nquando lecca.",
  ["_LightScreenProtectedText"] = "{USER} é protetto\ndagli attacchi\11speciali!",
  ["_LinedUpText"] = "in fila! Hai vinto\n{RAM:wStringBuffer}\11gettoni!",
  ["_LinkBattleLostText"] = "{PLAYER} ha perso\ncontro {RAM:wTrainerName}!",
  ["_LinkCableHelpText1"] = "CONSIGLI Uso del\nCavo Link",
  ["_LinkCableHelpText2"] = "Quale voce vuoi\nleggere?",
  ["_LinkCableInfoText1"] = "Collegato un GAME\nBOY a un altro,\11parla con\nl'addetto a destra\11in qualsiasi\nCENTRO POKéMON.",
  ["_LinkCableInfoText2"] = "Il COLOSSEO ti\npermette di\11lottare contro un\namico.",
  ["_LinkCableInfoText3"] = "Il CENTRO SCAMBI\nserve per\11scambiare i\nPOKéMON.",
  ["_LinkCanceledText"] = "Il collegamento é\nstato annullato.",
  ["_LoafingAroundText"] = "{RAM:wBattleMonNick}\nbighellona.",
  ["_LoreleisRoomLoreleiAfterBattleText"] = "Sei\nmeglio di quanto\11pensassi! Avanti!\nHai solo\11assaggiato la\npotenza della\11LEGA!",
  ["_LoreleisRoomLoreleiBeforeBattleText"] = "Benvenuto\nalla LEGA POKéMON!\11Io sono LORELEI\ndei SUPER QUATTRO!\11Nessuno mi batte\ncon i POKéMON di\11ghiaccio! Le mosse\ngelide sono\11potenti! I tuoi\nPOKéMON saranno\11alla mia\nmisericordia!\11Ahahah! Sei\npronto?",
  ["_LoreleisRoomLoreleiDontRunAwayText"] = "Voce misteriosa:\nNon scappare!",
  ["_LoreleisRoomLoreleiEndBattleText"] = "Come osi!",
  ["_LoweredItsHeadText"] = "china la testa!",
  ["_MachampDexEntry"] = "Con i suoi forti\nmuscoli, sferra\npugni potenti che\12possono scagliare\nla vittima oltre\nl'orizzonte.",
  ["_MachokeDexEntry"] = "Il suo corpo\nmuscoloso é cosi'\npotente che deve\12indossare una\ncintura per\nregolarne i moti.",
  ["_MachopDexEntry"] = "Adora sviluppare i\nmuscoli. Si allena\nin ogni stile di\12lotta marziale per\ndiventare forte.",
  ["_MadeWhirlwindText"] = "crea un turbine!",
  ["_MagazinesText"] = "Riviste POKéMON!\nQuaderni POKéMON!\11Grafici POKéMON!",
  ["_MagikarpDexEntry"] = "In un lontano\npassato era un po'\npiu' forte di\12questi deboli\ndiscendenti\nesistenti oggi.",
  ["_MagmarDexEntry"] = "Il suo corpo\nbrucia con un\nbagliore arancione\12che gli permette\ndi nascondersi tra\nle fiamme.",
  ["_MagnemiteDexEntry"] = "Usa l'antigravita'\nper restare\nsospeso. Compare\12senza preavviso\nusando TUONOSHOCK\ne simili.",
  ["_MagnetonDexEntry"] = "Formato da vari\nMAGNEMITE uniti.\nCompaiono spesso\12quando le macchie\nsolari si\ninfiammano.",
  ["_MankeyDexEntry"] = "Estremamente\nirritabile. Puo'\nessere docile un\12momento e poi\ninfiltrarsi in un\nattacco furente.",
  ["_MarowakDexEntry"] = "L'osso che porta é\nla sua arma. Lo\nlancia abilmente\12come un boomerang\nper mandare KO i\nbersagli.",
  ["_MartSignText"] = "Ogni strumento\nsoddisfa i\11bisogni! BOTTEGA\nPOKéMON",
  ["_MeowthDexEntry"] = "Adora gli oggetti\ncircolari. Gira di\nnotte per le\12strade in cerca di\nspiccioli caduti.",
  ["_MetapodDexEntry"] = "Questo POKéMON é\nvulnerabile agli\nattacchi finché il\12guscio é morbido,\nesponendo il corpo\ntenero.",
  ["_MewDexEntry"] = "Cosi' raro che\nmolti esperti lo\nritengono un\12miraggio. Pochi lo\nhanno visto in\ntutto il mondo.",
  ["_MewtwoBattleText"] = "Mew!",
  ["_MewtwoDexEntry"] = "Creato da uno\nscienziato dopo\nanni di orribili\12esperimenti di\ningegneria\ngenetica e DNA.",
  ["_MimicLearnedMoveText"] = "{USER} ha imparato\n{RAM:wNameBuffer}!",
  ["_MirrorMoveFailedText"] = "SPECULMOSSA\nfallita!",
  ["_MoltresDexEntry"] = "Noto come\nl'uccello\nleggendario del\12fuoco. Ogni\nbattito delle ali\ncrea un\12abbagliante lampo\ndi fiamme.",
  ["_MonCannotLearnMachineMoveText"] = "{RAM:wNameBuffer} non é\ncompatibile con\11{RAM:wStringBuffer}. Non\npuo' imparare\11{RAM:wStringBuffer}.",
  ["_MonIsTakenOutText"] = "{RAM:wStringBuffer} é\nestratto. Ottenuto\11{RAM:wStringBuffer}.",
  ["_MonWasReleasedText"] = "{RAM:wStringBuffer} é\nliberato fuori.\11Ciao {RAM:wStringBuffer}!",
  ["_MonWasStoredText"] = "{RAM:wStringBuffer} é nel\nBox {RAM:wBoxNumString}.",
  ["_MoneyForWinningText"] = "{PLAYER} vince\n¥{NUM:wAmountMoneyWon,\113 | LEADING_ZEROES\n| LEFT_ALIGN}!",
  ["_MonsStatsFellText"] = "Il {RAM:wStringBuffer} di\n{TARGET}",
  ["_MonsStatsRoseText"] = "Il {RAM:wStringBuffer} di\n{USER}",
  ["_MoveDisabledText"] = "La mossa é\ndisattivata!",
  ["_MoveIsDisabledText"] = "Il {RAM:wNameBuffer} di\n{USER} é\11disattivato!",
  ["_MoveNameText"] = "{RAM:wStringBuffer}!",
  ["_MoveNoPPText"] = "PP esauriti per\nquesta mossa!",
  ["_MoveWasDisabledText"] = "Il {RAM:wNameBuffer} di\n{TARGET} é\11disattivato!",
  ["_MrFujisHouseLittleGirlPokemonAreNiceToHugText"] = "é cosi' caldo! I\nPOKéMON sono belli\11da abbracciare!",
  ["_MrFujisHouseLittleGirlThisIsMrFujisHouseText"] = "Questa é la casa\ndi MR. FUJI. é\11molto gentile!\nCura i POKéMON\11abbandonati e\norfani!",
  ["_MrFujisHouseMrFujiHasMyFluteHelpedYouText"] = "MR. FUJI: Ti é\nutile il mio\11FLAUTO?",
  ["_MrFujisHouseMrFujiIThinkThisMayHelpYourQuestText"] = "MR. FUJI: {PLAYER}.\nLa tua ricerca del\11POKéDEX fallira'\nsenza amore per i\11POKéMON. Penso che\nquesto ti\11aiutera'.",
  ["_MrFujisHouseMrFujiPokeFluteExplanationText"] = "Al suono del\nFLAUTO POKéMON,\11quelli\naddormentati si\11sveglieranno.\nFunziona con tutti\11i POKéMON\ndormienti.",
  ["_MrFujisHouseMrFujiPokeFluteNoRoomText"] = "Devi fare spazio\nper questo!",
  ["_MrFujisHouseMrFujiPokedexText"] = "Lotteria Mensile\nGrandioso Premio!\11Il modulo é...\nSparita! é stata\11ritagliata!",
  ["_MrFujisHouseMrFujiReceivedPokeFluteText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_MrFujisHouseNidorinoText"] = "NIDORINO: Gaoo!",
  ["_MrFujisHousePsyduckText"] = "PSYDUCK: Gwappa!",
  ["_MrFujisHouseSuperNerdMrFujiHadBeenPrayingText"] = "MR. FUJI pregava\nda solo per la\11madre di CUBONE.",
  ["_MrFujisHouseSuperNerdMrFujiIsntHereText"] = "Strano, MR. FUJI\nnon c'é. Dove\11sara' andato?",
  ["_MrMimeDexEntry"] = "Se viene\ninterrotto mentre\nmima, prendera' a\12sberle il\ncolpevole con le\nsue grandi mani.",
  ["_MrPsychicsHouseMrPsychicReceivedTM29Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_MrPsychicsHouseMrPsychicTM29ExplanationText"] = "MT29 é PSICHICO!\nPuo' ridurre le\11abilita' SPECIALI\ndel bersaglio.",
  ["_MrPsychicsHouseMrPsychicTM29NoRoomText"] = "Dove pensi di\nmettere questo?",
  ["_MrPsychicsHouseMrPsychicYouWantedThisText"] = "...Aspetta! Non\ndire una parola!\11Lo volevi!",
  ["_MtMoon1FBewareZubatSign"] = "Attenzione! ZUBAT\né un\11succhiasangue!",
  ["_MtMoon1FCooltrainerF1AfterBattleText"] = "Come\nsi esce da qui?",
  ["_MtMoon1FCooltrainerF1BattleText"] = "Wow!\nQui dentro é molto\11piu' grande di\nquanto credessi!",
  ["_MtMoon1FCooltrainerF1EndBattleText"] = "Oh!\nHo perso!",
  ["_MtMoon1FCooltrainerF2AfterBattleText"] = "Ho\nsentito che ci\11sono fossili molto\nrari qui.",
  ["_MtMoon1FCooltrainerF2BattleText"] = "Cosa?\nAspetto i miei\11amici qui.",
  ["_MtMoon1FCooltrainerF2EndBattleText"] = "Ho\nperso?",
  ["_MtMoon1FHikerAfterBattleText"] = "I\nragazzi come te\11non dovrebbero\nstare qui!",
  ["_MtMoon1FHikerBattleText"] = "UAU! Mi\nhai spaventato!\11Ah, sei solo un\nragazzo!",
  ["_MtMoon1FHikerEndBattleText"] = "Acciderboli!\nSpaventato di\11nuovo!",
  ["_MtMoon1FSuperNerdAfterBattleText"] = "Devo\ntrovare POKéMON\11piu' forti.",
  ["_MtMoon1FSuperNerdBattleText"] = "Cosa!\nNon prendermi alle\11spalle!",
  ["_MtMoon1FSuperNerdEndBattleText"] = "Il mio\nPOKéMON non basta!",
  ["_MtMoon1FYoungster1AfterBattleText"] = "Sono venuto\nqui per fare il\11bullo con le\nragazze.",
  ["_MtMoon1FYoungster1BattleText"] = "Sei venuto\nanche tu a\11esplorare?",
  ["_MtMoon1FYoungster1EndBattleText"] = "Perdere é\nuno schifo!",
  ["_MtMoon1FYoungster2AfterBattleText"] = "Li ho\nvisti! Sono sicuro\11siano del TEAM\nROCKET!",
  ["_MtMoon1FYoungster2BattleText"] = "Uomini\nsospetti nella\11grotta. E tu?",
  ["_MtMoon1FYoungster2EndBattleText"] = "Mi hai\npreso!",
  ["_MtMoon1FYoungster3AfterBattleText"] = "ZUBAT é\ntosto! Ma puo'\11essere utile se ne\ncatturi uno.",
  ["_MtMoon1FYoungster3BattleText"] = "Attraversa\nla grotta per\11arrivare a\nCELESTOPOLI!",
  ["_MtMoon1FYoungster3EndBattleText"] = "Ho perso.",
  ["_MtMoonB2FDomeFossilYouWantText"] = "Vuoi il Fossile\nDome?",
  ["_MtMoonB2FHelixFossilYouWantText"] = "Vuoi il Fossile\nHelix?",
  ["_MtMoonB2FReceivedFossilText"] = "{PLAYER} ottiene\n{RAM:wStringBuffer}!",
  ["_MtMoonB2FRocket1AfterBattleText"] = "Mi hai\nfatto arrabbiare!\11Il TEAM ti\nmettera' al bando!",
  ["_MtMoonB2FRocket1BattleText"] = "Il TEAM\nROCKET trovera' i\11fossili, li\nrivendera' per\11fare soldi!",
  ["_MtMoonB2FRocket1EndBattleText"] = "Argh! Ora\nsono furioso!",
  ["_MtMoonB2FRocket2AfterBattleText"] = "Mannaggia!\nI miei soci non la\11passeranno liscia!",
  ["_MtMoonB2FRocket2BattleText"] = "Noi del\nTEAM ROCKET siamo\11gangster POKéMON!",
  ["_MtMoonB2FRocket2EndBattleText"] = "Ho\nrovinato tutto!",
  ["_MtMoonB2FRocket3AfterBattleText"] = "Se trovi\nun fossile,\11dammelo e\nsparisci!",
  ["_MtMoonB2FRocket3BattleText"] = "Facciamo\nun affare grosso\11qui! Sparisci,\nmoccioso!",
  ["_MtMoonB2FRocket3EndBattleText"] = "Vedo che\nsei bravo.",
  ["_MtMoonB2FRocket4AfterBattleText"] = "I POKéMON\nvivevano qui molto\11prima dell'uomo.",
  ["_MtMoonB2FRocket4BattleText"] = "I bambini\nnon dovrebbero\11seccare gli\nadulti!",
  ["_MtMoonB2FRocket4EndBattleText"] = "Che\nrabbia!",
  ["_MtMoonB2FSuperNerdOkIllShareText"] = "Va bene! Lo\ndivideremo!",
  ["_MtMoonB2FSuperNerdThenThisIsMineText"] = "D'accordo. Allora\nquesto é mio!",
  ["_MtMoonB2FSuperNerdTheresAPokemonLabText"] = "Lontano, all'ISOLA\nCANNELLA, c'é un\11LABORATORIO\nPOKéMON. Studiano\11la rigenerazione\ndei fossili.",
  ["_MtMoonB2FSuperNerdTheyreBothMineText"] = "Ehi, ferma! Li ho\ntrovati io! Sono\11entrambi miei!",
  ["_MtMoonB2FYouHaveNoRoomText"] = "Senti, non hai\nspazio per questo.",
  ["_MtMoonB2fSuperNerdEachTakeOneText"] = "Ne prendiamo uno a\ntesta! Niente\11ingordigia!",
  ["_MtMoonPokecenterBenchGuyText"] = "Se hai troppi\nPOKéMON, puoi\11depositarli al PC!",
  ["_MtMoonPokecenterGentlemanText"] = "Il TEAM ROCKET\nattacca i\11cittadini di\nCELESTOPOLI... Il\11TEAM ROCKET é\nsempre in prima\11pagina!",
  ["_MtMoonPokecenterMagikarpSalesmanIGotADealText"] = "UOMO: Salve! Ho un\naffare proprio per\11te! Ti do un\nmagnifico MAGIKARP\11per soli ¥500! Che\nne dici?",
  ["_MtMoonPokecenterMagikarpSalesmanNoMoneyText"] = "Ti servono piu'\nsoldi di cosi'!",
  ["_MtMoonPokecenterMagikarpSalesmanNoRefundsText"] = "UOMO: Be', io non\nfaccio rimborsi!",
  ["_MtMoonPokecenterMagikarpSalesmanNoText"] = "No? Lo faccio solo\ncome favore per\11te!",
  ["_MtMoonPokecenterYoungsterText"] = "Ho 6 POKé BALL\npronte alla\11cintura. Al\nmassimo puoi\11portare 6 POKéMON.",
  ["_MukDexEntry"] = "Fittamente coperto\ndi melma vile e\ndisgustosa. Molto\12tossico, anche le\nsue orme lasciano\nveleno.",
  ["_MultiHitText"] = "Colpisce il nemico\n{NUM:wPlayerNumHits,\111, 1} volte!",
  ["_Museum1FGamblerText"] = "Questo é un\nmagnifico fossile!",
  ["_Museum1FOldAmberText"] = "L'AMBRA é lucida e\ndorata!",
  ["_Museum1FScientist1AmberIsFossilizedTreeSapText"] = "L'AMBRA é linfa\nd'albero fossile.",
  ["_Museum1FScientist1ComeAgainText"] = "Torna presto!",
  ["_Museum1FScientist1DoYouKnowWhatAmberIsText"] = "Non puoi\nintrufolarti dal\11retro! Oh,\ninsomma! Sai cos'é\11l'AMBRA?",
  ["_Museum1FScientist1DontHaveEnoughMoneyText"] = "Non hai abbastanza\nsoldi.",
  ["_Museum1FScientist1GoToOtherSideText"] = "Prego, passa\ndall'altra parte!",
  ["_Museum1FScientist1TakePlentyOfTimeText"] = "Prenditi tutto il\ntempo per vederlo!",
  ["_Museum1FScientist1ThankYouText"] = "Ecco, ¥50! Grazie!",
  ["_Museum1FScientist1TheresALabSomewhereText"] = "C'é un laboratorio\nda qualche parte\11che cerca di\nresuscitare\11POKéMON antichi\ndall'AMBRA.",
  ["_Museum1FScientist1WouldYouLikeToComeInText"] = "Il biglietto costa\n¥50 per i bambini.\11Vuoi entrare?",
  ["_Museum1FScientist2GetTheOldAmberCheckText"] = "Ssh! Fai\nanalizzare l'AMBRA\11ANTICA!",
  ["_Museum1FScientist2ReceivedOldAmberText"] = "{PLAYER} riceve\nAMBRA ANTICA!",
  ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "Ssh! Credo che\nquesto pezzo di\11AMBRA contenga DNA\ndi POKéMON!\11Sarebbe fantastico\nresuscitare un\11POKéMON da esso!\nMa i miei colleghi\11mi ignorano!\nPercio' ho un\11favore da\nchiederti: portalo\11a un LABORATORIO\nPOKéMON!",
  ["_Museum1FScientist2YouDontHaveSpaceText"] = "Non hai spazio per\nquesto!",
  ["_Museum1FScientist3Text"] = "Siamo fieri di due\nfossili di\11rarissimi POKéMON\npreistorici!",
  ["_Museum2FBrunetteGirlText"] = "Voglio un PIKACHU!\né cosi' carino! Ho\11chiesto a papa' di\ncatturarmene uno!",
  ["_Museum2FGrampsText"] = "20 luglio 1969! Il\n1° allunaggio! Ho\11comprato una\ntelevisione a\11colori per\nvederlo!",
  ["_Museum2FHikerText"] = "Si', un PIKACHU\narrivera' presto!",
  ["_Museum2FMoonStoneSignText"] = "Meteorite caduto\nnel MONTE LUNA.\11(PIETRALUNARE?)",
  ["_Museum2FScientistText"] = "Abbiamo una mostra\nspaziale in corso.",
  ["_Museum2FSpaceShuttleSignText"] = "NAVETTA SPAZIALE\nCOLUMBIA",
  ["_Museum2FYoungsterText"] = "PIETRALUNARE? Cosa\nc'é di cosi'\11speciale?",
  ["_MustRechargeText"] = "{USER} deve\nricaricarsi!",
  ["_NameRatersHouseNameRaterATrulyImpeccableNameText"] = "{RAM:wNameBuffer}, eh? é\nun nome davvero\11impeccabile! Abbi\ncura di\11{RAM:wNameBuffer}!",
  ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "Va bene! Torna\nquando vuoi!",
  ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "{RAM:wNameBuffer}, eh? é\nun soprannome\11decente! Ma vuoi\nche gli dia un\11nome piu' carino?\nChe ne pensi?",
  ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "Ok! Questo POKéMON\nora si chiama\11{RAM:wBuffer}! é un\nnome migliore di\11prima!",
  ["_NameRatersHouseNameRaterWantMeToRateText"] = "Salve, salve! Sono\nil GIUDICE\11ONORARIO! Vuoi che\nvaluti i\11soprannomi dei\ntuoi POKéMON?",
  ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "Va bene! Come lo\nchiamiamo?",
  ["_NameRatersHouseNameRaterWhichPokemonText"] = "Quale POKéMON deve\nessere esaminato?",
  ["_NeedYourPokemonText"] = "Ok. Ci serve il\ntuo POKéMON.",
  ["_NewBadgeRequiredText"] = "No! Serve una\nnuova MEDAGLIA.",
  ["_NewBicycleText"] = "Una nuova e\nlucente\11BICICLETTA!",
  ["_NidokingDexEntry"] = "Usa la potente\ncoda in battaglia\nper schiacciare,\12stringere e infine\nrompere le ossa\nalla preda.",
  ["_NidoqueenDexEntry"] = "Le sue squame dure\noffrono una solida\nprotezione. Usa la\12sua stazza per\nsferrare potenti\nmosse.",
  ["_NidoranFDexEntry"] = "Sebbene piccolo, i\nsuoi aculei\nvelenosi rendono\12questo POKéMON\npericoloso. La\nfemmina ha corna.",
  ["_NidoranMDexEntry"] = "Irridisce le\norecchie per\npercepire i\12pericoli. Piu' le\ncorna sono grandi,\npiu' il veleno\12secreto é potente.",
  ["_NidorinaDexEntry"] = "Il corno della\nfemmina cresce\nlentamente.\12Preferisce\nattacchi fisici\ncome graffi e\12morsi.",
  ["_NidorinoDexEntry"] = "Un POKéMON\naggressivo e\nrapido\12nell'attaccare. Il\ncorno sulla testa\nsecreta un veleno\12potente.",
  ["_NinetalesDexEntry"] = "Molto intelligente\ne vendicativo.\nAfferrare una\12delle sue code\npuo' causare una\nmaledizione\12millenaria.",
  ["_NoCyclingAllowedHereText"] = "Qui non si puo'\nusare la bici.",
  ["_NoEffectText"] = "Non ha effetto!",
  ["_NoMonText"] = "Cosa? Non ci sono\nPOKéMON qui!",
  ["_NoMoreRoomForItemText"] = "Spazio esaurito\nper gli strumenti!",
  ["_NoMovesLeftText"] = "{RAM:wBattleMonNick} non ha\npiu' mosse!",
  ["_NoNibbleText"] = "Neanche\nun'abboccata!",
  ["_NoRoomToStoreText"] = "Nessun spazio per\ndepositare\11strumenti.",
  ["_NoRunningText"] = "No! Non si puo'\nfuggire da una\11lotta fra\nallenatori!",
  ["_NoSurfingHereText"] = "Non si puo' USARE\nSURF su {RAM:wNameBuffer}\11qui!",
  ["_NoTrade1Text"] = "Uffa! Vabbé...",
  ["_NoTrade2Text"] = "Be', se non lo\nvuoi tu...",
  ["_NoTrade3Text"] = "Che peccato.",
  ["_NoWillText"] = "Manca la voglia di\ncombattere!",
  ["_NotEnoughCoinsSlotMachineText"] = "Gettoni\ninsufficienti!",
  ["_NotHealthyEnoughText"] = "Non é abbastanza\nsalutare.",
  ["_NotThisTimeText"] = "Non questa volta!",
  ["_NotVeryEffectiveText"] = "Non é molto\nefficace...",
  ["_NothingHappenedText"] = "Non é accaduto\nnulla!",
  ["_NothingHereText"] = "Sembra che non ci\nsia nulla.",
  ["_NothingStoredText"] = "Non c'é nulla\ndepositato.",
  ["_NothingToCutText"] = "Non c'é nulla da\nTAGLIARE!",
  ["_NothingToDepositText"] = "Non hai nulla da\ndepositare.",
  ["_OHKOText"] = "KO in un colpo!",
  ["_OKExclamationText"] = "OK!",
  ["_OakLabEmailText"] = "C'é un messaggio\ndi posta qui! ...\11Chiamata a tutti\ngli allenatori di\11POKéMON! I\nmigliori della\11LEGA POKéMON sono\npronti a sfidare\11chiunque! Porta i\ntuoi migliori\11POKéMON e scopri\nil tuo livello!\11SEDE LEGA POKéMON\nALTOPIANO INDACO\11PS: PROF. OAK,\npassa a trovarci!\11...",
  ["_OakSpeechText1"] = "Salve! Benvenuto\nnel mondo dei\11POKéMON! Mi chiamo\nOAK! Per tutti\11sono il PROF.\nPOKéMON!",
  ["_OakSpeechText2A"] = "Questo mondo é\ninabitato da\11creature dette\nPOKéMON!",
  ["_OakSpeechText2B"] = "Per alcuni i\nPOKéMON sono\11animali domestici.\nAltri li usano per\11lottare. Io...\nStudio i POKéMON\11come professione.",
  ["_OakSpeechText3"] = "{PLAYER}! La tua\nleggenda sta per\11iniziare! Un mondo\ndi sogni e\11avventure ti\nattende con i\11POKéMON! Andiamo!",
  ["_OaksAideComeBackText"] = "Oh, capisco.\nQuando avrai\11{NUM:hOaksAideRequirement,\n1, 3} specie,\11torna a prendere\n{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideGotItemText"] = "{PLAYER} ottiene\n{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "Ottimo! Hai\ncatturato\11{NUM:hOaksAideNumMonsOwned,\n1, 3} specie di\11POKéMON!\nComplimenti! Ecco\11a te!",
  ["_OaksAideHiText"] = "Ciao! Ti ricordi\ndi me? Sono\11l'AIUTO del PROF.\nOAK! Se hai\11catturato\n{NUM:hOaksAideRequirement,\111, 3} specie di\nPOKéMON, dovrei\11darti {RAM:wOaksAideRewardItemName}!\nAllora, {PLAYER}!\11Hai catturato\nalmeno\11{NUM:hOaksAideRequirement,\n1, 3} specie?",
  ["_OaksAideNoRoomText"] = "Oh! Vedo che non\nhai alcuno spazio\11per {RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Vediamo... Oh no!\nHai catturato solo\11{NUM:hOaksAideNumMonsOwned,\n1, 3} specie! Te\11ne servono\n{NUM:hOaksAideRequirement,\111, 3} per avere\n{RAM:wOaksAideRewardItemName}.",
  ["_OaksLabGirlText"] = "Il PROF. OAK é la\nmassima autorita'\11sui POKéMON! Molto\nallenatori lo\11stimano molto!",
  ["_OaksLabGivePokeballsExplanationText"] = "Quando appare un\nPOKéMON selvatico,\11é tutto valido.\nLancia una POKé\11BALL e prova a\ncatturarlo! Non\11funziona sempre,\npero'. Un POKéMON\11in salute puo'\nfuggire. Ci vuole\11fortuna!",
  ["_OaksLabLastMonText"] = "Questo é l'ultimo\nPOKéMON di OAK!",
  ["_OaksLabMonEnergeticText"] = "Questo POKéMON é\ndavvero pieno di\11energia!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "OAK: Vieni a\ntrovarmi a volte.\11Voglio sapere come\nprocede il tuo\11POKéDEX.",
  ["_OaksLabOak1DeliverParcelText"] = "OAK: Oh, {PLAYER}!\nCome sta il mio\11vecchio POKéMON?\nBe', sembra\11proprio che ti\npiaccia. Devi\11avere un taleento\ncome allenatore!\11Cosa? Hai qualcosa\nper me? {PLAYER}\11consegna il PACCO\ndi OAK.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "OAK: Che bello\nvederti! Come va\11il POKéDEX? Fammi\ndare un'occhiata!",
  ["_OaksLabOak1ParcelThanksText"] = "Ah! é la POKé BALL\npersonalizzata che\11ho ordinato!\nGrazie!",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "I POKéMON di tutto\nil mondo ti\11attendono,\n{PLAYER}!",
  ["_OaksLabOak1RaiseYourYoungPokemonText"] = "OAK: {PLAYER},\ncresci il tuo\11giovane POKéMON\nfacendolo lottare!",
  ["_OaksLabOak1ReceivedPokeballsText"] = "OAK: Non puoi\navere dati\11dettagliati\nvedendoli e basta.\11Devi catturarli!\nUsa questi per i\11POKéMON selvatici.\n{PLAYER} riceve 5\11POKé BALL!",
  ["_OaksLabOak1WhichPokemonDoYouWantText"] = "OAK: Dunque,\n{PLAYER}, quale\11POKéMON vuoi?",
  ["_OaksLabOak1YourPokemonCanFightText"] = "OAK: Se appare un\nPOKéMON selvatico,\11il tuo puo'\nlottare contro di\11esso!",
  ["_OaksLabOak2Text"] = "?",
  ["_OaksLabOakBePatientText"] = "OAK: Pazienza!\nAnche {RIVAL} ne\11avra' uno!",
  ["_OaksLabOakChooseMonText"] = "OAK: {RIVAL}?\nLasciami\11pensare... Ah, é\nvero, ti avevo\11detto di venire!\nAspetta! Ecco,\11{PLAYER}! Ci sono 3\nPOKéMON! Haha!\11Sono dentro le\nPOKé BALL. Ero un\11serio allenatore\nda giovane! Alla\11mia eta' me ne\nrestano 3, ma uno\11é tuo! Scegli!",
  ["_OaksLabOakDontGoAwayYetText"] = "OAK: Ehi! Non te\nne andare ancora!",
  ["_OaksLabOakGotPokedexText"] = "OAK: {PLAYER} e\n{RIVAL}! Prendete\11questi! {PLAYER}\nriceve il POKéDEX\11da OAK!",
  ["_OaksLabOakIHaveARequestText"] = "OAK: Ah, giusto!\nHo una richiesta\11per voi due.",
  ["_OaksLabOakMyInventionPokedexText"] = "Sulla scrivania\nc'é la mia\11invenzione, il\nPOKéDEX! Registra\11in automatico i\ndati dei POKéMON\11visti o catturati!\né un'enciclopedia\11hi-tech!",
  ["_OaksLabOakThatWasMyDreamText"] = "Creare una guida\ncompleta di tutti\11i POKéMON...\nQuesto era il\11sogno mio! Ma sono\ntroppo vecchio!\11Voglio che voi due\nrealizziate il mio\11sogno! Forza,\nmuovetevi! Questa\11é una grande\nimpresa!",
  ["_OaksLabPokedexText"] = "é un'enciclopedia,\nma le pagine sono\11bianche!",
  ["_OaksLabReceivedMonText"] = "{PLAYER} riceve un\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: Si'! Non\nsono fantastico?",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: Nonno!\nSono stufo di\11aspettare!",
  ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL}: Heh, non\nho bisogno di fare\11l'avido come te!\nScegli pure,\11{PLAYER}!",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: Ehi\n{PLAYER}! Il nonno\11non c'é!",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}: Nonno!",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "COSA? Incredibile!\nHo scelto il\11POKéMON sbagliato!",
  ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}: Prendero'\nquesto, allora!",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: Aspetta\n{PLAYER}! Vediamo i\11nostri POKéMON!\nForza, ti sfido!",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}: D'accordo\nnonno! Faccio io!\11{PLAYER}, odio\ndirlo, ma non mi\11servi! Lo so!\nPrestero' una\11MAPPA CITTA' da\nmia sorella! Le\11diro' di non\ndartela, {PLAYER}!\11Ahahah!",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Il mio\nPOKéMON sembra\11molto piu' forte.",
  ["_OaksLabRivalReceivedMonText"] = "{RIVAL} riceve un\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}: Ok! Faro'\nlottare il mio\11POKéMON per\nrinforzarlo!\11{PLAYER}! Nonno! A\npresto!",
  ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}: Ehi!\nNonno! E io?",
  ["_OaksLabRivalWhatDidYouCallMeForText"] = "{RIVAL}: Perché mi\nhai chiamato?",
  ["_OaksLabScientistText"] = "Studio i POKéMON\ncome aiuto del\11PROF. OAK.",
  ["_OaksLabThoseArePokeBallsText"] = "Quelle sono POKé\nBALL. Contengono\11POKéMON!",
  ["_OaksLabYouWantBulbasaurText"] = "Dunque! Vuoi il\nPOKéMON pianta,\11BULBASAUR?",
  ["_OaksLabYouWantCharmanderText"] = "Dunque! Vuoi il\nPOKéMON fuoco,\11CHARMANDER?",
  ["_OaksLabYouWantSquirtleText"] = "Dunque! Vuoi il\nPOKéMON acqua,\11SQUIRTLE?",
  ["_OddishDexEntry"] = "Di giorno tiene il\nviso sepolto nel\nterreno. Di notte\12vaga per seminare\ni suoi semi.",
  ["_OhFineThenText"] = "Oh, va bene.",
  ["_OlderFileWillBeErasedText"] = "Il vecchio file\nsara' cancellato\11per salvare. OK?",
  ["_OmanyteDexEntry"] = "Sebbene estinto da\ntempo, in rari\ncasi puo' essere\12rigenerato dai\nfossili con la\ngenetica.",
  ["_OmastarDexEntry"] = "Un POKéMON\npreistorico\nestinto perché la\12pesante conchiglia\ngli impediva di\ncatturare prede.",
  ["_OnceReleasedText"] = "Una volta\nliberato,\11{RAM:wStringBuffer} é perso\nper sempre. OK?",
  ["_OneMoreGoSlotMachineText"] = "Un altro giro?",
  ["_OneTwoAndText"] = "1, 2 e...",
  ["_OnixDexEntry"] = "Crescendo, le\nparti in pietra\ndel corpo si\12induriscono\ndiventando simili\na un diamante\12nero.",
  ["_OopsYouDontHaveEnoughRoomText"] = "Ops! Non hai\nabbastanza spazio.",
  ["_OutOfCoinsSlotMachineText"] = "Acciderboli!\nGettoni esauriti!",
  ["_OutOfSafariBallsText"] = "PA: Din-don! Le\nSAFARI BALL sono\11finite!",
  ["_PPIncreasedText"] = "I PP di {RAM:wStringBuffer}\naumentano.",
  ["_PPMaxedOutText"] = "I PP di {RAM:wStringBuffer}\nsono al massimo.",
  ["_PPRestoredText"] = "I PP sono stati\nripristinati.",
  ["_PalletTownFisherText"] = "La tecnologia é\nincredibile! Ora\11puoi archiviare e\nrichiamare oggetti\11e POKéMON come\ndati via PC!",
  ["_PalletTownGirlText"] = "Allevo anch'io i\nPOKéMON! Quando\11saranno forti,\npotranno\11proteggermi!",
  ["_PalletTownOakHeyWaitDontGoOutText"] = "OAK: Ehi! Aspetta!\nNon uscire!",
  ["_PalletTownOakItsUnsafeText"] = "OAK: é pericoloso!\nI POKéMON\11selvatici vivono\nnell'erba! Ti\11serve un tuo\nPOKéMON per\11proteggerti. Lo\nso! Vieni con me!",
  ["_PalletTownOaksLabSignText"] = "LABORATORIO DI\nRICERCA POKéMON DI\11OAK",
  ["_PalletTownPlayersHouseSignText"] = "Casa di {PLAYER}",
  ["_PalletTownRivalsHouseSignText"] = "Casa di {RIVAL}",
  ["_PalletTownSignText"] = "BIANCAVILLA Le\nsfumature di un\11nuovo viaggio!",
  ["_ParalyzedMayNotAttackText"] = "{TARGET} é\nparalizzato! Puo'\11non attaccare!",
  ["_ParasDexEntry"] = "Scava per\nsucchiare le\nradici. I funghi\12sulla schiena\ncrescono traendo\nnutrimento\12dall'ospite.",
  ["_ParasectDexEntry"] = "Una coppia di\nparassiti dove il\nfungo ha preso il\12sopravvento\nsull'ospite.\nPreferisce luoghi\12umidi.",
  ["_ParlyzHealText"] = "La paralisi di\n{RAM:wNameBuffer}\11svanisce!",
  ["_PartyMenuBattleText"] = "Quale\nPOKéMON mandare in\11campo?",
  ["_PartyMenuItemUseText"] = "Usare lo strumento\nsu quale POKéMON?",
  ["_PartyMenuNormalText"] = "Scegli un POKéMON.",
  ["_PartyMenuSwapMonText"] = "Spostare il\nPOKéMON dove?",
  ["_PartyMenuUseTMText"] = "Usare la MT su\nquale POKéMON?",
  ["_PersianDexEntry"] = "Sebbene il pelo\nhia molti\nammiratori, é\12difficile da\nallevare per la\nsua indole\12capricciosa.",
  ["_PewterCityCooltrainerFText"] = "Si dice che i\nCLEFAIRY arrivino\11dalla luna! Sono\napparsi dopo che\11la PIETRALUNARE é\ncaduta sul monte.",
  ["_PewterCityCooltrainerMText"] = "Non ci sono molti\nallenatori seri\11qui! Sono come\nPIGLIAMOSCHE, ma\11BROCK di PLUMOPOLI\né davvero in\11gamba!",
  ["_PewterCityGymSignText"] = "PLUMOPOLI PALESTRA\nPOKéMON\11CAPOPALESTRA:\nBROCK Il roccioso\11allenatore\nPOKéMON!",
  ["_PewterCityMuseumSignText"] = "MUSEO DELLA\nSCIENZA DI\11PLUMOPOLI",
  ["_PewterCityPokecenterGuyText"] = "Yawn! Quando\nJIGGLYPUFF canta,\11i POKéMON si\naddormentano...\11...Anche io...\nFiiu...",
  ["_PewterCityPoliceNoticeSignText"] = "AVVISO! Dei ladri\nrubano fossili\11POKéMON al MONTE\nLUNA! Chiamate la\11polizia per info!",
  ["_PewterCitySignText"] = "PLUMOPOLI La\ncitta' dal grigio\11roccioso",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "Hai visitato il\nMUSEO?",
  ["_PewterCitySuperNerd1ItsRightHereText"] = "é proprio qui! Si\npaga per entrare,\11ma ne vale la\npena! Ci vediamo!",
  ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "Non erano\nfantastici i\11fossili del MONTE\nLUNA?",
  ["_PewterCitySuperNerd1YouHaveToGoText"] = "Davvero? Devi\nassolutamente\11andarci!",
  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "Psssst! Sai cosa\nsto facendo?",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "Spruzzo REPELLENTE\nper tenere i\11POKéMON lontani\ndal giardino!",
  ["_PewterCitySuperNerd2ThatsRightText"] = "Esatto! é un duro\nlavoro!",
  ["_PewterCityTrainerTipsText"] = "CONSIGLI Ogni\nPOKéMON che prende\11parte alla lotta\nguadagna ESP!",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "Se hai stoffa, va'\na sfidare BROCK!",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "Sei un allenatore,\nvero? BROCK cerca\11nuovi sfidanti!\nSeguimi!",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "Questa é una\nMEDAGLIA ufficiale\11della LEGA\nPOKéMON! I POKéMON\11di chi la possiede\nsono piu' forti!\11Ora puoi usare\nFLASH in ogni\11momento!",
  ["_PewterGymBrockPostBattleAdviceText"] = "Ci sono allenatori\ndi ogni tipo nel\11mondo! Sembri\nmolto dotato come\11allenatore\nPOKéMON! Vai alla\11PALESTRA di\nCELESTOPOLI a\11testare le\nabilita'!",
  ["_PewterGymBrockPreBattleText"] = "Io sono\nBROCK! Sono il\11CAPOPALESTRA di\nPLUMOPOLI! Credo\11in una difesa di\nroccia e nella\11determinazione!\nPercio' i miei\11POKéMON sono tutti\ndi tipo roccia!\11Vuoi ancora\nsfidarmi? Bene!\11Mostrami il tuo\nmeglio!",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "Ti ho\nsottovalutato.\11Come prova della\nvittoria, ecco la\11MEDAGLIA SASSO!\n{PLAYER} riceve la\11MEDAGLIA SASSO!",
  ["_PewterGymBrockWaitTakeThisText"] = "Aspetta! Prendi\nquesto con te!",
  ["_PewterGymCooltrainerMAfterBattleText"] = "Sei\nforte, ma non\11quanto BROCK!",
  ["_PewterGymCooltrainerMBattleText"] = "Fermati\nli', ragazzino!\11Sei ancora a anni\nluce da BROCK!",
  ["_MisReadPlaceholder"] = "",
  ["_PewterGymCooltrainerMEndBattleText"] = "Maledizione!\nAnni luce mi\11separano da BROCK!",
  ["_PewterGymGuideAdviceText"] = "Il 1° POKéMON in\ncampo é in cima\11alla LISTA\nPOKéMON! Cambiando\11l'ordine dei\nPOKéMON, le lotte\11saranno piu'\nfacili!",
  ["_PewterGymGuideBeginAdviceText"] = "Bene! Diamo inizio\nallo spettacolo!",
  ["_PewterGymGuideFreeServiceText"] = "é un servizio\ngratuito! Diamo\11inizio alle danze!",
  ["_PewterGymGuidePostBattleText"] = "Proprio\ncome pensavo! Hai\11stoffa da\ncampione!",
  ["_PewterGymGuidePreAdviceText"] = "Ehila'! Si vede\nche hai la stoffa\11del campione! Non\nsono un\11allenatore, ma so\ncome vincere! Ti\11portero' in alto!",
  ["_PewterGymReceivedTM34Text"] = "{PLAYER} riceve\nMT34!",
  ["_PewterGymTM34NoRoomText"] = "Non hai spazio per\nquesto!",
  ["_PewterMartSuperNerdText"] = "Cose buone possono\ncapitare se allevi\11con diligenza i\nPOKéMON, anche\11quelli deboli!",
  ["_PewterMartYoungsterText"] = "Un vecchio losco\nmi ha fatto\11comprare uno\nstrano POKéMON\11pesce! é\ndebolissimo e é\11costato ¥500!",
  ["_PewterNidoranHouseLittleBoyText"] = "NIDORAN cuccia!",
  ["_PewterNidoranHouseMiddleAgedManText"] = "Il nostro POKéMON\nviene da uno\11scambio, é duro.\nUn forestiero é un\11POKéMON preso\ntramite scambio.\11Cresce in fretta,\nma puo' ignorare\11un allenatore\ninesperto in\11lotta! Se solo\navessimo\11medaglie...",
  ["_PewterNidoranHouseNidoranText"] = "NIDORAN: Bowbow!",
  ["_PewterPokecenterGentlemanText"] = "Cosa!? Il TEAM\nROCKET é al MONTE\11LUNA? Eh? Sono al\ntelefono!\11Sparisci!",
  ["_PewterPokecenterJigglypuffText"] = "JIGGLYPUFF: Puu\npupuu!",
  ["_PewterSpeechHouseGamblerText"] = "I POKéMON imparano\nnuove tecniche\11crescendo! Ma\nalcune mosse vanno\11insegnate\ndall'allenatore!",
  ["_PewterSpeechHouseYoungsterText"] = "I POKéMON sono\npiu' facili da\11catturare se\nferiti o\11addormentati! Ma\nnon é una certezza\11assoluta!",
  ["_PickUpPayDayMoneyText"] = "{PLAYER} raccoglie\n¥{NUM:wTotalPayDayMoney,\113 | LEADING_ZEROES\n| LEFT_ALIGN}!",
  ["_PidgeotDexEntry"] = "A caccia, sfiora\nl'acqua ad alta\nvelocita' per\12ghermire prede\ndistratte come\nMAGIKARP.",
  ["_PidgeottoDexEntry"] = "Molto protettivo\nverso la sua ampia\narea, questo\12POKéMON becca\nferocemente ogni\nintruso.",
  ["_PidgeyDexEntry"] = "Comune nei boschi\ne foreste. Muove\nle ali a livello\12del suolo per\nsollevare sabbia\naccecante.",
  ["_PikachuDexEntry"] = "Quando diversi\nPOKéMON si\nraccolgono, la\12loro elettricita'\npuo' causare forti\ntempeste di\12fulmini.",
  ["_PinsirDexEntry"] = "Se non riesce a\nschiacciare la\nvittima tra le\12chele, la agita e\nla scaglia\nlontano.",
  ["_PlaySlotMachineText"] = "Una slot machine!\nVuoi giocare?",
  ["_PlayedFluteHadEffectText"] = "{PLAYER} suona il\nFLAUTO POKéMON.",
  ["_PlayedFluteNoEffectText"] = "Suonato il FLAUTO\nPOKéMON. Che\11motivetto\norecchiabile!",
  ["_PlayerBlackedOutText"] = "{PLAYER} non ha\npiu' POKéMON\11validi! {PLAYER} é\nk.o.!",
  ["_PlayerBlackedOutText2"] = "{PLAYER} non ha\npiu' POKéMON\11validi! {PLAYER} é\nk.o.!",
  ["_PlayerMon1Text"] = "{RAM:wBattleMonNick}!",
  ["_PlayerMon2Text"] = "{RAM:wBattleMonNick}",
  ["_PlayerMonFaintedText"] = "{RAM:wBattleMonNick} é\nesausto!",
  ["_PleaseWaitText"] = "OK, attendi solo\nun momento.",
  ["_PoisonedText"] = "{TARGET} é stato\navvelenato!",
  ["_PokeCenterSignText"] = "Cura i tuoi\nPOKéMON! CENTRO\11POKéMON",
  ["_PokemartAnythingElseText"] = "Posso fare\nqualcos'altro?",
  ["_PokemartBoughtItemText"] = "Eccolo a te!\nGrazie!",
  ["_PokemartBuyingGreetingText"] = "Prenditi tutto il\ntempo che vuoi.",
  ["_PokemartGreetingText"] = "Salve! Posso\naiutarti?",
  ["_PokemartItemBagEmptyText"] = "Non hai nulla da\nvendere.",
  ["_PokemartItemBagFullText"] = "Non puoi portare\naltri strumenti.",
  ["_PokemartNotEnoughMoneyText"] = "Non hai abbastanza\nsoldi.",
  ["_PokemartTellBuyPriceText"] = "{RAM:wStringBuffer}?\nFaranno\11¥{NUM:hMoney, 3 |\nLEADING_ZEROES |\11LEFT_ALIGN}. Va\nbene?",
  ["_PokemartTellSellPriceText"] = "Posso darti\n¥{NUM:hMoney, 3 |\11LEADING_ZEROES |\nLEFT_ALIGN} per\11questo.",
  ["_PokemartThankYouText"] = "Grazie!",
  ["_PokemartUnsellableItemText"] = "Non posso dare un\nprezzo a questo.",
  ["_PokemonBooksText"] = "Pieno zeppo di\nlibri sui POKéMON!",
  ["_PokemonCenterFarewellText"] = "Speriamo di\nrivederti presto!",
  ["_PokemonCenterWelcomeText"] = "Benvenuti al\nnostro CENTRO\11POKéMON!\nRistabiliamo la\11piena forma dei\ntuoi POKéMON!",
  ["_PokemonFaintedText"] = "{RAM:wNameBuffer} é\nesausto!",
  ["_PokemonFanClubBagFullText"] = "Fai spazio per\nquesto!",
  ["_PokemonFanClubChairFinalText"] = "Salve, {PLAYER}!\nSei tornato per\11parlare dei miei\nPOKéMON? No? Che\11peccato!",
  ["_PokemonFanClubChairmanIntroText"] = "Sono il presidente\ndel Fan Club! Ho\11raccolto oltre 100\nPOKéMON! Sono\11molto esigente in\nfatto di POKéMON!\11Quindi... Sei\nvenuto a sentire\11la mia storia?",
  ["_PokemonFanClubChairmanStoryText"] = "Bene! Ascoltate\nallora! Il mio\11RAPIDASH... é...\ncarino...\11adorabile...\nintelligente...\11splendido...\ngentile... lo\11adoro!\nAbbracciarlo...\11quando riposa...\ncaldo e\11coccoloso...\nspettacolare...\11...Ops! Guarda\nl'ora! Ti ho\11trattenuto troppo!\nGrazie\11dell'ascolto!\nPrendi questo!",
  ["_PokemonFanClubExplainBikeVoucherText"] = "Scambialo per una\nBICICLETTA! Non\11temere, il mio\nFEAROW mi porta\11ovunque volando!\nQuindi non mi\11serve la BICI!\nSpero ti piaccia\11andare in bici!",
  ["_PokemonFanClubNoStoryText"] = "Oh. Torna quando\nvorrai ascoltare\11la mia storia!",
  ["_PokemonFanClubPikachuFanBetterText"] = "Uffa! Il mio\nPIKACHU é il\11doppio piu'\ncarino!",
  ["_PokemonFanClubPikachuFanNormalText"] = "Non ammiri la coda\ndel mio PIKACHU?",
  ["_PokemonFanClubPikachuText"] = "PIKACHU: Chu!\nPikachu!",
  ["_PokemonFanClubReceivedBikeVoucherText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_PokemonFanClubReceptionistText"] = "Il nostro\npresidente parla\11sempre di POKéMON.",
  ["_PokemonFanClubSeelFanBetterText"] = "Oh cielo! Il mio\nSEEL é molto piu'\11attraente!",
  ["_PokemonFanClubSeelFanNormalText"] = "Adoro il mio SEEL!\nEmette un suono\11quando lo stringo!",
  ["_PokemonFanClubSeelText"] = "SEEL: Kyuoo!",
  ["_PokemonFanClubSign1Text"] = "Ascoltiamo tutti\ncon educazione gli\11altri allenatori!",
  ["_PokemonFanClubSign2Text"] = "Se qualcuno si\nvanta, vantati\11pure tu!",
  ["_PokemonFightingFitText"] = "Grazie! I tuoi\nPOKéMON sono in\11forma!",
  ["_PokemonMansion1FScientistAfterBattleText"] = "Una\nchiave? Non so di\11cosa tu stia\nparlando.",
  ["_PokemonMansion1FScientistBattleText"] = "Chi\nsei? Non dovrebbe\11esserci nessuno\nqui.",
  ["_PokemonMansion1FScientistEndBattleText"] = "Ahi!",
  ["_PokemonMansion1FSwitchNotPressedText"] = "Non ancora!",
  ["_PokemonMansion1FSwitchPressedText"] = "Chi non lo\nfarebbe?",
  ["_PokemonMansion1FSwitchText"] = "Un interruttore\nsegreto! Vuoi\11premerlo?",
  ["_PokemonMansion2FDiary1Text"] = "Diario: 5 luglio\nGuyana, Sud\11America Nuovo\nPOKéMON scoperto\11nel profondo della\ngiungla.",
  ["_PokemonMansion2FDiary2Text"] = "Diario: 10 luglio\nAbbiamo battezzato\11il nuovo POKéMON,\nMEW.",
  ["_PokemonMansion2FSuperNerdAfterBattleText"] = "Gli\ninterruttori\11aprono e chiudono\nporte alternate!",
  ["_PokemonMansion2FSuperNerdBattleText"] = "Non\nriesco a uscire!\11Questo vecchio\nposto é un\11rompicapo!",
  ["_PokemonMansion2FSuperNerdEndBattleText"] = "Oh no!\nIl mio sacco di\11oggetti!",
  ["_PokemonMansion2FSwitchNotPressedText"] = "Non ancora!",
  ["_PokemonMansion2FSwitchPressedText"] = "Chi non lo\nfarebbe?",
  ["_PokemonMansion2FSwitchText"] = "Un interruttore\nsegreto! Vuoi\11premerlo?",
  ["_PokemonMansion3FDiaryText"] = "Diario: 6 feb. MEW\nha partorito.\11Abbiamo chiamato\nil piccolo MEWTWO.",
  ["_PokemonMansion3FScientistAfterBattleText"] = "Sei\nbloccato? Prova a\11saltare giu' da\nli'!",
  ["_PokemonMansion3FScientistBattleText"] = "Il mio\nmentore visse qui\11un tempo.",
  ["_PokemonMansion3FScientistEndBattleText"] = "Uf!\nTravolgente!",
  ["_PokemonMansion3FSuperNerdAfterBattleText"] = "Chissa'\ndove é andato il\11mio socio.",
  ["_PokemonMansion3FSuperNerdBattleText"] = "Questo\nposto é cosi'\11grande!",
  ["_PokemonMansion3FSuperNerdEndBattleText"] = "Ahi!",
  ["_PokemonMansionB1FBurglarAfterBattleText"] = "Puoi\ntrovare roba in\11giro.",
  ["_PokemonMansionB1FBurglarBattleText"] = "Oh no.\nDove mi trovo ora?",
  ["_PokemonMansionB1FBurglarEndBattleText"] = "Awooh!",
  ["_PokemonMansionB1FDiaryText"] = "Diario: 1 set.\nMEWTWO é troppo\11potente. Non siamo\nriusciti a frenare\11la sua indole\nferoce...",
  ["_PokemonMansionB1FScientistAfterBattleText"] = "Mi\npiace qui!\11Favorisce i miei\nstudi!",
  ["_PokemonMansionB1FScientistBattleText"] = "Questo\nposto é ideale per\11un lab.",
  ["_PokemonMansionB1FScientistEndBattleText"] = "A che\nserviva questo?",
  ["_PokemonSellingGreetingText"] = "Cosa vorresti\nvendere?",
  ["_PokemonStuffText"] = "Wow! Un mucchio di\nroba POKéMON!",
  ["_PokemonTower1FBaldingGuyText"] = "Sono venuto a\npregare per il mio\11CLEFAIRY. Sniff!\nNon riesco a\11smettere di\npiangere...",
  ["_PokemonTower1FChannelerText"] = "Sono un MEDIUM! Ci\nsono spiriti che\11fanno marachelle!",
  ["_PokemonTower1FGirlText"] = "Il mio\nGROWLITHE...\11Perché sei morto?",
  ["_PokemonTower1FMiddleAgedWomanText"] = "Sei venuto a\nportare rispetto?\11Sii benedetto!",
  ["_PokemonTower1FReceptionistText"] = "La TORRE POKéMON\nfu eretta in\11memoria dei\nPOKéMON deceduti.",
  ["_PokemonTower2FChannelerText"] = "Neanche noi\nidentifichiamo i\11FANTASMI! Uno\nSPETTROSONDA li\11smaschererebbe.",
  ["_PokemonTower2FRivalDefeatedText"] = "Cosa? Sei una\ncarogna! Ci sono\11andato pesante\nanch'io!",
  ["_PokemonTower2FRivalHowsYourDexText"] = "Come va il\nPOKéDEX, amico? Ho\11appena catturato\nun CUBONE! Non\11trovo ancora il\nMAROWAK adulto!\11Dubbia ce ne\nsiano! Be', devo\11andare! Ho molto\nda fare! A presto,\11amico!",
  ["_PokemonTower2FRivalVictoryText"] = "{RIVAL}: Beh,\nquanti POKéMON\11fifoni hai!\nRinforzali un po'\11di piu'!",
  ["_PokemonTower2FRivalWhatBringsYouHereText"] = "{RIVAL}: Ehi\n{PLAYER}! Cosa ci\11fai qui? I tuoi\nPOKéMON non\11sembrano morti!\nPosso almeno farli\11svenire! Forza,\namico!",
  ["_PokemonTower3FChanneler1AfterBattleText"] = "I FANTASMI\nsi riconoscono con\11lo SPETTROSONDA.",
  ["_PokemonTower3FChanneler1BattleText"] = "Urrg...\nAwaa... Huhu...\11graa..",
  ["_PokemonTower3FChanneler1EndBattleText"] = "Hwa! Sono\nsalva!",
  ["_PokemonTower3FChanneler2AfterBattleText"] = "Scusa! Ero\nposseduta!",
  ["_PokemonTower3FChanneler2BattleText"] = "Kekeke...\nKwaaah!",
  ["_PokemonTower3FChanneler2EndBattleText"] = "Mhm? Che\nsto facendo?",
  ["_PokemonTower3FChanneler3AfterBattleText"] = "Anche i\nmiei amici erano\11posseduti!",
  ["_PokemonTower3FChanneler3BattleText"] = "Vattene!\nSpirito malvagio!",
  ["_PokemonTower3FChanneler3EndBattleText"] = "Uf! Lo\nspirito é via!",
  ["_PokemonTower4FChanneler1AfterBattleText"] = "Devo aver\nsognato...",
  ["_PokemonTower4FChanneler1BattleText"] = "FANTASMA!\nNo! Kwaaah!",
  ["_PokemonTower4FChanneler1EndBattleText"] = "Dov'é il\nFANTASMA?",
  ["_PokemonTower4FChanneler2AfterBattleText"] = "Non\nscopriamo\11l'identita' dei\nFANTASMI.",
  ["_PokemonTower4FChanneler2BattleText"] = "Maledetto\ncon me! Kwaaah!",
  ["_PokemonTower4FChanneler2EndBattleText"] = "Cosa!",
  ["_PokemonTower4FChanneler3AfterBattleText"] = "Che le\nanime dei POKéMON\11riposino in\npace...",
  ["_PokemonTower4FChanneler3BattleText"] = "Huhuhu...\nNon battermi!",
  ["_PokemonTower4FChanneler3EndBattleText"] = "Eh? Chi?\nCosa?",
  ["_PokemonTower5FChanneler1Text"] = "Vieni, bimbo! Ho\nsigillato lo\11spazio con magia!\nPuoi riposare qui!",
  ["_PokemonTower5FChanneler2AfterBattleText"] = "Ero sotto\npossessione!",
  ["_PokemonTower5FChanneler2BattleText"] = "Dammi...\nla tua... anima...",
  ["_PokemonTower5FChanneler2EndBattleText"] = "Gasp!",
  ["_PokemonTower5FChanneler3AfterBattleText"] = "Ero\nposseduta!",
  ["_PokemonTower5FChanneler3BattleText"] = "Tu...\nunisciti... a\11noi...",
  ["_PokemonTower5FChanneler3EndBattleText"] = "Che\nincubo!",
  ["_PokemonTower5FChanneler4AfterBattleText"] = "Ho ripreso\ni sensi!",
  ["_PokemonTower5FChanneler4BattleText"] = "Zombi!",
  ["_PokemonTower5FChanneler4EndBattleText"] = "Ah?",
  ["_PokemonTower5FChanneler5AfterBattleText"] = "Caddi nel\nmale nonostante\11l'addestramento!",
  ["_PokemonTower5FChanneler5BattleText"] = "Urgah...\nUrff....",
  ["_PokemonTower5FChanneler5EndBattleText"] = "Whoo!",
  ["_PokemonTower5FPurifiedZoneText"] = "Entrato in zona\nprotetta e pura! I\11POKéMON di {PLAYER}\nsono curati!",
  ["_PokemonTower6FBeGoneText"] = "Viatene...\nIntrusi...",
  ["_PokemonTower6FChanneler1AfterBattleText"] = "Mi sento\nanemica e\11debole...",
  ["_PokemonTower6FChanneler1BattleText"] = "Dammi...\nil tuo...\11sangue...",
  ["_PokemonTower6FChanneler1EndBattleText"] = "Gemito!",
  ["_PokemonTower6FChanneler2AfterBattleText"] = "I capelli\nnon sono caduti!\11Era uno spirito\nmalvagio!",
  ["_PokemonTower6FChanneler2BattleText"] = "Urff...\nKwaah!",
  ["_PokemonTower6FChanneler2EndBattleText"] = "Qualcosa é\ncaduto!",
  ["_PokemonTower6FChanneler3AfterBattleText"] = "Che\nsuccede qui?",
  ["_PokemonTower6FChanneler3BattleText"] = "Ke..ke...ke...\nke..ke...ke!!",
  ["_PokemonTower6FChanneler3EndBattleText"] = "Keee!",
  ["_PokemonTower6FGhostWasCubonesMotherText"] = "Il FANTASMA era\nl'anima irrequieta\11della madre!",
  ["_PokemonTower6FSoulWasCalmedText"] = "L'anima della\nmadre é calmata. é\11partita per\nl'aldila'!",
  ["_PokemonTower7FMrFujiRescueText"] = "MR. FUJI: Eh? Sei\nvenuto a salvarmi?\11Grazie. Ma sono\nvenuto di mia\11spontanea\nvolonta'. Per\11calmare l'anima\ndella madre di\11CUBONE. Penso che\nlo spirito sia\11andato\nnell'aldila'. Ti\11ringrazio per il\npensiero! Seguimi\11a casa, alla CASA\nPOKéMON ai piedi\11della torre.",
  ["_PokemonTower7FRocket1AfterBattleText"] = "Non lo\ndimentichero'!",
  ["_PokemonTower7FRocket1BattleText"] = "Che vuoi?\nPerché sei qui?",
  ["_PokemonTower7FRocket1EndBattleText"] = "Mi\narrendo!",
  ["_PokemonTower7FRocket2AfterBattleText"] = "I POKéMON\nservono solo a\11fare soldi! Non\nimpicciarti!",
  ["_PokemonTower7FRocket2BattleText"] = "Questo\nvecchietto si é\11lamentato per i\nPOKéMON inutili!\11Discutiamo da\nadulti noi!",
  ["_PokemonTower7FRocket2EndBattleText"] = "Ti prego!\nBasta!",
  ["_PokemonTower7FRocket3AfterBattleText"] = "Non la\npasserai liscia!",
  ["_PokemonTower7FRocket3BattleText"] = "Non\nsalverai nessuno,\11moccioso!",
  ["_PokemonTower7FRocket3EndBattleText"] = "Non\nsfidare i ROCKET!",
  ["_PoliwagDexEntry"] = "Le zampe cresciute\nle impediscono di\ncorrere.\12Preferisce nuotare\nche provare a\nstare in piedi.",
  ["_PoliwhirlDexEntry"] = "Capace di vivere\nin acqua e fuori.\nFuori suda per\12mantenere il corpo\nviscido.",
  ["_PoliwrathDexEntry"] = "Ottimo nuotatore a\nstile libero e a\nrana. Supera\12facilmente i\nmigliori nuotatori\numani.",
  ["_PonytaDexEntry"] = "I suoi zoccoli\nsono 10 volte piu'\nduri di un\12diamante. Calpesta\nqualsiasi cosa\nappiattendola in\12poco tempo.",
  ["_PoofText"] = "Puff!",
  ["_PorygonDexEntry"] = "Un POKéMON fatto\ninteramente di\ncodice di\12programmazione. Si\nmuove liberamente\nnel cyberspazio.",
  ["_PotionText"] = "{RAM:wNameBuffer}\nrecupera\11{NUM:wHPBarHPDifference,\n2, 3}!",
  ["_PowerPlantVoltorbBattleText"] = "Bzzzt!",
  ["_PowerPlantZapdosBattleText"] = "Gyaoo!",
  ["_PrimeapeDexEntry"] = "Sempre furioso e\ntenace. Non smette\ndi inseguire la\12sua preda finché\nnon l'ha\ncatturata.",
  ["_PsyduckDexEntry"] = "Mentre distrae i\nnemici con l'aria\nsvagata, questo\12subdolo POKéMON\nusa poteri\ncinetici.",
  ["_PushStartText"] = "Premi START per\naprire il MENU!",
  ["_RaichuDexEntry"] = "La lunga coda\nfunziona da messa\na terra per\12proteggerlo dalla\nsua stessa alta\ntensione.",
  ["_RaisePPWhichTechniqueText"] = "Aumentare i PP di\nquale mossa?",
  ["_RanAwayScaredText"] = "{TARGET} é fuggito\nper la paura!",
  ["_RanFromBattleText"] = "{USER}\nfugge dalla lotta!",
  ["_RapidashDexEntry"] = "Molto competitivo,\nquesto POKéMON\ninsegue chiunque\12si muova veloce\nnella speranza di\nfare una gara.",
  ["_RareCandyText"] = "{RAM:wNameBuffer} sale al\nlivello\11{NUM:wCurEnemyLevel,\n1, 3}!",
  ["_RaticateDexEntry"] = "Usa i baffi per\nmantenere\nl'equilibrio.\12Sembra rallentare\nse vengono\ntagliati.",
  ["_RattataDexEntry"] = "Morde qualsiasi\ncosa attaccando.\nPiccolo e rapido,\12é comune in molti\nluoghi.",
  ["_RedBedroomSNESText"] = "{PLAYER} gioca al\nSuper NES!\11...Bene! é ora di\nandare!",
  ["_RedsHouse1FMomLookingGreatText"] = "MAMMA: Oh bene! Tu\ne i POKéMON state\11benissimo! Badate\na voi!",
  ["_RedsHouse1FMomWakeUpText"] = "MAMMA: Giusto.\nTutti i ragazzi\11lasciano casa. Lo\nhan detto in TV.\11Il PROF. OAK, qui\naccanto, ti cerca.",
  ["_RedsHouse1FMomYouShouldRestText"] = "MAMMA: {PLAYER}!\nDovresti riposare\11un attimo.",
  ["_RedsHouse1FTVStandByMeMovieText"] = "C'é un film in TV.\nQuattro ragazzi\11camminano sui\nbinari. Meglio\11andare anch'io.",
  ["_RedsHouse1FTVWrongSideText"] = "Ops, lato\nsbagliato.",
  ["_ReflectGainedArmorText"] = "{USER} ottiene uno\nscudo!",
  ["_RegainedHealthText"] = "{USER} recupera\nsalute!",
  ["_ReleaseWhichMonText"] = "Quale POKéMON\nliberare?",
  ["_RepelWoreOffText"] = "L'effetto del\nREPELLENTE\11svanisce.",
  ["_RequireCoinCaseText"] = "Serve un\nSALVADANAIO!",
  ["_RestorePPWhichTechniqueText"] = "Ripristinare i PP\ndi quale mossa?",
  ["_ReviveText"] = "{RAM:wNameBuffer} é\nrivitalizzato!",
  ["_RhydonDexEntry"] = "Protetto da una\npelle corazzata,\npuo' vivere nella\12lava fusa a 3600\ngradi.",
  ["_RhyhornDexEntry"] = "Le sue grandi ossa\nsono 1000 volte\npiu' dure di\12quelle umane. Puo'\nsbalzare via un\ntrim.",
  ["_Rival1WinText"] = "{RIVAL}:\nSi'! Non sono\11fantastico?",
  ["_RivalDefeatedText"] = "NO! Non puo'\nessere! Hai\11battuto il meglio!\nDopo tanto lavoro\11per la LEGA? Il\nmio regno é gia'\11terminato? Non é\ngiusto!",
  ["_RivalVictoryText"] = "Ahahah! Ho vinto,\nho vinto! Sono\11troppo forte per\nte, {PLAYER}! Sei\11stato bravo ad\narrivare fin qui,\11io sono il genio!\nBel tentativo, ma\11non vali nulla!\nAhahah!",
  ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "Ho\nvisto un MACHOP in\11questo tunnel!",
  ["_RockTunnel1FCooltrainerF1BattleText"] = "Eek!\nNon fare scherzi\11nel buio!",
  ["_RockTunnel1FCooltrainerF1EndBattleText"] = "Era\ntroppo buio!",
  ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "Sembravi\ncarino e innocuo!",
  ["_RockTunnel1FCooltrainerF2BattleText"] = "Sono\nvenuto fin qui per\11i POKéMON!",
  ["_RockTunnel1FCooltrainerF2EndBattleText"] = "Non\nho piu' POKéMON!",
  ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "Uf!\nOra sono tutto\11sudato!",
  ["_RockTunnel1FCooltrainerF3BattleText"] = "Hai\ndei POKéMON!\11Iniziamo!",
  ["_RockTunnel1FCooltrainerF3EndBattleText"] = "Giochi\nduro!",
  ["_RockTunnel1FHiker1AfterBattleText"] = "Attento\na ONIX! Puo'\11stritolarti!",
  ["_RockTunnel1FHiker1BattleText"] = "Questo\ntunnel é molto\11lungo, ragazzo!",
  ["_RockTunnel1FHiker1EndBattleText"] = "Doh!\nHai vinto!",
  ["_RockTunnel1FHiker2AfterBattleText"] = "Quel\nPOKéMON dormiente\11al PERCORSO mi ha\ncostretto a una\11deviazione.",
  ["_RockTunnel1FHiker2BattleText"] = "Mhm.\nForse mi sono\11perso...",
  ["_RockTunnel1FHiker2EndBattleText"] = "Calma!\nChe sto facendo?\11Dov'é l'uscita?",
  ["_RockTunnel1FHiker3AfterBattleText"] = "Hai\nabbastanza talento\11per scalare!",
  ["_RockTunnel1FHiker3BattleText"] = "I\nforestieri come te\11devono mostrarmi\nrispetto!",
  ["_RockTunnel1FHiker3EndBattleText"] = "Mi\narrendo!",
  ["_RockTunnel1FSignText"] = "TUNNEL ROCCIOSO\nCELESTOPOLI\11LAVANDONIA",
  ["_RockTunnel1FSuperNerdAfterBattleText"] = "Vabbé,\nprendero' un ZUBAT\11strada facendo!",
  ["_RockTunnel1FSuperNerdBattleText"] = "Lotta\nPOKéMON! Pronti,\11via!",
  ["_RockTunnel1FSuperNerdEndBattleText"] = "Game\nover!",
  ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "Voglio\nandare a casa!",
  ["_RockTunnelB1FCooltrainerF1BattleText"] = "Gli\nescursionisti\11lasciano rametti\ncome segnavia.",
  ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "Ohhh!\nHo fatto del mio\11meglio!",
  ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "Amo i\npiccoli POKéMON, i\11grandi fanno\npaura!",
  ["_RockTunnelB1FCooltrainerF2BattleText"] = "Non\nvengo spesso, ma\11lottero' con te.",
  ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "Oh!\nHo perso!",
  ["_RockTunnelB1FHiker1AfterBattleText"] = "Punto\nsulla forza perché\11odio pensare!",
  ["_RockTunnelB1FHiker1BattleText"] = "Ahahah!\nPuoi battere la\11mia forza?",
  ["_RockTunnelB1FHiker1EndBattleText"] = "Ops!\nBattuto!",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "Tra i\nmonti trovi spesso\11POKéMON di tipo\nroccia.",
  ["_RockTunnelB1FHiker2BattleText"] = "Le mie\ntecniche ti\11faranno piangere!",
  ["_RockTunnelB1FHiker2EndBattleText"] = "Mi\narrendo! Sei un\11tecnico migliore!",
  ["_RockTunnelB1FHiker3AfterBattleText"] = "Crescero'\nil mio POKéMON per\11battere il tuo,\nragazzo!",
  ["_RockTunnelB1FHiker3BattleText"] = "Colpiscimi\ncon il tuo meglio!",
  ["_RockTunnelB1FHiker3EndBattleText"] = "Colpo\npartito!",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Quando\nfinisci il\11POKéDEX, posso\naverlo?",
  ["_RockTunnelB1FSuperNerd1BattleText"] = "Hai un\nPOKéDEX? Ne voglio\11uno!",
  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "Accidenti!\nChe invidia!",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "Alcuni\nsi vestono da\11POKéMON per\ndivertimento.",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "Conosci\ni cosplayer di\11POKéMON?",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "Be',\nquesto é tutto.",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Sono un\nartista, non un\11lottatore.",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "Disegno\nPOKéMON quando\11sono a casa.",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "Uf!\nSono esausto!",
  ["_RockTunnelPokecenterFisherText"] = "Ho venduto una\nPEPITA per ¥5000!",
  ["_RockTunnelPokecenterGentlemanText"] = "I tipi elementali\ndei POKéMON li\11rendono forti con\nalcuni e deboli\11con altri!",
  ["_RockTunnelPokecenterGuyText"] = "Ho sentito che i\nFANTASMI infestano\11LAVANDONIA!",
  ["_RocketHide3AfterBattleText3"] = "Vai pure\navanti! Ma ti\11serve la CHIAVE\nASCENSORE!",
  ["_RocketHideout3BattleText"] = "Ci é\narrivata voce che\11stavi arrivando!",
  ["_RocketHideout3EndBattleText3"] = "Cosa? Ho\nperso? No!",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "Stai\ncriticando il TEAM\11ROCKET?",
  ["_RocketHideoutB1FRocket1BattleText"] = "Chi sei?\nCome sei arrivato\11qui?",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "Ahi!\nBattuto!",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "Non la\npasserai liscia,\11moccioso!",
  ["_RocketHideoutB1FRocket2BattleText"] = "Ti sei\nintrodotto nella\11nostra base?",
  ["_RocketHideoutB1FRocket2EndBattleText"] = "Bruciato!",
  ["_RocketHideoutB1FRocket3AfterBattleText"] = "La\nSPETTROSONDA? Non\11so dove sia!",
  ["_RocketHideoutB1FRocket3BattleText"] = "Allarme\nintruso!",
  ["_RocketHideoutB1FRocket3EndBattleText"] = "Non ci\nriesco!",
  ["_RocketHideoutB1FRocket4AfterBattleText"] = "OK,\nparlero'! Prendi\11l'ascensore per il\nCAPO!",
  ["_RocketHideoutB1FRocket4BattleText"] = "Perché sei\nvenuto qui?",
  ["_RocketHideoutB1FRocket4EndBattleText"] = "Questo non\nva!",
  ["_RocketHideoutB1FRocket5AfterBattleText"] = "Oh no,\nquella lotta ha\11aperto la porta!",
  ["_RocketHideoutB1FRocket5BattleText"] = "Ti sei\nperso, piccolo\11ratto?",
  ["_RocketHideoutB1FRocket5EndBattleText"] = "Perché...?",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "La base\nROCKET ha 4 piani\11interrati.\nArriverai dal\11CAPO?",
  ["_RocketHideoutB2FRocketBattleText"] = "Il CAPO\ndice che vedi i\11FANTASMI con lo\nSPETTROSONDA!",
  ["_RocketHideoutB2FRocketEndBattleText"] = "Mi\narrendo!",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "SPETTROSONDA?\nLa macchina\11rubata. é qui da\nqualche parte.",
  ["_RocketHideoutB3FRocket1BattleText"] = "Smetti di\nintrometterti\11negli affari del\nROCKET!",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "Oof!\nAtterrato!",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Vedo che cresci i\nPOKéMON con cura.\11Un bambino come te\nnon capirebbe cosa\11voglio fare. Mi\nfaccio da parte\11stavolta! Spero ci\nriverremo...",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "Dunque! Devo dire\nche sono colpito\11che tu sia qui!",
  ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "COSA! Non puo'\nessere!",
  ["_RocketHideoutB4FRocket1AfterBattleText"] = "Ce l'hai\ncon il TEAM\11ROCKET?",
  ["_RocketHideoutB4FRocket1BattleText"] = "Ti\nconosco! Hai\11rovinato i piani\nal MONTE LUNA!",
  ["_RocketHideoutB4FRocket1EndBattleText"] = "Bruciato\ndi nuovo!",
  ["_RocketHideoutB4FRocket2AfterBattleText"] = "CAPO!\nScusa se ho\11fallito!",
  ["_RocketHideoutB4FRocket2BattleText"] = "Come fai a\nnon vedere la\11bellezza del\nnostro male?",
  ["_RocketHideoutB4FRocket2EndBattleText"] = "Ayaya!",
  ["_RocketHideoutB4FRocket3AfterBattleText"] = "Oh no! Ho\nperso la CHIAVE\11ASCENSORE!",
  ["_RocketHideoutB4FRocket3BattleText"] = "L'ascensore\nnon va? Chi ha la\11CHIAVE ASCENSORE?",
  ["_RocketHideoutB4FRocket3EndBattleText"] = "No!",
  ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "Sembra che serva\nuna chiave.",







  ["_RoseText"] = "rose!",
  ["_Route10CooltrainerF1AfterBattleText"] = "Ho\nnotato dei\11POKéMANIAC che\ngironzolavano.",
  ["_Route10CooltrainerF1BattleText"] = "Sono\nstata in una\11PALESTRA POKéMON\nqualche volta. Ma\11ho sempre perso.",
  ["_Route10CooltrainerF1EndBattleText"] = "Oh!\nDi nuovo al\11tappeto!",
  ["_Route10CooltrainerF2AfterBattleText"] = "I\nPOKéMON qui sono\11cosi' paffuti!\nDovrebbe essercene\11uno rosa con un\nmotivo floreale!",
  ["_Route10CooltrainerF2BattleText"] = "Mi\nsento un po'\11svienevole per\nquesta dura\11escursione.",
  ["_Route10CooltrainerF2EndBattleText"] = "Non\nce la faccio!",
  ["_Route10Hiker1AfterBattleText"] = "E-et-ciu'!\nEt-ciu'! Sniff!\11Tirch!",
  ["_Route10Hiker1BattleText"] = "Ah-ahah-ah-ah!",
  ["_Route10Hiker1EndBattleText"] = "Ah-aha!\nNon sto ridendo!\11Ho il raffreddore!\nE-et-ciu'!",
  ["_Route10Hiker2AfterBattleText"] = "Mi\nsento gonfio\11dell'aria di\nmonte!",
  ["_Route10Hiker2BattleText"] = "Ah!\nQuest'aria di\11monte é deliziosa!",
  ["_Route10Hiker2EndBattleText"] = "Questo\nmi ha schiarito le\11idee!",
  ["_Route10PowerPlantSignText"] = "CENTRALE ELETTRICA",
  ["_Route10RockTunnelSignText"] = "DIGRAPUNTO",
  ["_Route10SuperNerd1AfterBattleText"] = "Ho\naltri POKéMON rari\11a casa!",
  ["_Route10SuperNerd1BattleText"] = "Wow,\nsei un POKéMANIAC\11anche tu? Vuoi\nvedere la mia\11collezione?",
  ["_Route10SuperNerd1EndBattleText"] = "Uhm.\nNon sono\11arrabbiato!",
  ["_Route10SuperNerd2AfterBattleText"] = "Mi stai\nantipatico perché\11mi hai battuto!",
  ["_Route10SuperNerd2BattleText"] = "Ehi\nragazzo, vuoi\11vedere i miei\nPOKéMON?",
  ["_Route10SuperNerd2EndBattleText"] = "Oh no!\nI miei POKéMON!",
  ["_Route11DiglettsCaveSignText"] = "GROTTA DIGLETT",
  ["_Route11Gambler1AfterBattleText"] = "I\nPOKéMON sono vita!\11E vivere significa\nazzardare!",
  ["_Route11Gambler1BattleText"] = "Vinci,\nperdi o pareggi!",
  ["_Route11Gambler1EndBattleText"] = "Atcha!\nNon é andata come\11volevo!",
  ["_Route11Gambler2AfterBattleText"] = "Non\npuoi essere un\11covardo nel mondo\ndei POKéMON!",
  ["_Route11Gambler2BattleText"] = "Competizione!\nNon ne tengo mai\11abbastanza!",
  ["_Route11Gambler2EndBattleText"] = "Avevo\nuna possibilita'!",
  ["_Route11Gambler3AfterBattleText"] = "Colpo\ndi fortuna! Solo\11fortuna!",
  ["_Route11Gambler3BattleText"] = "Fwahaha!\nNon ho mai perso!",
  ["_Route11Gambler3EndBattleText"] = "La mia\nprima sconfitta!",
  ["_Route11Gambler4AfterBattleText"] = "é solo\nfortuna. Colpo di\11fortuna.",
  ["_Route11Gambler4BattleText"] = "Non\navevo mai vinto\11prima...",
  ["_Route11Gambler4EndBattleText"] = "Me lo\nsapevo...",
  ["_Route11Gate1FGuardText"] = "Quando catturi\ntanti POKéMON, non\11é difficile\ntrovare i nomi? A\11LAVANDONIA c'é un\nesperto di\11nomignoli POKéMON.\nTi aiutera' anche\11a ribattezzarli!",
  ["_Route11Gate2FLeftBinocularsNoSnorlaxText"] = "Hai guardato nei\nbinocoli. C'é una\11vista stupenda!",
  ["_Route11Gate2FLeftBinocularsSnorlaxText"] = "Hai guardato nei\nbinocoli. Un\11grosso POKéMON\ndorme sulla\11strada!",
  ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "Ci sono oggetti a\nterra che non si\11possono vedere.\nCERCASP_ e' in\11grado di rilevarli\nnelle vicinanze.\11Non individua il\npunto esatto, devi\11cercarli tu!",
  ["_Route11Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli. L'unico\11modo per andare da\nCELESTOPOLI a\11LAVANDONIA é\npassare per il\11DIGRAPUNTO.",
  ["_Route11SuperNerd1AfterBattleText"] = "Fai\ngirare la voce:\11risparmia energia!",
  ["_Route11SuperNerd1BattleText"] = "Attento!\nSto posando dei\11cavi!",
  ["_Route11SuperNerd1EndBattleText"] = "é stata\nun'esperienza\11elettrizzante!",
  ["_Route11SuperNerd2AfterBattleText"] = "Beh, é\nora di tornare al\11lavoro.",
  ["_Route11SuperNerd2BattleText"] = "Attento\nai fili scoperti!",
  ["_Route11SuperNerd2EndBattleText"] = "Urca!\nSei una scintilla!",
  ["_Route11Youngster1AfterBattleText"] = "Ce l'ho\nmessa tutta! Non\11ho rimpianti!",
  ["_Route11Youngster1BattleText"] = "Andiamo, ma\nnon barare!",
  ["_Route11Youngster1EndBattleText"] = "Eh? Non é\ngiusto!",
  ["_Route11Youngster2AfterBattleText5"] = "Che vuoi?\nLasciami in pace!",
  ["_Route11Youngster2BattleText"] = "Sono appena\ndiventato un\11allenatore! Ma\ncredo di poter\11vincere!",
  ["_Route11Youngster2EndBattleText"] = "I miei\nPOKéMON no!",
  ["_Route11Youngster3AfterBattleText"] = "C'é un\ngrosso POKéMON che\11scende dalle\nmontagne. é forte,\11se riesci a\nprenderlo.",
  ["_Route11Youngster3BattleText"] = "Sono il\nmigliore della mia\11classe!",
  ["_Route11Youngster3EndBattleText"] = "Acciderboli!\nDevo rendere i\11miei POKéMON piu'\nforti!",
  ["_Route11Youngster4AfterBattleText"] = "Faro'\nmeglio a cercarne\11di piu' forti!",
  ["_Route11Youngster4BattleText"] = "I miei\nPOKéMON dovrebbero\11essere pronti!",
  ["_Route11Youngster4EndBattleText"] = "Troppo\ngiovane per farlo!",
  ["_Route12CooltrainerMAfterBattleText"] = "Pensa\nche avrei potuto\11evolvere i miei\nPOKéMON con una\11PIETRALUNARE!",
  ["_Route12CooltrainerMBattleText"] = "Hai\ntrovato una\11PIETRALUNARE?",
  ["_Route12CooltrainerMEndBattleText"] = "Ahi!",
  ["_Route12Fisher1AfterBattleText"] = "Resisti!\nHo la lenza\11impigliata!",
  ["_Route12Fisher1BattleText"] = "Evviva!\nHa abboccato,\11proprio qui!",
  ["_Route12Fisher1EndBattleText"] = "Tch!\nSolo un\11pesciolino!",
  ["_Route12Fisher2AfterBattleText"] = "Con un\nAMO migliore\11potrei catturare\nPOKéMON migliori!",
  ["_Route12Fisher2BattleText"] = "Pazienza!\nLa pesca richiede\11molta attesa!",
  ["_Route12Fisher2EndBattleText"] = "Quello\né scappato!",
  ["_Route12Fisher3AfterBattleText"] = "Mi hai\nbattuto coi\11POKéMON, ma io ci\nsaccio con la\11pesca!",
  ["_Route12Fisher3BattleText"] = "Il\nDRITTO DELLA PESCA\11contro il BIMBO\nPOKéMON!",
  ["_Route12Fisher3EndBattleText"] = "Troppo\nforte!",
  ["_Route12Fisher4AfterBattleText"] = "Va bene\nlo stesso. Perdere\11non mi scoccia\npiu' di tanto.",
  ["_Route12Fisher4BattleText"] = "Preferirei\nlavorare!",
  ["_Route12Fisher4EndBattleText"] = "Non é\ncosi' semplice...",
  ["_Route12Fisher5AfterBattleText"] = "Pesco\nMAGIKARP in\11continuazione, ma\nsono debolissimi!",
  ["_Route12Fisher5BattleText"] = "Non sai\nmai cosa puoi\11pescare!",
  ["_Route12Fisher5EndBattleText"] = "Scappato!",
  ["_Route12Gate1FGuardText"] = "C'é un punto di\nosservazione al\11piano superiore.",
  ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "{PLAYER} riceve\nMT39!",
  ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "MT39 contiene\nPIrossino. é molto\11precisa, usala\nnelle lotte che\11non puoi\npermetterti di\11perdere.",
  ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "Non hai abbastanza\nspazio per questo.",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "Le ceneri del mio\nPOKéMON sono nella\11TORRE POKéMON.\nTieni questa MT.\11Non mi serve\npiu'...",
  ["_Route12Gate2FLeftBinocularsText"] = "Hai guardato nei\nbinocoli. Un\11pescatore!",
  ["_Route12Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli. é la\11TORRE POKéMON!",
  ["_Route12SignText"] = "PERCORSO 12 Nord\nper LAVANDONIA",
  ["_Route12SnorlaxCalmedDownText"] = "SNORLAX si é\ncalmato! Con un\11grande sbadiglio é\ntornato sui monti!",
  ["_Route12SnorlaxText"] = "Un POKéMON\ndormiente blocca\11la via!",
  ["_Route12SnorlaxWokeUpText"] = "SNORLAX si é\nsvegliato! Ha\11sferrato un\nattacco furioso!",
  ["_Route12SportFishingSignText"] = "AREA DI PESCA\nSPORTIVA",
  ["_Route12SuperNerdAfterBattleText"] = "L'acqua\né conduttrice di\11elettricita',\ndovresti friggere\11i POKéMON marini!",
  ["_Route12SuperNerdBattleText"] = "L'elettricita'\né la mia\11specialita'!",
  ["_Route12SuperNerdEndBattleText"] = "Spento!",
  ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "Sono il fratello\ndel GURU\11PESCATORE! Adoro\npescare! Ti piace\11pescare?",
  ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "La pesca é uno\nstile di vita! Dai\11mari ai fiumi,\nesci e prendi il\11pesce grosso!",
  ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "Oh no! Avevo un\nregalo per te, ma\11non hai abbastanza\nspazio!",
  ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "Magnifico! Mi\npiace il tuo\11stile! Prendi\nquesto e pesca,\11giovanotto!\n{PLAYER} riceve\11{RAM:wStringBuffer}!",
  ["_Route12SuperRodHouseFishingGuruThatsDisappointingText"] = "Oh... Che\ndelusione...",
  ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "Ciao, {PLAYER}! Usa\nil SUPERAMO in\11qualsiasi acqua!\nPotrai pescare\11diversi tipi di\nPOKéMON. Prova a\11pescare dovunque\ntu possa!",
  ["_Route13Beauty1AfterBattleText"] = "Chissa' se\nsono piu' forti i\11POKéMON maschi o\nfemmine?",
  ["_Route13Beauty1BattleText"] = "Certo,\ngiochero' con te!",
  ["_Route13Beauty1EndBattleText"] = "Oh! Brutto\ncavernicolo!",
  ["_Route13Beauty2AfterBattleText"] = "Non so\nnulla di POKéMON.\11Mi piacciono solo\nquelli fighi!",
  ["_Route13Beauty2BattleText"] = "Vuoi\nPOKéMONIzzare con\11me?",
  ["_Route13Beauty2EndBattleText"] = "é gia'\nfinito?",
  ["_Route13BikerAfterBattleText"] = "Sparisci!",
  ["_Route13BikerBattleText"] = "Che\nguardi?",
  ["_Route13BikerEndBattleText"] = "Accidenti!\nMarce sgranate!",
  ["_Route13CooltrainerF1AfterBattleText"] = "Voglio\ndiventare un bravo\11allenatore. Mi\nallenero' duro.",
  ["_Route13CooltrainerF1BattleText"] = "Dicono\nche me la cavaimo\11per la mia eta'!",
  ["_Route13CooltrainerF1EndBattleText"] = "Ohh!\nHo perso!",
  ["_Route13CooltrainerF2AfterBattleText"] = "So\nche hai preso\11quelle MEDAGLIE\ndai CAPIPALESTRA.",
  ["_Route13CooltrainerF2BattleText"] = "Wow!\nChe figate le tue\11MEDAGLIE!",
  ["_Route13CooltrainerF2EndBattleText"] = "Non\nbasta!",
  ["_Route13CooltrainerF3AfterBattleText"] = "Devi\nfar lottare i\11POKéMON per\nrenderli piu'\11forti!",
  ["_Route13CooltrainerF3BattleText"] = "I\nmiei cari POKéMON\11vogliono fare la\ntua conoscenza.",
  ["_Route13CooltrainerF3EndBattleText"] = "Wow!\nHai vinto alla\11grande!",
  ["_Route13CooltrainerF4AfterBattleText"] = "CALCIO\nha aumentato la\11VELOCITA' dei miei\nPOKéMON.",
  ["_Route13CooltrainerF4BattleText"] = "Ho\ntrovato CALCIO in\11una grotta.",
  ["_Route13CooltrainerF4EndBattleText"] = "Che\nsbaglio!",
  ["_Route13CooltrainerM1AfterBattleText"] = "I miei\nPOKéMON sembrano\11felici, nonostante\nabbiano perso.",
  ["_Route13CooltrainerM1BattleText"] = "I miei\nPOKéMON volatili\11vogliono fare a\nbotte!",
  ["_Route13CooltrainerM1EndBattleText"] = "La mia\ncombo alata ha\11perso?",
  ["_Route13CooltrainerM2AfterBattleText"] = "Sono\nesausto. Credo che\11volero' a casa.",
  ["_Route13CooltrainerM2BattleText"] = "Il\nvento spira dalla\11mia parte!",
  ["_Route13CooltrainerM2EndBattleText"] = "Il\nvento é cambiato!",
  ["_Route13CooltrainerM3AfterBattleText"] = "Vorrei\nvolare come PIDGEY\11e PIDGEOTTO...",
  ["_Route13CooltrainerM3BattleText"] = "Io\nscelgo sempre i\11POKéMON volatili!",
  ["_Route13CooltrainerM3EndBattleText"] = "Energia\nesaurita!",
  ["_Route13SignText"] = "PERCORSO 13 Nord\nper PONTE SILENZIO",
  ["_Route13TrainerTips1Text"] = "CONSIGLI AGLI\nALLENATORI Guarda\11a sinistra di quel\npalo!",
  ["_Route13TrainerTips2Text"] = "CONSIGLI AGLI\nALLENATORI Usa\11SELECT per\ninvertire gli\11oggetti nello\nzaino!",
  ["_Route14Biker1AfterBattleText"] = "Che c'é,\nche c'é? Che cosa\11vuoi?",
  ["_Route14Biker1BattleText"] = "Forza,\nforza. Andiamo,\11andiamo, andiamo!",
  ["_Route14Biker1EndBattleText"] = "Argh!\nPerso! Sparisci!",
  ["_Route14Biker2AfterBattleText"] = "Allevare\nPOKéMON é una noia\11mortale.",
  ["_Route14Biker2BattleText"] = "Perfetto!\nDevo far passare\11il tempo!",
  ["_Route14Biker2EndBattleText"] = "Cosa?\nTu!?",
  ["_Route14Biker3AfterBattleText"] = "é forte\naver reso i tuoi\11POKéMON cosi'\npotenti! La forza\11comanda! E lo sai!",
  ["_Route14Biker3BattleText"] = "Gareggiamo\nqui perché c'é\11piu' spazio!",
  ["_Route14Biker3EndBattleText"] = "Spazzati\nvia!",
  ["_Route14Biker4AfterBattleText"] = "Chissa'\nchi vincerebbe tra\11te e me, uno\ncontro uno!",
  ["_Route14Biker4BattleText"] = "Lotta\nPOKéMON? Che\11figata! Rissai!",
  ["_Route14Biker4EndBattleText"] = "Spazzato\nvia!",
  ["_Route14CooltrainerM1AfterBattleText"] = "Hai\ndelle MN, vero? I\11POKéMON non\npossono mai\11dimenticare quelle\nmosse.",
  ["_Route14CooltrainerM1BattleText"] = "Devi\nusare le MT per\11insegnare mosse\nforti ai POKéMON!",
  ["_Route14CooltrainerM1EndBattleText"] = "Non\nbasta!",
  ["_Route14CooltrainerM2AfterBattleText"] = "Devono\nimparare mosse\11migliori.",
  ["_Route14CooltrainerM2BattleText"] = "I miei\nPOKéMON volatili\11sono pronti per la\nbattaglia.",
  ["_Route14CooltrainerM2EndBattleText"] = "Non\nancora pronti!",
  ["_Route14CooltrainerM3AfterBattleText"] = "Insegna\nai POKéMON mosse\11dello stesso tipo\nper renderli piu'\11potenti.",
  ["_Route14CooltrainerM3BattleText"] = "Le MT\nsono in vendita a\11AZZURROPOLI! Ma\npochi hanno le MN!",
  ["_Route14CooltrainerM3EndBattleText"] = "Ahi,\nche sfortuna!",
  ["_Route14CooltrainerM4AfterBattleText"] = "I\nPOKéMON volatili\11sono il mio amore!",
  ["_Route14CooltrainerM4BattleText"] = "Hai\ninsegnato ai tuoi\11POKéMON volatili\ncome usare VOLO?",
  ["_Route14CooltrainerM4EndBattleText"] = "Abbattuto\nin fiamme!",
  ["_Route14CooltrainerM5AfterBattleText"] = "I 3\nPOKéMON leggendari\11sono tutti rapaci.",
  ["_Route14CooltrainerM5BattleText"] = "Hai\nmai sentito\11parlare dei\nPOKéMON\11leggendari?",
  ["_Route14CooltrainerM5EndBattleText"] = "Perché?\nPerché ho perso?",
  ["_Route14CooltrainerM6AfterBattleText"] = "Vincere\no perdere, alla\11fine non conta\nnulla!",
  ["_Route14CooltrainerM6BattleText"] = "Non ne\nho voglia, ma OK!\11Andiamo!",
  ["_Route14CooltrainerM6EndBattleText"] = "Lo\nsapevo!",
  ["_Route14SignText"] = "PERCORSO 14 Ovest\nper FUCSIAPOLI",
  ["_Route15Beauty1AfterBattleText"] = "Ti perdono!\nPosso incassare!",
  ["_Route15Beauty1BattleText"] = "Oh, che\ncarino che sei!",
  ["_Route15Beauty1EndBattleText"] = "Sembravi\ncosi' carino!",
  ["_Route15Beauty2AfterBattleText"] = "Mi piace\ntornare a casa per\11stare con i miei\nPOKéMON!",
  ["_Route15Beauty2BattleText"] = "Allevo\nPOKéMON perché\11vivo da sola!",
  ["_Route15Beauty2EndBattleText"] = "Non l'avevo\nchiesto!",
  ["_Route15Biker1AfterBattleText"] = "Si vive\nuna volta sola,\11percio' faccio il\nfuorilegge! IL\11TEAM ROCKET\nCOMANDA!",
  ["_Route15Biker1BattleText"] = "Ehi\nragazzo! Forza! Li\11ho appena presi!",
  ["_Route15Biker1EndBattleText"] = "Perché\nno?",
  ["_Route15Biker2AfterBattleText"] = "Stavo\nsolo scherzando\11sui soldi!",
  ["_Route15Biker2BattleText"] = "Sborsa\ntutti i tuoi soldi\11quando perdi con\nme, pivello!",
  ["_Route15Biker2EndBattleText"] = "Non puo'\nessere vero!",
  ["_Route15CooltrainerF1AfterBattleText"] = "Non\npuoi cambiare il\11soprannome dei\nPOKéMON scambiati.\11Solo l'Allenatore\nOriginale puo'.",
  ["_Route15CooltrainerF1BattleText"] = "Fammi\nprovare il POKéMON\11che ho appena\nscambiato!",
  ["_Route15CooltrainerF1EndBattleText"] = "Non\nbasta!",
  ["_Route15CooltrainerF2AfterBattleText"] = "Ho\npaura dei CENTAURI\11, sono cosi'\nbrutti e cattivi!",
  ["_Route15CooltrainerF2BattleText"] = "Tu\nhai una faccia\11gentile, credo di\npoterti battere!",
  ["_Route15CooltrainerF2EndBattleText"] = "No,\nsbagliato!",
  ["_Route15CooltrainerF3AfterBattleText"] = "Scambio\nPOKéMON con i miei\11amici!",
  ["_Route15CooltrainerF3BattleText"] = "Che\nc'é di figo?\11Scambiare POKéMON!",
  ["_Route15CooltrainerF3EndBattleText"] = "Ho\ndetto scambio!",
  ["_Route15CooltrainerF4AfterBattleText"] = "Vado\nad allenarmi con\11persone meno\nforti.",
  ["_Route15CooltrainerF4BattleText"] = "Vuoi\ngiocare con i miei\11POKéMON?",
  ["_Route15CooltrainerF4EndBattleText"] = "Ero\ntroppo impaziente!",
  ["_Route15CooltrainerM1AfterBattleText"] = "Forse\nnon sono portato\11per le lotte.",
  ["_Route15CooltrainerM1BattleText"] = "Quando\nfischio, posso\11chiamare i POKéMON\nvolatili!",
  ["_Route15CooltrainerM1EndBattleText"] = "Ahi!\nChe tragico!",
  ["_Route15CooltrainerM2AfterBattleText"] = "Sapevi\nche mosse come\11TERREMOTO non\nhanno alcun\11effetto sui\nvolatili?",
  ["_Route15CooltrainerM2BattleText"] = "Hmm? I\nmiei volatili\11tremano! Tu ci sai\nfare, eh?",
  ["_Route15CooltrainerM2EndBattleText"] = "Proprio\ncome pensavo!",
  ["_Route15Gate1FGuardText"] = "Stai completando\nil POKéDEX?\11L'AIUTANTE DEL\nPROF. OAK é\11passato di qui.",
  ["_Route15Gate2FBinocularsText"] = "Hai guardato nei\nbinocoli. Sembra\11una piccola isola!",
  ["_Route15Gate2FOaksAideExpAllText"] = "CONDPIENA da'\nPunti ESP a tutti\11i POKéMON con te,\nanche se non\11lottano. Tuttavia,\nriduce la\11quantita' di ESP\nper ciascun\11POKéMON. Se non ti\nserve, deponila\11tramite PC.",
  ["_Route15SignText"] = "PERCORSO 15 Ovest\nper FUCSIAPOLI",
  ["_Route15UpstairsBinocularsText"] = "Hai guardato nei\nbinocoli... Un\11grosso uccello\nlucente vola verso\11il mare.",
  ["_Route16Biker1AfterBattleText"] = "Ci piace\nciondolare qui,\11che c'é?",
  ["_Route16Biker1BattleText"] = "Che cosa\nvuoi?",
  ["_Route16Biker1EndBattleText"] = "Non\nosare ridere!",
  ["_Route16Biker2AfterBattleText"] = "Lascia\nstare, chi vuole\11la tua BICI!",
  ["_Route16Biker2BattleText"] = "Che\nbella BICI! Fatti\11sotto!",
  ["_Route16Biker2EndBattleText"] = "Fuori\ncombattimento!",
  ["_Route16Biker3AfterBattleText"] = "Odio\nperdere! Sparisci\11dalla mia vista!",
  ["_Route16Biker3BattleText"] = "Vieni\nfuori a giocare,\11topolino!",
  ["_Route16Biker3EndBattleText"] = "Brutto\nratto!",
  ["_Route16Biker4AfterBattleText"] = "Puoi\narrivare a\11FUCSIAPOLI da\nAZZURROPOLI usando\11la strada\ncostiera.",
  ["_Route16Biker4EndBattleText"] = "Kaboom!",
  ["_Route16Biker5AfterBattleText"] = "Mi\npiacciono i\11POKéMON feroci!\nFanno a pezzi i\11nemici!",
  ["_Route16Biker5BattleText"] = "Ho una\nfame da lupi e\11sono cattivo!",
  ["_Route16Biker5EndBattleText"] = "Male,\nmale, male!",
  ["_Route16Biker6AfterBattleText"] = "Mi piace\nmolestare la gente\11con i miei feroci\nPOKéMON!",
  ["_Route16Biker6BattleText"] = "Certo,\nvengo!",
  ["_Route16Biker6EndBattleText"] = "Non\nfarmi arrabbiare!",
  ["_Route16CyclingRoadSignText"] = "Goditi la discesa!\nPISTA CICLABILE",
  ["_Route16FlyHouseBrunetteGirlHM02ExplanationText"] = "MN02 contiene\nVOLO. Ti\11riportera' in\nqualsiasi citta'.\11Sfruttala al\nmeglio!",
  ["_Route16FlyHouseBrunetteGirlHM02NoRoomText"] = "Non hai abbastanza\nspazio per questo.",
  ["_Route16FlyHouseBrunetteGirlReceivedHM02Text"] = "{PLAYER} riceve\nMN02!",
  ["_Route16FlyHouseBrunetteGirlText"] = "Oh, hai trovato il\nmio rifugio\11segreto! Ti prego,\nnon dire a nessuno\11che sono qui. Ti\nfaro' un regalo\11per farti\nperdonare!",
  ["_Route16FlyHouseFearowText"] = "FEAROW: Kyueen!",
  ["_Route16Gate1FGamblerText"] = "Come sei entrato?\nBuon impegno!",
  ["_Route16Gate1FGuardCyclingRoadExplanationText"] = "La PISTA CICLABILE\né una discesa sul\11mare. é una corsa\nfantastica.",
  ["_Route16Gate1FGuardNoPedestriansAllowedText"] = "I pedoni non sono\nammessi sulla\11PISTA CICLABILE!",
  ["_Route16Gate1FGuardWaitUpText"] = "Ehi tu! Aspetta,\nper favore!",
  ["_Route16Gate2FLeftBinocularsText"] = "Hai guardato nei\nbinocoli. é il\11CENTRO\nCOMMERCIALE!",
  ["_Route16Gate2FLittleBoyText"] = "Vado a fare un\ngiro con la mia\11ragazza!",
  ["_Route16Gate2FLittleGirlText"] = "Andiamo a fare un\ngiro insieme!",
  ["_Route16Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli. C'é un\11lungo sentiero\nsull'acqua!",
  ["_Route16SignText"] = "PERCORSO 16\nAZZURROPOLI\11FUCSIAPOLI",
  ["_Route16SnorlaxReturnedToMountainsText"] = "Con un grande\nsbadiglio, SNORLAX\11é tornato sui\nmonti!",
  ["_Route16SnorlaxWokeUpText"] = "SNORLAX si é\nsvegliato! Ha\11sferrato un\nattacco furioso!",
  ["_Route16Text7"] = "Un POKéMON\ndormiente blocca\11la via!",
  ["_Route16biker4BattleText"] = "Ehi, mi\nhai appena urtato!",
  ["_Route17Biker10AfterBattleText"] = "Devo\nfare un po' di\11sonno!",
  ["_Route17Biker10BattleText"] = "Vattene\nragazzo! Sono\11distrutto!",
  ["_Route17Biker10EndBattleText"] = "Sei\nsoddisfatto?",
  ["_Route17Biker1AfterBattleText"] = "Ci sono\nbegli oggetti giu'\11sulla PISTA\nCICLABILE!",
  ["_Route17Biker1BattleText"] = "Non ci\nsono soldi a\11battere i\nragazzini!",
  ["_Route17Biker1EndBattleText"] = "Spento\nfuori!",
  ["_Route17Biker2AfterBattleText"] = "Potrei\nscaraventarti\11fuori di qui con\nuna panciata!",
  ["_Route17Biker2BattleText"] = "Che\nvuoi, pivello?",
  ["_Route17Biker2EndBattleText"] = "Urca!",
  ["_Route17Biker3AfterBattleText"] = "Adoro\ncorrere in\11discesa!",
  ["_Route17Biker3BattleText"] = "Vai a\nFUCSIAPOLI?",
  ["_Route17Biker3EndBattleText"] = "Schiantato\ne bruciato!",
  ["_Route17Biker4AfterBattleText"] = "Cerchi\navventure?",
  ["_Route17Biker4BattleText"] = "Siamo\nCENTAURI! Stelle\11della strada!",
  ["_Route17Biker4EndBattleText"] = "Fumato!",
  ["_Route17Biker5AfterBattleText"] = "Ho preso\nil mio VOLTORB\11alla CENTRALE\nABANDONATA.",
  ["_Route17Biker5BattleText"] = "Lascia\nche VOLTORB ti\11fulmini!",
  ["_Route17Biker5EndBattleText"] = "Messo al\ntappeto!",
  ["_Route17Biker6AfterBattleText"] = "Forse\nalcuni POKéMON\11hanno bisogno di\nPIETRE per\11evolversi.",
  ["_Route17Biker6BattleText"] = "I miei\nPOKéMON non si\11evolvono! Perché?",
  ["_Route17Biker6EndBattleText"] = "Ma\nguarda te!",
  ["_Route17Biker7AfterBattleText"] = "Scommetto\nche ho perso peso\11qui!",
  ["_Route17Biker7BattleText"] = "Ho\nbisogno di un po'\11di esercizio!",
  ["_Route17Biker7EndBattleText"] = "Uff! Bel\nallenamento!",
  ["_Route17Biker8AfterBattleText"] = "Preparati\na lottare per le\11tue idee!",
  ["_Route17Biker8BattleText"] = "Fai il\nribelle!",
  ["_Route17Biker8EndBattleText"] = "Aaaargh!",
  ["_Route17Biker9AfterBattleText"] = "La\ndiscesa rende\11difficile\nsterzare!",
  ["_Route17Biker9BattleText"] = "Bella\nBICI! Come si\11guida?",
  ["_Route17Biker9EndBattleText"] = "Acciderboli!",
  ["_Route17CyclingRoadEndsSignText"] = "PISTA CICLABILE La\npendenza finisce\11qui!",
  ["_Route17NoticeSign1Text"] = "é un avviso!\nAttenzione agli\11oggetti scartati!",
  ["_Route17NoticeSign2Text"] = "é un avviso! Non\nbuttare la\11partita, butta le\nPOKé BALL!",
  ["_Route17SignText"] = "PERCORSO 17\nAZZURROPOLI\11FUCSIAPOLI",
  ["_Route17TrainerTips1Text"] = "CONSIGLI AGLI\nALLENATORI Tutti i\11POKéMON sono\nunici. Anche\11quelli dello\nstesso tipo e\11livello crescono\ncon ritmi diversi.",
  ["_Route17TrainerTips2Text"] = "CONSIGLI AGLI\nALLENATORI Premi\11il Pulsante A o B\nper restare fermo\11sulla pendenza.",
  ["_Route18CooltrainerM1AfterBattleText"] = "Vorrei\ntanto una BICI!",
  ["_Route18CooltrainerM1BattleText"] = "Controllo\nsempre ogni zona\11erbosa per nuovi\nPOKéMON.",
  ["_Route18CooltrainerM1EndBattleText"] = "Tch!",
  ["_Route18CooltrainerM2AfterBattleText"] = "Nei\nfine settimana\11raccolgo anche\nPOKéMON marini!",
  ["_Route18CooltrainerM2BattleText"] = "Kurukkoo!\nTi piace il mio\11verso da uccello?",
  ["_Route18CooltrainerM2EndBattleText"] = "Dovevo\nproprio\11scocciarti!",
  ["_Route18CooltrainerM3AfterBattleText"] = "Questo\né il mio posto\11preferito per la\ncaccia ai POKéMON!",
  ["_Route18CooltrainerM3BattleText"] = "Questo\né il mio\11territorio! Fuori\ndi qui!",
  ["_Route18CooltrainerM3EndBattleText"] = "Acciderboli!",
  ["_Route18CyclingRoadSignText"] = "PISTA CICLABILE\nVietato l'accesso\11ai pedoni!",
  ["_Route18Gate1FGuardCyclingRoadUphillText"] = "Da qui in poi la\nPISTA CICLABILE é\11tutta in salita.",
  ["_Route18Gate1FGuardExcuseMeText"] = "Ehi tu!",
  ["_Route18Gate1FGuardYouNeedABicycleText"] = "Ti serve una\nBICICLETTA per la\11PISTA CICLABILE!",
  ["_Route18Gate2FLeftBinocularsText"] = "Hai guardato nei\nbinocoli.\11BIANCAVILLA é a\novest!",
  ["_Route18Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli. Ci sono\11persone che\nnuotano!",
  ["_Route18SignText"] = "PERCORSO 18\nAZZURROPOLI\11FUCSIAPOLI",
  ["_Route19CooltrainerM1AfterBattleText"] = "Grazie,\nragazzo! Sono\11pronto per una\nnuotata!",
  ["_Route19CooltrainerM1BattleText"] = "Devo\nscaldarmi prima di\11nuotare!",
  ["_Route19CooltrainerM1EndBattleText"] = "Tutto\nriscaldato!",
  ["_Route19CooltrainerM2AfterBattleText"] = "Attenzione\nai TENTACOOL!",
  ["_Route19CooltrainerM2BattleText"] = "Aspetta!\nTi viene un\11attacco cardiaco!",
  ["_Route19CooltrainerM2EndBattleText"] = "Ooh!\nChe gelido!",
  ["_Route19SignText"] = "PERCORSO MARINO 19\nFUCSIAPOLI ISOLE\11SPUMA",
  ["_Route19Swimmer1AfterBattleText"] = "Posso\nbattere i POKéMON\11a nuoto!",
  ["_Route19Swimmer1BattleText"] = "Adoro\nnuotare! E tu?",
  ["_Route19Swimmer1EndBattleText"] = "Tuffo a\npancia!",
  ["_Route19Swimmer2AfterBattleText"] = "Vedo un\npaio di isole!",
  ["_Route19Swimmer2BattleText"] = "Cosa\nc'é oltre\11l'orizzonte?",
  ["_Route19Swimmer2EndBattleText"] = "Glub!",
  ["_Route19Swimmer3AfterBattleText"] = "Devi\npescare per\11trovare POKéMON\nmarini!",
  ["_Route19Swimmer3BattleText"] = "Ho\nprovato ad\11immergermi per i\nPOKéMON, ma nulla!",
  ["_Route19Swimmer3EndBattleText"] = "Aiuto!",
  ["_Route19Swimmer4AfterBattleText"] = "Guardo\nil mare per\11dimenticare!",
  ["_Route19Swimmer4BattleText"] = "Guardo\nil mare per\11dimenticare!",
  ["_Route19Swimmer4EndBattleText"] = "Ooh!\nChe trauma!",
  ["_Route19Swimmer5AfterBattleText"] = "C'é\nancora molta\11strada per le\nISOLE SPUMA.",
  ["_Route19Swimmer5BattleText"] = "Oh,\nadoro il tuo\11mezzo! Posso\naverlo se vinco?",
  ["_Route19Swimmer5EndBattleText"] = "Oh! Ho\nperso!",
  ["_Route19Swimmer6AfterBattleText"] = "Il mio\nragazzo voleva\11nuotare fino alle\nISOLE SPUMA.",
  ["_Route19Swimmer6BattleText"] = "Nuotare\né fantastico! Le\11scottature no!",
  ["_Route19Swimmer6EndBattleText"] = "Che\nshock!",
  ["_Route19Swimmer7AfterBattleText"] = "Ho un\ncrampo! Glub,\11glub...",
  ["_Route19Swimmer7BattleText"] = "Queste\nacque sono\11traditrici!",
  ["_Route19Swimmer7EndBattleText"] = "Ooh!\nPericoloso!",
  ["_Route19Swimmer8AfterBattleText"] = "LAPRAS\né cosi' grande, ti\11terra' sicuramente\nasciutto.",
  ["_Route19Swimmer8BattleText"] = "Ho\nnuotato fino qui,\11ma sono stanco.",
  ["_Route19Swimmer8EndBattleText"] = "Sono\nesausto...",
  ["_Route1SignText"] = "PERCORSO 1\nBIANCAVILLA\11SMERALDOPOLI",
  ["_Route1Youngster1AlsoGotPokeballsText"] = "Abbiamo anche\ndelle POKé BALL\11per catturare\nPOKéMON!",
  ["_Route1Youngster1GotPotionText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_Route1Youngster1MartSampleText"] = "Ciao! Lavoro in un\nPOKé MARKET. é un\11negozio utile,\nvisitalo a\11SMERALDOPOLI. Sai\nche c'é? Ti do' un\11campione! Eccolo!",
  ["_Route1Youngster1NoRoomText"] = "Hai troppa roba\ncon te!",
  ["_Route1Youngster2Text"] = "Vedi quei\ndislivelli lungo\11la strada? é un\npo' spaventoso, ma\11puoi saltare giu'.\nPuoi tornare a\11BIANCAVILLA piu'\nrapidamente in\11quel modo.",
  ["_Route20CooltrainerMAfterBattleText"] = "I miei\nuccelli non\11possono portarmi\nindietro con VOLO!",
  ["_Route20CooltrainerMBattleText"] = "Sono\narrivato qui in\11sella al mio\nPOKéMON volatile!",
  ["_Route20CooltrainerMEndBattleText"] = "Oh no!",
  ["_Route20SeafoamIslandsSignText"] = "ISOLE SPUMA",
  ["_Route20Swimmer1AfterBattleText"] = "Vorrei\ntanto cavalcare i\11POKéMON.",
  ["_Route20Swimmer1BattleText"] = "Qui\nl'acqua é bassa.",
  ["_Route20Swimmer1EndBattleText"] = "Splash!",
  ["_Route20Swimmer2AfterBattleText"] = "C'é\nun'enorme caverna\11sotto quest'isola.",
  ["_Route20Swimmer2BattleText"] = "SPUMA é\nun rifugio\11tranquillo!",
  ["_Route20Swimmer2EndBattleText"] = "Smetti!",
  ["_Route20Swimmer3AfterBattleText"] = "Vuoi\ngalleggiare con\11me?",
  ["_Route20Swimmer3BattleText"] = "Adoro\ngalleggiare\11insieme ai pesci!",
  ["_Route20Swimmer3EndBattleText"] = "Ahi!",
  ["_Route20Swimmer4AfterBattleText"] = "Una\nvolta SPUMA era\11un'isola sola!",
  ["_Route20Swimmer4BattleText"] = "Sei in\nvacanza anche tu?",
  ["_Route20Swimmer4EndBattleText"] = "Nessuna\npieta'!",
  ["_Route20Swimmer5AfterBattleText"] = "Avrei\ndovuto allenare i\11POKéMON, non me\nstesso!",
  ["_Route20Swimmer5BattleText"] = "Guarda\nil mio fisico\11bestiale!",
  ["_Route20Swimmer5EndBattleText"] = "Imbranato!",
  ["_Route20Swimmer6AfterBattleText"] = "Cavalcare\nun POKéMON sembra\11proprio forte!",
  ["_Route20Swimmer6BattleText"] = "Perché\ncavalchi un\11POKéMON? Non sai\nnuotare?",
  ["_Route20Swimmer6EndBattleText"] = "Ahi!\nSilurato!",
  ["_Route20Swimmer7AfterBattleText"] = "Le mie\nperle verranno\11piu' grandi dentro\nCLOYSTER?",
  ["_Route20Swimmer7BattleText"] = "Il mio\nragazzo mi ha dato\11grandi perle!",
  ["_Route20Swimmer7EndBattleText"] = "Non\ntoccare le mie\11perle!",
  ["_Route20Swimmer8AfterBattleText"] = "I\nPOKéMON hanno\11occupato una villa\nabbandonata a\11ISOLA CANNELLA!",
  ["_Route20Swimmer8BattleText"] = "Ho\nnuotato fino a qui\11da ISOLA CANNELLA!",
  ["_Route20Swimmer8EndBattleText"] = "Sono\ncosi' deluso!",
  ["_Route20Swimmer9AfterBattleText"] = "CANNELLA\né un'isola\11vulcanica!",
  ["_Route20Swimmer9BattleText"] = "CANNELLA,\na ovest, ha un\11LABORATORIO per\nPOKéMON.",
  ["_Route20Swimmer9EndBattleText"] = "Aspetta!",
  ["_Route21Fisher1AfterBattleText"] = "Non\nriesco a prendere\11niente di buono!",
  ["_Route21Fisher1BattleText"] = "Vuoi\nsapere se i pesci\11abboccano?",
  ["_Route21Fisher1EndBattleText"] = "Accidenti!",
  ["_Route21Fisher2AfterBattleText"] = "Sembra\nche io peschi solo\11MAGIKARP!",
  ["_Route21Fisher2BattleText"] = "Ho\nfatto un grosso\11bottino! Ci provi?",
  ["_Route21Fisher2EndBattleText"] = "Maledetti\nMAGIKARP!",
  ["_Route21Fisher3AfterBattleText"] = "Ero\nsolo arrabbiato\11perché non\nriuscivo a\11prendere nulla.",
  ["_Route21Fisher3BattleText"] = "Ehi,\nnon spaventare i\11pesci!",
  ["_Route21Fisher3EndBattleText"] = "Scusa!\nNon volevo!",
  ["_Route21Fisher4AfterBattleText"] = "Oh\naspetta! Ha\11abboccato! Evviva!",
  ["_Route21Fisher4BattleText"] = "Tienimi\ncompagnia finché\11non prendo\nqualcosa!",
  ["_Route21Fisher4EndBattleText"] = "Questo\nha fatto passare\11il tempo.",
  ["_Route21Swimmer1AfterBattleText"] = "Mi\npiacciono anche i\11monti!",
  ["_Route21Swimmer1BattleText"] = "Il mare\npurifica il mio\11corpo e l'anima!",
  ["_Route21Swimmer1EndBattleText"] = "Ayah!",
  ["_Route21Swimmer2AfterBattleText"] = "A chi\nassomiglio? A un\11salvagente bucato?\nSparisci!",
  ["_Route21Swimmer2BattleText"] = "Cosa\nc'é che non va se\11nuoto?",
  ["_Route21Swimmer2EndBattleText"] = "Colpo\nbasso!",
  ["_Route21Swimmer3AfterBattleText"] = "Dove\nhai catturato i\11tuoi POKéMON?",
  ["_Route21Swimmer3BattleText"] = "Ho\ncatturato tutti i\11miei POKéMON in\nmare!",
  ["_Route21Swimmer3EndBattleText"] = "Sub!!\nGiu'!!",
  ["_Route21Swimmer4AfterBattleText"] = "Sono\nesausto! Ma mi\11restano la gara di\nbici e la\11maratona!",
  ["_Route21Swimmer4BattleText"] = "Ora\nsono impegnato in\11un triathlon!",
  ["_Route21Swimmer4EndBattleText"] = "Ansimante...\nansimante...",
  ["_Route21Swimmer5AfterBattleText"] = "Sono\ncotto al sole!",
  ["_Route21Swimmer5BattleText"] = "Ahh!\nSenti il sole e il\11vento!",
  ["_Route21Swimmer5EndBattleText"] = "Ahi! Ho\nperso!",
  ["_Route22GateGuardGoRightAheadText"] = "Oh! Quella é la\nMEDAGLIA SASSO!\11Prendi pure!",
  ["_Route22GateGuardICantLetYouPassText"] = "Le regole sono\nregole. Non posso\11lasciarti passare.",
  ["_Route22GateGuardNoBoulderbadgeText"] = "Solo i veri abili\nallenatori possono\11passare. Non hai\nancora la MEDAGLIA\11SASSO!",
  ["_Route22PokemonLeagueSignText"] = "LEGA POKéMON\nIngresso\11Principale",
  ["_Route22Rival1DefeatedText"] = "Acciderboli! Hai\navuto solo\11fortuna!",
  ["_Route22Rival1VictoryText"] = "{RIVAL}: Cosa?\nPerché ho 2\11POKéMON? Dovresti\ncatturarne altri\11anche tu!",
  ["_Route22Rival2DefeatedText"] = "Cosa!? Sono stato\nsolo disattento!",
  ["_Route22Rival2VictoryText"] = "{RIVAL}: Hahaha!\n{PLAYER}! é il tuo\11meglio? Non vali\nun tubo, amico! Va\11ad allenarti\nancora! Perdente!",
  ["_Route22RivalAfterBattleText1"] = "Ho\nsentito che la\11LEGA POKéMON ha\nmolti allenatori\11forti! Devo capire\ncome superarli!\11Smettila di\nciondolare e datti\11una mossa!",
  ["_Route22RivalAfterBattleText2"] = "Questo mi\nha sganciato! Sono\11pronto per la LEGA\nPOKéMON! {PLAYER},\11ti serve piu'\npratica! Ma lo sai\11anche tu! Me ne\nvado. Ci si vede!",
  ["_Route22RivalBeforeBattleText1"] = "{RIVAL}:\nEhi! {PLAYER}! Vai\11alla LEGA POKéMON?\nScordatelo!\11Probabilmente non\nhai MEDAGLIE! La\11guardia non ti\nfara' passare! A\11proposito, i tuoi\nPOKéMON sono\11diventati piu'\nforti?",
  ["_Route22RivalBeforeBattleText2"] = "{RIVAL}:\nCosa? {PLAYER}! Che\11sorpresa vederti\nqui! Quindi vai\11alla LEGA POKéMON?\nHai raccolto anche\11tutte le MEDAGLIE?\nForte! Allora ti\11concero' per le\nfeste {PLAYER} come\11riscaldamento per\nla LEGA! Vieni\11avanti!",
  ["_Route23GoRightAheadText"] = "Bene allora!\nPrendi pure!",
  ["_Route23OhThatIsTheBadgeText"] = "Puoi passare solo\nse hai con te\11{RAM:wNameBuffer}! Oh!\nQuella é\11{RAM:wNameBuffer}!",
  ["_Route23VictoryRoadGateSignText"] = "Varco della Via\nVittoria - LEGA\11POKéMON",
  ["_Route23YouDontHaveTheBadgeYetText"] = "Puoi passare solo\nse hai con te\11{RAM:wNameBuffer}! Non\nhai ancora\11{RAM:wNameBuffer}! Devi\naverla per\11raggiungere la\nLEGA POKéMON!",
  ["_Route24CooltrainerF1AfterBattleText"] = "Ce\nl'ho messa tutta,\11non ho rimpianti!",
  ["_Route24CooltrainerF1BattleText"] = "Sono\nla n. 4! Ti stai\11stancando?",
  ["_Route24CooltrainerF1EndBattleText"] = "Ho\nperso anche io!",
  ["_Route24CooltrainerF2AfterBattleText"] = "Ce\nl'ho messa tutta,\11non ho rimpianti!",
  ["_Route24CooltrainerF2BattleText"] = "Sono\nla seconda! Ora si\11fa sul serio!",
 ["_Route24CooltrainerF2EndBattleText"] = "Come\nho potuto perdere?",
  ["_Route24CooltrainerM1DefeatedText"] = "Arrgh! Ci sai\nfare!",
  ["_Route24CooltrainerM1JoinTeamRocketText"] = "A proposito, ti\nandrebbe di\11entrare nel TEAM\nROCKET? Siamo un\11gruppo dedicato al\nmale grazie ai\11POKéMON! Vuoi\nunirti? Sei\11sicuro? Forza,\nunisciti a noi! Ti\11sto dicendo di\nunirti! OK, hai\11bisogno di\nconvinzione! Ti\11faro' un'offerta\nche non potrai\11rifiutare!",
  ["_Route24CooltrainerM1NoRoomText"] = "Non hai abbastanza\nspazio!",
  ["_Route24CooltrainerM1ReceivedNuggetText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_Route24CooltrainerM1YouBeatOurContestText"] = "Complimenti! Hai\nbattuto i nostri\11allenatori!",
  ["_Route24CooltrainerM1YouCouldBecomeATopLeaderText"] = "Con le tue\ncapacita' potresti\11diventare un capo\nnel TEAM ROCKET!",
  ["_Route24CooltrainerM1YouJustEarnedAPrizeText"] = "Hai appena vinto\nun premio\11favoloso!",
  ["_Route24CooltrainerM2AfterBattleText"] = "Mi\nsono nascosto\11perché la gente\nsul ponte mi\11spaventava!",
  ["_Route24CooltrainerM2BattleText"] = "Ho\nvisto la tua\11impresa dall'erba!",
  ["_Route24CooltrainerM2EndBattleText"] = "Non\ncredevo!",
  ["_Route24CooltrainerM3AfterBattleText"] = "Ce\nl'ho messa tutta,\11non ho rimpianti!",
  ["_Route24CooltrainerM3BattleText"] = "OK!\nSono il n. 5! Ti\11faro' a pezzi!",
  ["_Route24CooltrainerM3EndBattleText"] = "Urca!\nTroppo forte!",
  ["_Route24Youngster1AfterBattleText"] = "Ce l'ho\nmessa tutta, non\11ho rimpianti!",
  ["_Route24Youngster1BattleText"] = "Ecco il n.\n3! Non saro' un\11osso facile!",
  ["_Route24Youngster1EndBattleText"] = "Ahi!\nSchiacciato al\11suolo!",
  ["_Route24Youngster2AfterBattleText"] = "Ce l'ho\nmessa tutta, non\11ho rimpianti!",
  ["_Route24Youngster2BattleText"] = "Questo é il\nPONTE NUGGET!\11Batti 5 di noi e\nvinci un premio\11favoloso! Pensi di\nfarcela?",
  ["_Route24Youngster2EndBattleText"] = "Urca! Roba\nforte!",
  ["_Route25BillSignText"] = "VILLA MARINA Qui\nabita BILL",
  ["_Route25CooltrainerF1AfterBattleText"] = "Vorrei\nche il mio ragazzo\11fosse bravo come\nte!",
  ["_Route25CooltrainerF1BattleText"] = "Ciao!\nIl mio ragazzo é\11un figo!",
  ["_Route25CooltrainerF1EndBattleText"] = "Ero\nin cattive\11condizioni!",
  ["_Route25CooltrainerF2AfterBattleText"] = "Vieni\ndal MONTE LUNA?\11Posso avere un\nCLEFAIRY?",
  ["_Route25CooltrainerF2BattleText"] = "Il\nmio amico ha un\11POKéMON carino.\nChe invidia!",
  ["_Route25CooltrainerF2EndBattleText"] = "Non\nsono cosi'\11invidiosa!",
  ["_Route25CooltrainerMAfterBattleText"] = "Pazienza.\nLa mia ragazza mi\11consolera'.",
  ["_Route25CooltrainerMBattleText"] = "Sono\nun tipo forte. Ho\11una ragazza!",
  ["_Route25CooltrainerMEndBattleText"] = "Ahi,\naccidenti...",
  ["_Route25Hiker1AfterBattleText"] = "Acciderboli!\nUno ZUBAT mi ha\11morso laggiu'.",
  ["_Route25Hiker1BattleText"] = "Vengo\ngiu' dal MONTE\11LUNA, ma sono\npronto!",
  ["_Route25Hiker1EndBattleText"] = "Ti sei\nimpegnato duro!",
  ["_Route25Hiker2AfterBattleText"] = "Il\ncollezionista ha\11moltissimi POKéMON\nrari.",
  ["_Route25Hiker2BattleText"] = "Vado a\ntrovare un\11collezionista di\nPOKéMON al capo!",
  ["_Route25Hiker2EndBattleText"] = "Mi hai\npreso.",
  ["_Route25Hiker3AfterBattleText"] = "Il\nsentiero in basso\11é una scorciatoia\nper CELESTOPOLI.",
  ["_Route25Hiker3BattleText"] = "Vai a\ntrovare BILL?\11Prima lottiamo!",
  ["_Route25Hiker3EndBattleText"] = "Ci sai\nproprio fare.",
  ["_Route25Youngster1AfterBattleText"] = "Tutti i\nPOKéMON hanno\11debolezze. é\nmeglio allevarne\11di vari tipi.",
  ["_Route25Youngster1BattleText"] = "Gli\nallenatori locali\11vengono qui ad\nallenarsi!",
  ["_Route25Youngster1EndBattleText"] = "Te la cavi.",
  ["_Route25Youngster2AfterBattleText"] = "Sulla M.N.\nANNA ho visto\11allenatori di\ntutto il mondo.",
  ["_Route25Youngster2BattleText"] = "Mio padre\nmi ha portato a\11una festa\nfantastica sulla\11M.N. ANNA a\nARANCIOPOLI!",
  ["_Route25Youngster2EndBattleText"] = "Non sono\narrabbiato!",
  ["_Route25Youngster3AfterBattleText"] = "Se il tuo\nPOKéMON é confuso\11o dorme,\nsostituiscilo!",
  ["_Route25Youngster3BattleText"] = "Sapevo che\navrei dovuto\11lottare con te!",
  ["_Route25Youngster3EndBattleText"] = "Sapevo che\navrei perso!",
  ["_Route2DiglettsCaveSignText"] = "GROTTA DIGLETT",
  ["_Route2GateOaksAideFlashExplanationText"] = "La MN FLASH\nillumina anche i\11sotterranei piu'\nbui.",
  ["_Route2GateYoungsterText"] = "Una volta che un\nPOKéMON impara\11FLASH, puoi\nattraversare la\11GROTTA DIGLETT.",
  ["_Route2SignText"] = "PERCORSO 2\nSMERALDOPOLI\11PLUMOPOLI",
  ["_Route2TradeHouseScientistText"] = "Un POKéMON svenuto\nnon puo' lottare.\11Ma puo' ancora\nusare mosse come\11TAGLIO!",
  ["_Route3CooltrainerF1AfterBattleText"] = "Smettila\ndi fissare se non\11vuoi lottare!",
  ["_Route3CooltrainerF1BattleText"] = "Mi\nhai guardato,\11vero?",
  ["_Route3CooltrainerF1EndBattleText"] = "Sei\nproprio cattivo!",
  ["_Route3CooltrainerF2AfterBattleText"] = "Evita\nle lotte non\11facendoti vedere\ndalla gente!",
  ["_Route3CooltrainerF2BattleText"] = "Quella\ntua occhiata, é\11cosi' intrigante!",
  ["_Route3CooltrainerF2EndBattleText"] = "Sii\ngentile!",
  ["_Route3CooltrainerF3AfterBattleText"] = "Il\nPERCORSO 4 é ai\11piedi del MONTE\nLUNA.",
  ["_Route3CooltrainerF3BattleText"] = "Eek!\nMi hai toccato?",
  ["_Route3CooltrainerF3EndBattleText"] = "Tutto\nqui?",
  ["_Route3SignText"] = "PERCORSO 3 MONTE\nLUNA",
  ["_Route3Text1"] = "Uff... Meglio\nriposare un po'...\11Mh... Quel tunnel\nda CELESTOPOLI ti\11sfinisce!",
  ["_Route3Youngster1AfterBattleText"] = "Ci sono\naltri tipi di\11POKéMON oltre a\nquelli del bosco!",
  ["_Route3Youngster1BattleText"] = "Ehi! Ti ho\nvisto nel BOSCO\11SMERALDOPOLI!",
  ["_Route3Youngster1EndBattleText"] = "Mi hai\nbattuto di nuovo!",
  ["_Route3Youngster2AfterBattleText"] = "Stai\ndepositando i\11POKéMON sul PC?\nOgni BOX puo'\11contenerne 20!",
  ["_Route3Youngster2BattleText"] = "Ciao! Mi\npiacciono i\11pantaloncini! Sono\ncomodi e facili da\11indossare!",
  ["_Route3Youngster2EndBattleText"] = "Non ci\nposso credere!",
  ["_Route3Youngster3AfterBattleText"] = "Se un BOX\nPOKéMON nel PC si\11riempie, passa a\nun altro!",
  ["_Route3Youngster3BattleText"] = "Sei un\nallenatore?\11Lottiamo!",
  ["_Route3Youngster3EndBattleText"] = "Se avessi\navuto nuovi\11POKéMON avrei\nvinto!",
  ["_Route3Youngster4AfterBattleText"] = "Indosso\nsempre\11pantaloncini,\nanche in inverno!",
  ["_Route3Youngster4BattleText"] = "Ehi! Non\nporti i\11pantaloncini!",
  ["_Route3Youngster4EndBattleText"] = "Perso!\nPerso! Perso!",
  ["_Route3Youngster5AfterBattleText"] = "I POKéMON\nallenati sono piu'\11forti di quelli\nselvatici!",
  ["_Route3Youngster5BattleText"] = "Puoi\nlottare contro il\11mio nuovo POKéMON!",
  ["_Route3Youngster5EndBattleText"] = "Fatto e\nfinito!",
  ["_Route4CooltrainerF1Text"] = "Ahi! Sono\ninciampata su un\11POKéMON roccioso,\nGEODUDE!",
  ["_Route4CooltrainerF2AfterBattleText"] = "Forse\nnon ci sono altri\11funghi qui. Credo\ndi averli presi\11tutti.",
  ["_Route4CooltrainerF2BattleText"] = "Sono\nvenuta a prendere\11il mio POKéMON\nfungo!",
  ["_Route4CooltrainerF2EndBattleText"] = "Oh!\nIl mio caro\11POKéMON fungo!",
  ["_Route4MtMoonSignText"] = "MONTE LUNA\nIngresso Tunnel",
  ["_Route4SignText"] = "PERCORSO 4 MONTE\nLUNA CELESTOPOLI",
  ["_Route5UndergroundPathSignText"] = "SOTTERRANEO\nCELESTOPOLI\11ARANCIOPOLI",
  ["_Route6CooltrainerAfterBattleText"] = "Sussurro...\nsussurro...",
  ["_Route6CooltrainerF1BattleText"] = "Scusa!\nQuesta é una\11conversazione\nprivata!",
  ["_Route6CooltrainerF1EndBattleText"] = "Ugh!\nOdio perdere!",
  ["_Route6CooltrainerF2AfterBattleText"] = "Voglio\ndiventare piu'\11forte! Qual é il\ntuo segreto?",
  ["_Route6CooltrainerF2BattleText"] = "Io?\nBeh, OK.\11Giochiamo!",
  ["_Route6CooltrainerF2EndBattleText"] = "Non\nha funzionato!",
  ["_Route6CooltrainerM1BattleText"] = "Chi\nc'é? Smettila di\11origliare!",
  ["_Route6CooltrainerM1EndBattleText"] = "Proprio\nnon riesco a\11vincere!",
  ["_Route6CooltrainerM2AfterBattleText"] = "Dovrei\nportare con me\11piu' POKéMON per\nsicurezza.",
  ["_Route6CooltrainerM2BattleText"] = "Mh?\nVuoi parlare con\11me?",
  ["_Route6CooltrainerM2EndBattleText"] = "Non ho\niniziato io!",
  ["_Route6UndergroundPathSignText"] = "SOTTERRANEO\nCELESTOPOLI\11ARANCIOPOLI",
  ["_Route6Youngster1AfterBattleText"] = "Mi\npiacciono gli\11insetti, torno nel\nBOSCO\11SMERALDOPOLI.",
  ["_Route6Youngster1BattleText"] = "Non ci sono\nmolti insetti qui\11fuori.",
  ["_Route6Youngster1EndBattleText"] = "No!\nScherzi!",
  ["_Route6Youngster2AfterBattleText"] = "I miei\nPOKéMON sono\11deboli? O sono\nscarso io?",
  ["_Route6Youngster2BattleText"] = "Non ti ho\nmai visto in giro!\11Ci sai fare?",
  ["_Route6Youngster2EndBattleText"] = "Ci sai\nproprio fare!",
  ["_Route7UndergroundPathSignText"] = "SOTTERRANEO\nAZZURROPOLI\11LAVANDONIA",
  ["_Route8CooltrainerF1AfterBattleText"] = "Quando\ni POKéMON crescono\11diventano brutti!\nNon dovrebbero\11evolversi!",
  ["_Route8CooltrainerF1BattleText"] = "Mi\npiace NIDORAN,\11percio' li\nraccolgo!",
  ["_Route8CooltrainerF1EndBattleText"] = "Perché?\nPerché??",
  ["_Route8CooltrainerF2AfterBattleText"] = "Penso\nche PIDGEY e\11RATTATA siano\ncarini!",
  ["_Route8CooltrainerF2BattleText"] = "MEOWTH\né cosi' carino,\11miao, miao, miao!",
  ["_Route8CooltrainerF2EndBattleText"] = "Miao!",
  ["_Route8CooltrainerF3AfterBattleText"] = "La\nguardia di\11ZAFFERANOPOLI non\nci fa passare. é\11proprio cattiva!",
  ["_Route8CooltrainerF3BattleText"] = "Dobbiamo\nsembrare\11stupiducci a star\nqui cosi'!",
  ["_Route8CooltrainerF3EndBattleText"] = "Guarda\ncosa hai fatto!",
  ["_Route8CooltrainerF4AfterBattleText"] = "Ho\nsentito che\11CLEFAIRY si evolve\nse esposto a una\11PIETRALUNARE.",
  ["_Route8CooltrainerF4BattleText"] = "Qual\né un POKéMON\11carino, rotondo e\nsoffice?",
  ["_Route8CooltrainerF4EndBattleText"] = "Fermati!\nNon essere cosi'\11cattivo col mio\nCLEFAIRY!",
  ["_Route8Gambler1AfterBattleText"] = "La dea\nbendata non é con\11me oggi!",
  ["_Route8Gambler1BattleText"] = "Bene!\nLanciamo i dadi!",
  ["_Route8Gambler1EndBattleText"] = "Acciderboli!\nMancato di poco!",
  ["_Route8Gambler2AfterBattleText"] = "Il\ngioco d'azzardo e\11i POKéMON sono\ncome le ciliegie!\11Non puoi smettere!",
  ["_Route8Gambler2BattleText"] = "Sono un\ntipo che rischia\11sempre!",
  ["_Route8Gambler2EndBattleText"] = "Mancato\nil grosso colpo!",
  ["_Route8SuperNerd1AfterBattleText"] = "Me la\ncavo meglio a\11scuola che qui!",
  ["_Route8SuperNerd1BattleText"] = "Te la\ncavi coi POKéMON,\11ma come vani in\nchimica?",
  ["_Route8SuperNerd1EndBattleText"] = "Ahi!\nCollasso nucleare!",
  ["_Route8SuperNerd2AfterBattleText"] = "Vai con\nGRIMER prima...\11e... ...e...\npoi...",
  ["_Route8SuperNerd2BattleText"] = "Ci\nvuole strategia\11per vincere qui!",
  ["_Route8SuperNerd2EndBattleText"] = "Non ha\nsenso logico!",
  ["_Route8SuperNerd3AfterBattleText"] = "Siamo\nbloccati qui a\11causa dei cancelli\ndi ZAFFERANOPOLI",
  ["_Route8SuperNerd3BattleText"] = "La\nscuola é\11divertente, ma\nanche i POKéMON.",
  ["_Route8SuperNerd3EndBattleText"] = "Resto a\nstudiare.",
  ["_Route8UndergroundSignText"] = "SOTTERRANEO\nAZZURROPOLI\11LAVANDONIA",
  ["_Route9CooltrainerF1AfterBattleText"] = "Ti\nserve luce per\11attraversare quel\ntunnel buio piu'\11avanti.",
  ["_Route9CooltrainerF1BattleText"] = "Hai\ncon te dei\11POKéMON! Sei mio!",
  ["_Route9CooltrainerF1EndBattleText"] = "Mi\nhai ingannato!",
  ["_Route9CooltrainerF2AfterBattleText"] = "Hai\ntalento! In bocca\11al lupo!",
  ["_Route9CooltrainerF2BattleText"] = "Non\nosare compatirmi!",
  ["_Route9CooltrainerF2EndBattleText"] = "No!\nSei troppo forte!",
  ["_Route9CooltrainerM1AfterBattleText"] = "Continua\na camminare!",
  ["_Route9CooltrainerM1BattleText"] = "Chi é\nquello che cammina\11con quei\nbellissimi\11POKéMON?",
  ["_Route9CooltrainerM1EndBattleText"] = "Spento\ncome una\11lampadina!",
  ["_Route9CooltrainerM2AfterBattleText"] = "Vai\nalla GROTTA\11DIGLETT anche tu?",
  ["_Route9CooltrainerM2BattleText"] = "Prendo\nla GROTTA DIGLETT\11per andare a\nLAVANDONIA...",
  ["_Route9CooltrainerM2EndBattleText"] = "Non\nsono all'altezza!",
  ["_Route9Hiker1AfterBattleText"] = "Hai\navuto fegato a\11venirmi contro,\neh?",
  ["_Route9Hiker1BattleText"] = "Bwahaha!\nOttimo! Mi\11annoiavo, eh!",
  ["_Route9Hiker1EndBattleText"] = "Vieni\npure, eh! Oh\11aspetta. Non ho\npiu' POKéMON!",
  ["_Route9Hiker2AfterBattleText"] = "Hahaha!\nI ragazzi devono\11essere tosti!",
  ["_Route9Hiker2BattleText"] = "Hahaha!\nNon sei un bel\11peperino!",
  ["_Route9Hiker2EndBattleText"] = "Che\ncos'é?",
  ["_Route9Hiker3AfterBattleText"] = "Hahahaha!\nNoi tipacci\11ridiamo sempre!",
  ["_Route9Hiker3BattleText"] = "Hahahaha!\nForza, amico!",
  ["_Route9Hiker3EndBattleText"] = "Hahahaha!\nMi hai battuto\11lealmente!",
  ["_Route9SignText"] = "PERCORSO 9\nCELESTOPOLI GROTTA\11DIGLETT",
  ["_Route9Youngster1AfterBattleText"] = "Devo\nraccogliere piu'\11di qualche insetto\nper\11fortificarmi...",
  ["_Route9Youngster1BattleText"] = "Mi alzo\npresto ogni giorno\11per far crescere i\nPOKéMON dai\11bozzoli!",
  ["_Route9Youngster1EndBattleText"] = "COSA? Che\ntotale perdita di\11tempo!",
  ["_Route9Youngster2AfterBattleText"] = "Se non ti\npiacciono i\11POKéMON insetto,\nmi stai\11antipatico!",
  ["_Route9Youngster2BattleText"] = "Vai, mio\nsuper POKéMON\11insetto!",
  ["_Route9Youngster2EndBattleText"] = "I miei\ninsetti...",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "Hai\nferito il mio\11povero POKéMON!\nPrendo a pretese\11che tu lo curi in\nun CENTRO POKéMON!",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "Ho\nraccolto questi\11POKéMON in tutto\nil mondo!",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "Oh\nno! Ho girato il\11mondo per\ntrovarli!",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "Dovresti\nessere gentile con\11gli amici!",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "Viaggio\nda solo nei miei\11viaggi! I POKéMON\nsono i miei unici\11amici!",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "I miei,\nmiei amici...",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "Voglio\nessere lasciato\11solo! Fuori!",
  ["_Route6CooltrainerM2BattleText"] = "Tu,\nmarmocchio! Come\11osi irrompere!",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "Uhm!\nBimbo maleducato!",
  ["_SSAnne1FRoomsGentleman3Text"] = "Ssh! Sono un\nagente di POLIZIA!\11Sulle tracce del\nTEAM ROCKET!",
  ["_SSAnne1FRoomsGirl1Text"] = "Cameriere, vorrei\nuna torta di\11ciliegie, per\nfavore!",
  ["_SSAnne1FRoomsGirl2Text"] = "Facciamo una\ncrociera intorno\11al mondo.",
  ["_SSAnne1FRoomsLittleGirlText"] = "Viaggio sempre con\nWIGGLYTUFF!",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "Una crociera é\nelegante ma\11accogliente!",
  ["_SSAnne1FRoomsWigglytuffText"] = "WIGGLYTUFF: Puup\npupuu!",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Diventiamo\namici, OK? Cosi'\11potremo scambiare\nPOKéMON!",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "Adoro i\nPOKéMON! E tu?",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "Wow! Sei\nfantastico!",
  ["_SSAnne1FSailorText"] = "I passeggeri sono\nagitati! Potresti\11essere sfidato dai\npiu' annoiati!",
  ["_SSAnne1FWaiterText"] = "Bonjour! Sono il\ncameriere di\11questa nave! Saro'\nfelice di servirti\11qualsiasi cosa\ndesideri! Ah! Il\11tipo forte e\nsilenzioso!",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Ho\nsentito che a\11bordo c'era un\nesperto di TAGLIO.\11Ma era solo un\nvecchio mal di\11mare! Comunque\nTAGLIO é molto\11utile! Dovresti\nandare a vederlo!\11Ci si vede!",
  ["_SSAnne2FRivalDefeatedText"] = "Uhm! Almeno stai\nallevando i tuoi\11POKéMON!",
  ["_SSAnne2FRivalText"] = "{RIVAL}: Bonjour!\n{PLAYER}! Che\11sorpresa vederti\nqui! {PLAYER}, sei\11stato invitato\ndavvero? Come va\11col tuo POKéDEX?\nIo ne ho gia'\11presi 40 tipi,\namico! Ce ne sono\11di ogni tipo\novunque! Cerca\11nelle zone erbose!",
  ["_SSAnne2FRivalVictoryText"] = "{PLAYER}! Che hai,\nil mal di mare?\11Dovresti darti una\nmossa, amico!",
  ["_SSAnne2FRoomsBeautyText"] = "Sento che molta\ngente ha il mal di\11mare!",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "Il CAPITANO\nsembrava molto\11malato e pallido!",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "Oh,\nadoro i tuoi forti\11POKéMON!",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Non\nti ho mai visto\11alla festa.",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "Prendila\ncon filosofia!",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "La\nfesta? La festa\11sulla nave\ndovrebbe essere\11finita ormai.",
  ["_SSAnne2FRoomsFisherBattleText"] = "Guarda\nche cosa ho\11pescato!",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "Ho\nfinito le scorte!",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "15 anni\nfa avrei vinto di\11sicuro!",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "Gareggiare\ncon i giovani mi\11mantiene\ngiovanile.",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "Bella\nlotta! Ah, mi\11sento di nuovo\ngiovane!",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "Preferisco\nPOKéMON forti e\11rari.",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "Quale\npreferisci, un\11POKéMON forte o\nraro?",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "Devo\nsalutarti!",
  ["_SSAnne2FRoomsGentleman3Text"] = "In tutti i miei\nviaggi non ho mai\11visto un POKéMON\ndormire cosi'! Era\11qualcosa di\nsimile!",
  ["_SSAnne2FRoomsGentleman4Text"] = "Ah si', ho visto\nalcuni POKéMON\11traghettare la\ngente sull'acqua!",
  ["_SSAnne2FRoomsGentleman5Text"] = "Sei stato alla\nZONA SAFARI a\11FUCSIAPOLI?\nC'erano tanti tipi\11rarissimi di\nPOKéMON!!",
  ["_SSAnne2FRoomsGrampsText"] = "I POKéMON possono\nTAGLIARE piccoli\11arbusti.",
  ["_SSAnne2FRoomsLittleBoyText"] = "Io e il mio babbo\npensiamo che la\11ZONA SAFARI sia\nmagnifica!",
  ["_SSAnne2FWaiterText"] = "Questa nave é una\nnave di lusso per\11allenatori! A ogni\nporto facciamo\11feste con\ninvitati!",
  ["_SSAnne3FSailorText"] = "Il nostro CAPITANO\né un maestro di\11spada! Insegna\nanche TAGLIO ai\11POKéMON!",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "Volevo\nfare anche te mio\11assistente!",
  ["_SSAnneB1FRoomsFisherBattleText"] = "Salve\nstraniero! Fermati\11a chiacchierare!\nTutti i miei\11POKéMON provengono\ndal mare!",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "Acciderboli!\nQuello mi é\11scappato!",
  ["_SSAnneB1FRoomsMachokeText"] = "MACHOKE: Gwoh!\nGoggoh!",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "Haha!\nVuoi fare il\11marinaio,\ncompagno?",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "Sai cosa\ndicono su marinai\11e lotte!",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "Esatto!\nBel match,\11compagno!",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "Hai\nvisto il GURU\11PESCATORE a\nARANCIOPOLI?",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "Il mio\norgoglio di\11marinaio é in\ngioco!",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "Il tuo\nspirito mi ha\11affondato!",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "Abbiamo\npreso tutti i\11POKéMON mentre\neravamo in mare!",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "Anche\nnoi marinai\11abbiamo POKéMON!",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "OK, non\nte la cavi male.",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "I\nPOKéMON marini\11vivono in acque\nprofonde. Ti serve\11un AMO!",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "Mi\npiacciono i\11pivelli vispi come\nte!",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "Argh!\nPerso!",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "A volte\nqualche medusa\11alla deriva\nfinisce sulla\11nave.",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "Compagno,\ncamminerai con\11l'asse se perdi!",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "Argh!\nBattuto da un\11ragazzino!",
  ["_SSAnneB1FRoomsSuperNerdText"] = "Il mio amico\nMACHOKE é\11fortissimo! Ha\nabbastanza FORZA\11per spostare\ngrandi massi!",
  ["_SSAnneBowCooltrainerMText"] = "Urf. Sto male.\nSono uscito a\11prendere aria.",
  ["_SSAnneBowSailor1Text"] = "Scrofare i ponti é\nun lavoro duro!",
  ["_SSAnneBowSailor2AfterBattleText"] = "Quanti\ntipi di POKéMON\11crediti che ci\nsiano in tutto?",
  ["_SSAnneBowSailor2BattleText"] = "Ehi\ncompagno! Facciamo\11un saltello!",
  ["_SSAnneBowSailor2EndBattleText"] = "Sei\nimpressionante!",
  ["_SSAnneBowSailor3AfterBattleText"] = "Mio\npadre ha detto che\11ci sono 100 tipi\ndi POKéMON.\11Secondo me ce ne\nsono di piu'.",
  ["_SSAnneBowSailor3BattleText"] = "Ahoi\nla'! Hai il mal di\11mare?",
  ["_SSAnneBowSailor3EndBattleText"] = "Sono\nstato solo\11distratto!",
  ["_SSAnneBowSuperNerdText"] = "La festa é finita.\nLa nave partira'\11presto.",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "Oh no! Non hai\nabbastanza spazio!",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "CAPITANO: Uff!\nGrazie! Sto molto\11meglio! Vuoi\nvedere la mia\11tecnica TAGLIO? Te\nla mostrerei se\11non stessi male...\nLo so! Prendi\11questa! Insegnala\nai tuoi POKéMON e\11potrai TAGLIARE\nogni volta!",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "CAPITANO: Uff! Ora\nche non sto piu'\11male, credo sia\nl'ora.",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "CAPITANO:\nOoargh... Che\11schifo... Urrp!\nMal di mare...\11{PLAYER} ha\nstrofinato la\11schiena del\nCAPITANO!\11Strofina-strofina...\nStrofina-strofina...",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "Come sconfiggere\nil mal di mare...\11Il CAPITANO sta\nleggendo questo!",
  ["_SSAnneCaptainsRoomTrashText"] = "Che schifo! Non\navrei dovuto\11guardare!",
  ["_SSAnneKitchenCook1Text"] = "Tu, mon petit!\nSiamo occupati\11qui! Fuori dai\npiedi!",
  ["_Route6KitchenCook2Text"] = "Ho visto una\nstrana palla nella\11spazzatura.",
  ["_SSAnneKitchenCook3Text"] = "Sono cosi'\noccupato che ho le\11vertigini!",
  ["_SSAnneKitchenCook4Text"] = "Um-de-hum-de ho...\nSbuccio patate\11tutti i giorni!\nUm-hum...",
  ["_SSAnneKitchenCook5Text"] = "Hai saputo di\nSNORLAX? Fa solo\11una vita a\nmangiare e\11dormire!",
  ["_SSAnneKitchenCook6Text"] = "Piagnuc...\nSniff... Devo solo\11pelare cipolle...\nPiagnuc...",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "Ehm-ehm! Certo che\nsono lo CHEF! La\11portata principale\né",
  ["_SSTicketNoRoomText"] = "Hai troppa roba,\namico!",
  ["_SSTicketReceivedText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",







  ["_SafariZoneAngryText"] = "{RAM:wEnemyMonNick}\nselvatico é\11arrabbiato!",
  ["_SafariZoneCenterRestHouseGirlText"] = "SARA: Dove sara'\nandato il mio\11ragazzo ERIK?",
  ["_SafariZoneCenterRestHouseScientistText"] = "Sto catturando\nPOKéMON da portare\11a casa come\nregali!",
  ["_SafariZoneCenterRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneCenterTrainerTipsSignText"] = "CONSIGLI UTILI\nPremi il Pulsante\11START per vedere\nil tempo residuo!",
  ["_SafariZoneEastRestHouseRockerText"] = "Ho catturato un\nCHANSEY! Ne é\11valsa la pena!",
  ["_SafariZoneEastRestHouseScientistText"] = "Quanti ne hai\ncatturati? Sono\11distrutto dal\nlavoro!",
  ["_SafariZoneEastRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneEastRestHouseSilphWorkerMText"] = "Uff! Sono stanco\ndi tutto questo\11svago!",
  ["_SafariZoneEastSignText"] = "AREA CENTRALE\nNORD: AREA 2",
  ["_SafariZoneEastTrainerTipsText"] = "CONSIGLI UTILI Il\ntempo rimasto\11diminuisce solo\nmentre cammini!",
  ["_SafariZoneEatingText"] = "{RAM:wEnemyMonNick}\nselvatico sta\11mangiando!",
  ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "Ti chiameremo con\nl'altoparlante se\11finisce il tempo o\nle SAFARI BALL!",
  ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "é stato un buon\nbottino? Torna a\11trovarci!",
  ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "Buona fortuna!",
  ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "Te ne vai gia'?",
  ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "Ops! Non hai\nabbastanza soldi!",
  ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "OK! Torna a\ntrovarci presto!",
  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Restituisci le\nSAFARI BALL che ti\11sono rimaste.",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "Benvenuto nella\nZONA SAFARI!",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "Costano 500\nPokémon-dollari!\11Qui usiamo solo\nSAFARI BALL.\11{PLAYER} riceve 30\nSAFARI BALL!",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "Per soli 500\nPokémon-dollari\11puoi catturare\ntutti i POKéMON\11che vuoi! Vuoi\npartecipare alla\11caccia?",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "Ciao! é la tua\nprima volta qui?",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "La ZONA SAFARI ha\n4 zone diverse. In\11ogni zona ci sono\nPOKéMON\11differenti. Usate\nle SAFARI BALL per\11catturarli! Se\nfiniscono tempo o\11SAFARI BALL, la\npartita é finita!\11Prima di partire,\napri un POKéMON\11BOX vuoto per fare\nspazio ai nuovi!",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "Spiacente, tu sei\nun cliente\11abituale!",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "Il mio EEVEE si é\nevoluto in\11FLAREON! Ma quello\ndi un amico é\11diventato un\nVAPOREON! Chissa'\11perché?",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Vai nella parte\npiu' profonda\11della ZONA SAFARI.\nVinci rai un\11premio!",
  ["_SafariZoneNorthRestHouseScientistText"] = "Puoi tenere ogni\noggetto trovato\11per terra qui. Ma\nfinira' il tempo\11se provi a prender\nli tutti insieme!",
  ["_SafariZoneNorthRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneNorthSignText"] = "AREA 2",
  ["_SafariZoneNorthTrainerTips1Text"] = "CONSIGLI UTILI La\nCASA SEGRETA é\11ancora piu'\navanti!",
  ["_SafariZoneNorthTrainerTips2Text"] = "CONSIGLI UTILI I\nPOKéMON si\11nascondono\nnell'erba! Cammina\11a zig-zag\nnell'erba alta per\11farli uscire.",
  ["_SafariZoneNorthTrainerTips3Text"] = "CONSIGLI UTILI\nVinci una MN\11gratis trovando la\nCASA SEGRETA!",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "La MN03 é SURF! I\nPOKéMON potranno\11traghettarti\nsull'acqua! Questa\11MN non si rompe!\nPuoi usarla tutte\11le volte che vuoi!\nSei fortunatissimo\11a vincere questo\nfavoloso premio!",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "Non hai abbastanza\nspazio per questo\11favoloso premio!",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "Ah! Finalmente!\nSei il primo ad\11arrivare alla CASA\nSEGRETA! Temevo\11che nessuno circa\navrebbe vinto il\11nostro premio.\nCongratulazioni!\11Hai vinto!",
  ["_SafariZoneWestFindWardensTeethSignText"] = "AVVISO RICHIESTA\nCercate i DENTI\11D'ORO smarriti dal\nGUARDIANO SAFARI.\11Devono essere da\nqueste parti.\11Ricompensa\nofferta!\11Contattare:\nGUARDIA",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "Usare l'ESCA rende\ni POKéMON piu'\11facili da\npigliare.",
  ["_SafariZoneWestRestHouseScientistText"] = "Lanciare SASSI ai\nPOKéMON li fa\11scappare, ma sono\npiu' facili da\11catturare.",
  ["_SafariZoneWestRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "Ho camminato\nmolto, ma non ho\11visto POKéMON che\nvolevo.",
  ["_SafariZoneWestSignText"] = "AREA 3 EST: AREA\nCENTRALE",
  ["_SafariZoneWestTrainerTipsText"] = "CONSIGLI UTILI\nCampagna esplo\11razione zone! Alla\nricerca della CASA\11SEGRETA!",
  ["_SaffronCityFightingDojoSignText"] = "DOJO LOTTA",
  ["_SaffronCityGentlemanText"] = "Sono volato qui\ncol mio PIDGEOT\11leggendo della\nSILPH. é gia'\11finita? Mi sono\nperso tutta la\11cronaca.",
  ["_SaffronCityGymSignText"] = "PALESTRA POKéMON\ndi ZAFFERANOPOLI\11CAPOPALESTRA:\nSABRINA Maestra\11dei POKéMON psico!",
  ["_SaffronCityMrPsychicsHouseSignText"] = "CASA DEL SIG. PSI",
  ["_SaffronCityPidgeotText"] = "PIDGEOT: Bi bibii!",
  ["_SaffronCityPokecenterGuyText1"] = "Sarebbe bello se i\nSUPERQUATTRO\11venissero a dare\nuna lezione al\11TEAM ROCKET!",
  ["_SaffronCityPokecenterGuyText2"] = "Il TEAM ROCKET é\nscomparso!\11Possiamo uscire in\nsicurezza!\11Fantastico!",
  ["_SaffronCityRockerText"] = "Ho visto il CAPO\ndel ROCKET\11scappare\ndall'edificio\11SILPH.",
  ["_SaffronCityRocket1Text"] = "Che vuoi?\nSparisci!",
  ["_SaffronCityRocket2Text"] = "Il CAPO ha detto\nche prendera'\11questa citta'!",
  ["_SaffronCityRocket3Text"] = "Togliti di mezzo!",
  ["_SaffronCityRocket4Text"] = "ZAFFERANOPOLI\nappartiene al TEAM\11ROCKET!",
  ["_SaffronCityRocket5Text"] = "Essere malvagi mi\nfa sentire vivo!",
  ["_SaffronCityRocket6Text"] = "Ahi! Guarda dove\nmetti i piedi!",
  ["_SaffronCityRocket7Text"] = "Con la SILPH sotto\ncontrollo, possia\11mo sfruttare i\nPOKéMON del mondo!",
  ["_SaffronCityRocket8Text"] = "Sono una guardia.\nNon lascio pas\11sare bambini",
  ["_SaffronCityRocket9Text"] = "... Ronf... Ha! Si\nsta facendo un\11pisolino!",
  ["_SaffronCityScientistText"] = "Hai battuto il\nTEAM ROCKET da\11solo? Incredibile!",
  ["_SaffronCitySignText"] = "ZAFFERANOPOLI\nSplendente e d'oro\11Terra del\nCommercio",
  ["_SaffronCitySilphCoLatestProductSignText"] = "L'ultimo prodotto\ndella SILPH!\11Uscita da\ndefinire...",
  ["_SaffronCitySilphCoSignText"] = "SOCIETA' SILPH\nEDIFICIO UFFICI",
  ["_SaffronCitySilphWorkerFText"] = "La gente dovrebbe\ntornare a frotte a\11ZAFFERANOPOLI ora.",
  ["_SaffronCitySilphWorkerMText"] = "Si'! Il TEAM\nROCKET é andato\11via! é sicuro\nuscire di nuovo!",
  ["_SaffronCityTrainerTips1Text"] = "CONSIGLI UTILI\nCURA TOTALE cura\11tutti i problemi\ncome sonno e\11ustioni. Costa un\npo' di piu', ma é\11molto piu' comodo.",
  ["_SaffronCityTrainerTips2Text"] = "CONSIGLI UTILI Le\nnuove SUPER BALL\11offrono una\nmiglior cattura.\11Provale su quei\nPOKéMON difficili\11da catturare.",
  ["_SaffronGateGuardGeeImThirstyText"] = "Sono di guardia.\nUffa, ho una sete!\11Aspetta un attimo,\nla strada é\11chiusa.",
  ["_SaffronGateGuardImParchedText"] = "Ehi, ragazzo! Ho\nla gola secca! ...\11Eh? Posso bere\nquesta bibita? Oh,\11grazie!",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "Ciao, grazie per\nle bevande\11fresche!",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "... Glub glub...\n... Gulp... Se\11vuoi andare a\nZAFFERANOPOLI...\11... Puoi passare.\nLo condividero'\11con le altre\nguardie!",
  ["_SaffronGymChanneler1AfterBattleText"] = "In una\nlotta tra uguali,\11vince chi ha la\nvolonta' piu'\11forte! Se vuoi\nbattere SABRINA,\11pensa solo a\nvincere!",
  ["_SaffronGymChanneler1BattleText"] = "SABRINA é\npiu' giovane di\11me, ma la\nrispetto!",
  ["_SaffronGymChanneler1EndBattleText"] = "Non basta!",
  ["_SaffronGymChanneler2AfterBattleText"] = "Devo\ninsegnare tecniche\11migliori ai miei\nPOKéMON!",
  ["_SaffronGymChanneler2BattleText"] = "I POKéMON\nassomi gliono ai\11propri allenatori.\nI tuoi POKéMON\11devono essere\ntosti!",
  ["_SaffronGymChanneler2EndBattleText"] = "Lo sapevo!",
  ["_SaffronGymChanneler3AfterBattleText"] = "Sapevo che\nsarebbe successo\11tutto questo.",
  ["_SaffronGymChanneler3BattleText"] = "Io e te, i\nnostri POKéMON\11lotteranno!",
  ["_SaffronGymChanneler3EndBattleText"] = "Ho perso\nal termine!",
  ["_SaffronGymGuideBeatSabrinaText"] = "Poteri psichici,\neh? Se li avessi\11io, farei un sacco\ndi soldi alle\11slot!",
  ["_SaffronGymGuideChampInMakingText"] = "Ehila'! Campione!\nI POKéMON di\11SABRINA usano la\nmente anziché la\11forza! I POKéMON\nLotta sono deboli\11contro i POKéMON\npsico! Vengono\11stesi prima di\npoter sferrare un\11pugno!",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "La MEDAGLIA PALUDE\nubbidisce ai\11POKéMON fino al Lv\n70! I POKéMON piu'\11forti diventano\nselvaggi e ti\11ignorano! Non far\ncrescere troppo i\11tuoi POKéMON!\nAspetta, prendi\11questa MT!",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "Ognuno ha poteri\npsichici! La gente\11non se ne rende\nconto!",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "Sono scioccata! Ma\nuna sconfitta é\11una sconfitta.\nAmmetto di non\11aver studiato\nabbastanza! Hai\11vinto la MEDAGLIA\nPALUDE!",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER} riceve la\nMT46!",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "Il tuo zaino é\ncormo di roba!",
  ["_SaffronGymSabrinaText"] = "Avevo previsto la\ntua venuta! Ho\11poteri psichici da\nquando ero\11piccola. Ho\niniziato piegando\11i cucchiai con la\nmente. Odio\11lottare, ma se lo\ndesideri, ti\11mostrero' i\npoteri!",
  ["_SaffronGymYoungster1AfterBattleText"] = "I POKéMON\npsico temono solo\11spettri e insetti!",
  ["_SaffronGymYoungster1BattleText"] = "Il nostro\npotere invisibile\11ti spaventa?",
  ["_SaffronGymYoungster1EndBattleText"] = "Non l'avevo\nprevisto!",
  ["_SaffronGymYoungster2AfterBattleText"] = "SABRINA ha\nappena steso il\11MAESTRO DI KARATE\nqui accanto!",
  ["_SaffronGymYoungster2BattleText"] = "Sai che la\nforza nuda e cruda\11non basta!",
  ["_SaffronGymYoungster2EndBattleText"] = "Non ci\nposso credere!",
  ["_SaffronGymYoungster3AfterBattleText"] = "C'erano 2\npalestre POKéMON a\11ZAFFERANOPOLI. Il\nDOJO qui vicino ha\11perso lo status\nquando li abbiamo\11stroncati!",
  ["_SaffronGymYoungster3BattleText"] = "SABRINA é\ngiovane, ma é\11anche la nostra\nCAPO! Non\11arriverai a lei\nfacilmente!",
  ["_SaffronGymYoungster3EndBattleText"] = "Ho perso la\nconcentrazione!",
  ["_SaffronGymYoungster4AfterBattleText"] = "Esatto! Ho\nusato la telepatia\11per leggerti la\nmente!",
  ["_SaffronGymYoungster4BattleText"] = "La palestra\ndi ZAFFERANOPOLI é\11famosa per i suoi\npsico! Vuoi vedere\11SABRINA! Lo so!",
  ["_SaffronGymYoungster4EndBattleText"] = "Arrrgh!",
  ["_SaffronMartCooltrainerFText"] = "IL REVITALIZ. é\ncostoso, ma\11rimette in sesto i\nPOKéMON!",
  ["_SaffronMartSuperNerdText"] = "Il REPELL MAX dura\npiu' del SUPER REP\11per tenere lontani\ni POKéMON piu'\11deboli!",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "Grazie per aver\nscritto. Spero di\11vederti presto!\nEhi! Non guardare\11la mia lettera!",
  ["_SaffronPidgeyHousePaperText"] = "Mi hanno regalato\nuna PROTEINA.\11Serve per aumen\ntare la potenza\11delle mosse!",
  ["_SaffronPidgeyHousePidgeyText"] = "PIDGEY: Kurukkoo!",
  ["_SaffronPidgeyHouseYoungsterText"] = "A mia figlia piace\nmoltissimo imitare\11la gente! La sua\npassione sono le\11BAMB. POKé!",
  ["_SaffronPokecenterBeautyText"] = "I tassi di cresci\nta dei POKéMON\11variano da specie\na specie.",
  ["_SaffronPokecenterGentlemanText"] = "La SILPH é molto\nfamosa. Ecco\11perché ha attirato\nil TEAM ROCKET!",
  ["_SandshrewDexEntry"] = "Si scava una tana\nprofonda\nsottoterra in zone\12aride lontano\ndall'acqua. Emerge\nsolo per cercare\12cibo.",
  ["_SandslashDexEntry"] = "Si appallottola in\nuna sfera spinosa\nse minacciato.\12Puo' rotolare da\nappallottolato per\nattaccare o\12fuggire.",
  ["_SaveOptionText"] = "L'opzione SALVA é\nnel MENU.",
  ["_SavingEnergyText"] = "{USER} sta\naccumulando\11energia!",
  ["_ScaredText"] = "{RAM:wBattleMonNick} ha\ntroppa paura per\11muoversi!",
  ["_ScytherDexEntry"] = "Con agilita' e\nvelocita' da\nninja, puo' creare\12l'illusione che ce\nne sia piu' di\nuno.",
  ["_SeadraDexEntry"] = "Capace di nuotare\nall'indietro\nbattendo\12rapidamente le\npinne pettorali\nsimili a ali e la\12robusta coda.",
  ["_SeafoamIslandsB4FArticunoBattleText"] = "Gyaoo!",
  ["_SeafoamIslandsB4FBouldersSignText"] = "I massi potreb\nbero deviare il\11flusso d'acqua!",
  ["_SeafoamIslandsB4FDangerSignText"] = "PERICOLO Corrente\nforte!",
  ["_SeakingDexEntry"] = "Nella stagione\ndella deposizione,\nsi possono vedere\12mentre risalgono\npotentemente fiumi\ne torrenti.",
  ["_SeelDexEntry"] = "Il corno sporgente\nsulla testa é\nmolto duro. Viene\12usato per sfondare\nil ghiacchio\nspesso.",
  ["_SentToBoxText"] = "Non c'é piu' posto\nper i POKéMON!\11{RAM:wBoxMonNicks} é stato\nspedito al BOX\11POKéMON {RAM:wStringBuffer}\nsul PC!",
  ["_ShallWeHealYourPokemonText"] = "Vuoi curare i tuoi\nPOKéMON?",
  ["_ShellderDexEntry"] = "Il suo guscio duro\nrespinge ogni tipo\ndi attacco. é\12vulnerabile solo\nquando il guscio é\naperto.",
  ["_ShroudedInMistText"] = "{USER} é avvolto\nnella nebbia!",
  ["_SilphCo10FGiovanniILostAgainText"] = "Arrgh!! Ho perso\ndi nuovo!?",
  ["_SilphCo10FPorygonText"] = "Il monitor ha un\nPOKéMON sopra!",
  ["_SilphCo10FRocketAfterBattleText"] = "Bel\ntentativo, ma la\11sala riunio ni é\nun piano su!",
  ["_SilphCo10FRocketBattleText"] = "Benvenuto\nal 10° piano! Che\11piacere averti qui\ncon me!",
  ["_SilphCo10FRocketEndBattleText"] = "Sono\nstupito!",
  ["_SilphCo10FScientistAfterBattleText"] = "Sei\nsoddisfatto di\11avermi battuto?\nAllora torna a\11casa!",
  ["_SilphCo10FScientistBattleText"] = "Basta\ncon questi giochi\11sciocchi!",
  ["_SilphCo10FScientistEndBattleText"] = "Nessun\ncontinua rimasto!",
  ["_SilphCo10FSilphWorkerFImScaredText"] = "Waaaaa! Ho paura!",
  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "Ti prego, sta'\nzitto sul mio\11pianto!",
  ["_SilphCo11FBeautyText"] = "SEGRETARIA: Grazie\nper averci\11liberato tutti!\nAmmiriamo molto il\11tuo coraggio.",
  ["_SilphCo11FGiovanniText"] = "Ah {PLAYER}! Ci\nrincontriamo! Il\11PRESIDENTE ed io\nstiamo parlando di\11affari. Non\nficcare il naso\11nelle cose dei\ngrandi... O\11proverai il\ndolore!",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "Accidenti! Hai\nrovinato i nostri\11piani SILPH! Ma il\nTEAM ROCKET non\11cadra' mai!\n{PLAYER}! Ricorda\11che i POKéMON sono\ndel TEAM ROCKET!\11Devo andare, ma\ntornero'!",
  ["_SilphCo11FRocket1AfterBattleText"] = "Vuoi\nvedere il mio\11CAPO, eh?",
  ["_SilphCo11FRocket1BattleText"] = "Fermati\nli'! Non muoverti!",
  ["_SilphCo11FRocket1EndBattleText"] = "Non... Ti\nprego!",
  ["_SilphCo11FRocket2AfterBattleText"] = "Attento,\nal mio CAPO\11piacciono i\nPOKéMON tosti!",
  ["_SilphCo11FRocket2BattleText"] = "Alt! Hai\nun appun tamento\11col CAPO?",
  ["_SilphCo11FRocket2EndBattleText"] = "Gaah!\nDistrutto!",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PRESIDENTE: Non\npuoi comprarla da\11nessuna parte! é\nla nostra MASTER\11BALL segreta!\nCatturera' qual\11siasi POKéMON\nsenza fallire!\11Pero' tieni il\nsegreto sull'uso.",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "Non hai posto per\nquesto.",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SilphCo11FSilphPresidentText"] = "PRESIDENTE: Grazie\nper aver salvato\11la SILPH! Non\ndimentichero' che\11ci hai salvati nel\npericolo! Devo\11ringraziarti in\nqualche modo!\11Essendo ricco,\nposso darti tutto!\11Ecco, forse questo\nandra' bene!",
  ["_SilphCo1FLinkReceptionistText"] = "Benvenuto! Il\nPRESIDENTE é\11all'11° piano\nnella sala\11riunioni!",
  ["_SilphCo2FRocket1AfterBattleText"] = "Le\npiastrelle a forma\11di rombo sono\nteletrasporti!\11Sono hi-tech!",
  ["_SilphCo2FRocket1BattleText"] = "I bambini\nnon possono\11entrare!",
  ["_SilphCo2FRocket1EndBattleText"] = "Duro!",
  ["_SilphCo2FRocket2AfterBattleText"] = "La SILPH\nsi unira' al TEAM\11ROCKET!",
  ["_SilphCo2FRocket2BattleText"] = "Ehi tu!\nChe fai qui?",
  ["_SilphCo2FRocket2EndBattleText"] = "Ho\ntoppato!",
  ["_SilphCo2FScientist1AfterBattleText"] = "Lavoro\nper SILPH e TEAM\11ROCKET!",
  ["_SilphCo2FScientist1BattleText"] = "Aiuto!\nLavoro alla SILPH.",
  ["_SilphCo2FScientist1EndBattleText"] = "Come\nfacevi a sapere\11che ero ROCKET?",
  ["_SilphCo2FScientist2AfterBattleText"] = "Sai\nrisolvere il\11labirinto qui?",
  ["_SilphCo2FScientist2BattleText"] = "Zona\nvietata! Vai a\11casa!",
  ["_SilphCo2FScientist2EndBattleText"] = "Sei\nbravo.",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "La MT36 é\nAUTODISTRUZIONE! é\11forte, ma il\nPOKéMON va K.O.!\11Fai attenzione.",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "Non hai abbastanza\nspazio per questo.",
  ["_SilphCo3FRocketAfterBattleText"] = "Un\nindizio? Puoi\11aprire le porte\ncon una SCHEDA!",
  ["_SilphCo3FRocketBattleText"] = "Smetti di\ndarci fastidio,\11moccioso!",
  ["_SilphCo3FRocketEndBattleText"] = "Mi\narrendo!",
  ["_SilphCo3FScientistAfterBattleText"] = "Uhm...\nIl TEAM ROCKET ha\11detto che mi\navrebbe fatto stu\11diare i POKéMON!",
  ["_SilphCo3FScientistBattleText"] = "Sostengo\nil TEAM ROCKET\11piu' della stessa\nSILPH!",
  ["_SilphCo3FScientistEndBattleText"] = "Mi hai\nproprio preso!",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Lavoro alla SILPH.\nChe devo fare?",
  ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "{PLAYER}! Tu e i\ntuoi POKéMON ci\11avete salvati!",
  ["_SilphCo4FRocket1AfterBattleText"] = "Fwahahaha!\nIl mio CAPO punta\11questo posto!",
  ["_SilphCo4FRocket1BattleText"] = "Il TEAM\nROCKET ha preso il\11comando della\nSILPH S.P.A.!",
  ["_SilphCo4FRocket1EndBattleText"] = "Arrgh!",
  ["_SilphCo4FRocket2AfterBattleText"] = "Meglio\navvisare il CAPO\11all'11° piano!",
  ["_SilphCo4FRocket2BattleText"] = "Intruso\navvistato!",
  ["_SilphCo4FRocket2EndBattleText"] = "Tu chi\nsei?",
  ["_SilphCo4FScientistAfterBattleText"] = "Le\nporte sono chiuse!\11Una SCHEDA le\napre!",
  ["_SilphCo4FScientistBattleText"] = "I miei\nPOKéMON sono i\11miei leali\nsoldati!",
  ["_SilphCo4FScientistEndBattleText"] = "Accidenti!\nChe POKéMON\11deboli!",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "Sssh! Non vedi che\nmi nascondo?",
  ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "Eh? Il TEAM ROCKET\né sparito?",
  ["_SilphCo5FPokemonReport1Text"] = "é un RAPPORTO! IL\nLABORATORIO ha\11creato PORYGON, il\nprimo POKéMON\11virtuale.",
  ["_SilphCo5FPokemonReport2Text"] = "é un RAPPORTO!\nOltre 160 mosse\11POKéMON sono state\nconfermate.",
  ["_SilphCo5FPokemonReport3Text"] = "é un RAPPORTO! 4\nPOKéMON si\11evolvono solo con\nlo scambio tramite\11cavo Link.",
  ["_SilphCo5FRockerAfterBattleText"] = "Sei solo\nal 5° piano. La\11strada per il CAPO\né lunga!",
  ["_SilphCo5FRockerBattleText"] = "Cosa? Non\ndovrebbero esserci\11bambini!",
  ["_SilphCo5FRockerEndBattleText"] = "Oh cielo!",
  ["_SilphCo5FRocket1AfterBattleText"] = "Non é\nsaggio attaccare\11briga col TEAM\nROCKET!",
  ["_SilphCo5FRocket1BattleText"] = "Ho sentito\nche un bimbo\11gironzola.",
  ["_SilphCo5FRocket1EndBattleText"] = "Boom!",
  ["_SilphCo5FRocket2AfterBattleText"] = "A\nproposito. KOFFING\11si evolve in\nWEEZING!",
  ["_SilphCo5FRocket2BattleText"] = "Rispetta\nun po' il TEAM\11ROCKET!",
  ["_SilphCo5FRocket2EndBattleText"] = "Cof...\nCof...",
  ["_SilphCo5FScientistAfterBattleText"] = "Lavoravamo\nalla super POKé\11BALL che catturava\nqualsiasi cosa!",
  ["_SilphCo5FScientistBattleText"] = "Studiamo\nle POKé BALL su\11questo piano!",
  ["_SilphCo5FScientistEndBattleText"] = "Accidenti!\nDannazione!",
  ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "Il TEAM ROCKET é\nin subbuglio per\11un intruso. Sei\ntu?",
  ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "Il TEAM ROCKET é\nfuggito! Sei il\11nostro eroe!",
  ["_SilphCo6FRocket1AfterBattleText"] = "Non\nimporta! I miei\11fratelli mi\nvendicheranno!",
  ["_SilphCo6FRocket1BattleText"] = "Sono uno\ndei 4 FRATELLI\11ROCKET!",
  ["_SilphCo6FRocket1EndBattleText"] = "Fiamma\nspenta!",
  ["_SilphCo6FRocket2AfterBattleText"] = "Chi sta\ncon la giustizia,\11tradisce il male!",
  ["_SilphCo6FRocket2BattleText"] = "Osi\ntradire il TEAM\11ROCKET?",
  ["_SilphCo6FRocket2EndBattleText"] = "Tradit\ntore!",
  ["_SilphCo6FScientistAfterBattleText"] = "FILIALE\nESTERNA? é in una\11zona davvero\nremota!",
  ["_SilphCo6FScientistBattleText"] = "Quel\nmarrano del\11PRESIDENTE! Non\ndoveva man darmi\11in questa filiale\nsperduta!",
  ["_SilphCo6FScientistEndBattleText"] = "Accidenti!",
  ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "Mi dispiace tanto\nper lui, lo devo\11sposare!",
  ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "Guardalo! é un\nvero codardo!",
  ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "Il TEAM ROCKET\nvuole conquistare\11il mondo coi\nPOKéMON!",
  ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "Il TEAM ROCKET é\nfuggito per colpa\11tua!",
  ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "Bene, é ora di\ntornare al lavoro!",
  ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "I ROCKET sono\nvenuti a occupare\11l'edificio!",
  ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "Avranno preso di\nmira la SILPH per\11i nostri prodotti.",
  ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "Vieni a lavorare\nalla SILPH quando\11sarai grande!",
  ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "Mio Dio, aiuto!\nAiutami ti prego!",
  ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "Ci siamo\nfidanzati! Eheheh!",
  ["_SilphCo7FRivalDefeatedText"] = "Oh ho! Sei pronto\nper il CAPO\11ROCKET!",
  ["_SilphCo7FRivalGoodLuckToYouText"] = "Beh, {PLAYER}! Vado\navanti e sopra!\11Guardando il mio\nPOKéDEX capisco\11chi é forte e come\nsi evolvono! Vado\11alla LEGA POKéMON\na cacciare i\11SUPERQUATTRO!\nDiventero' il piu'\11forte allenatore!\n{PLAYER}, buona\11fortuna! Ci si\nvede!",
  ["_SilphCo7FRivalText"] = "{RIVAL}: Cosa ti\nha trattenuto?",
  ["_SilphCo7FRivalVictoryText"] = "{RIVAL}: Come\ndire? Non sei\11ancora pronto per\ngiocare con i\11grandi!",
  ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}: Ahahah!\nSapevo che saresti\11venuto! Il TEAM\nROCKET ti ha\11rallentato! Ti ho\nvisto a\11ZAFFERANOPOLI e ho\nvoluto vedere se\11sei migliorato!",
  ["_SilphCo7FRocket1AfterBattleText"] = "Non\ntroverai il mio\11CAPO girando a\ncaso!",
  ["_SilphCo7FRocket1BattleText"] = "Oh ho!\nSento puzza di\11topo!",
  ["_SilphCo7FRocket1EndBattleText"] = "Luce\nspenta!",
  ["_SilphCo7FRocket2AfterBattleText"] = "Non\nimporta. I miei\11fratelli\nrenderanno il\11favore!",
  ["_SilphCo7FRocket2BattleText"] = "Sono uno\ndei 4 FRATELLI\11ROCKET!",
  ["_SilphCo7FRocket2EndBattleText"] = "Aack!\nFratelli, ho\11perso!",
  ["_SilphCo7FRocket3AfterBattleText"] = "Vattene a\ncasa prima che il\11CAPO si arrabbi!",
  ["_SilphCo7FRocket3BattleText"] = "Un bimbo\nintruso? Sarai tu!",
  ["_SilphCo7FRocket3EndBattleText"] = "Va bene!\nHo perso!",
  ["_SilphCo7FScientistAfterBattleText"] = "Nonostante\nl'eta', sei un\11abile allenatore!",
  ["_SilphCo7FScientistBattleText"] = "Eheheh!\nMi hai scambiato\11per un operaio?",
  ["_SilphCo7FScientistEndBattleText"] = "Ho\nchiuso!",
  ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "Oh! Ciao! Non sei\nun ROCKET! Sei\11venuto a salvarci?\nGrazie! Voglio\11darti un POKéMON\nper questo.",
  ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "Il CAPO del ROCKET\né nella sala! Il\11PRESIDENTE sta\nbene?",
  ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "é un LAPRAS, molto\nintelligente. Era\11nel laboratorio ma\nstara' meglio con\11te! Penso che\nsarai un buon\11allenatore! é un\nottimo nuo tore,\11ti dara' un\npassaggio!",
  ["_SilphCo7FSilphWorkerM1SavedText"] = "Salvo alla fine!\nGrazie!",
  ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "Il TEAM ROCKET\nvoleva la MASTER\11BALL per catturare\nqualsiasi POKéMON!",
  ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "Abbiamo chiuso il\nprogetto MASTER\11BALL per colpa del\nTEAM ROCKET.",
  ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "Sarebbe un guaio\nse il TEAM ROCKET\11prendesse la SILPH\no i nostri\11POKéMON!",
  ["_SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText"] = "Wow! Hai messo in\nfuga il TEAM\11ROCKET da solo?",
  ["_SilphCo7FSilphWorkerM4ItsReallyDangerousHereText"] = "Tu! Qui é peri\ncoloso! Sei venuto\11a salvarmi? Non\npuoi!",
  ["_SilphCo7FSilphWorkerM4SafeAtLastText"] = "Al sicuro! Oh\ngrazie!",
  ["_SilphCo8FRocket1AfterBattleText"] = "Se non\ntorni indietro,\11chiamo rinforzi!",
  ["_SilphCo8FRocket1BattleText"] = "Da qui non\npasserai!",
  ["_SilphCo8FRocket1EndBattleText"] = "Manca la\ngrinta!",
  ["_SilphCo8FRocket2AfterBattleText"] = "Lascio\nfare ai miei\11fratelli!",
  ["_SilphCo8FRocket2BattleText"] = "Sono uno\ndei 4 FRATELLI\11ROCKET!",
  ["_SilphCo8FRocket2EndBattleText"] = "Whoo! Oh\nfratelli!",
  ["_SilphCo8FScientistAfterBattleText"] = "Allora,\nche ne pensi del\11labiri nto della\nSILPH?",
  ["_SilphCo8FScientistBattleText"] = "Ci\nstai creando\11problemi!",
  ["_SilphCo8FScientistEndBattleText"] = "Eh? Ho\nperso?",
  ["_SilphCo8FSilphWorkerMSilphIsFinishedText"] = "Chissa' se la\nSILPH é finita...",
  ["_SilphCo8FSilphWorkerMThanksForSavingUsText"] = "Grazie per averci\nsalvati!",
  ["_SilphCo9FRocket1AfterBattleText"] = "Se avessi\niniziato alla tua\11eta'...",
  ["_SilphCo9FRocket1BattleText"] = "I tuoi\nPOKéMON ti\11adorano, ragazzo!",
  ["_SilphCo9FRocket1EndBattleText"] = "Ghaaah!",
  ["_SilphCo9FRocket2AfterBattleText"] = "I miei\nfratelli mi\11vendicheranno!",
  ["_SilphCo9FRocket2BattleText"] = "Sono uno\ndei 4 FRATELLI\11ROCKET!",
  ["_SilphCo9FRocket2EndBattleText"] = "Warg!\nFratelli, ho\11perso!",
  ["_SilphCo9FScientistAfterBattleText"] = "Sfruttare\ni punti deboli\11funziona! Pensa ai\ntipi elementali!",
  ["_SilphCo9FScientistBattleText"] = "I tuoi\nPOKéMON hanno\11debolezze! Le\ncolpiro'!",
  ["_SilphCo9FScientistEndBattleText"] = "Mi hai\ndistrutto!",
  ["_SkyAttackGlowingText"] = "sta brillando!",
  ["_SlowbroDexEntry"] = "Si dice che lo\nSHELLDER attaccato\nalla coda di\12SLOWPOKE si nutra\ndegli avanzi del\nsuo ospite.",
  ["_SlowpokeDexEntry"] = "Incredibilmente\nlento e tonto. Ci\nvogliono 5 secondi\12per sentire dolore\nquando viene\nattaccato.",
  ["_SnorlaxDexEntry"] = "Molto pigro.\nMangia e dorme.\nAumentando la\12stazza, diventa\nsempre piu'\nindolente.",
  ["_SoYouWantPrizeText"] = "Quindi vuoi\n{RAM:wNameBuffer}?",
  ["_SorryNeedMoreCoinsText"] = "Spiacente, ti\nservono piu'\11gettoni.",
  ["_SpearowDexEntry"] = "Mangia insetti\nnell'erba. Deve\nbattere le ali\12corte ad alta\nvelocita' per\nrestare in volo.",
  ["_SquirtleDexEntry"] = "Dopo la nascita,\nla schiena si\ngonfia in un\12guscio. Spruzza\npotente schiuma\ndalla bocca.",
  ["_StarmieDexEntry"] = "Il nucleo centrale\nbrilla dei sette\ncolori\12dell'arcobalene.\nAlcuni lo\nconsiderano una\12gemma preziosa.",
  ["_StartSlotMachineText"] = "Via!",
  ["_StartedSleepingEffect"] = "{USER} é caduto\nnel sonno!",
  ["_StaryuDexEntry"] = "Un POKéMON\nenigmatico che\nrigenera senza\12sforzo qualsiasi\narto perso in\nlotta.",
  ["_StatusChangesEliminatedText"] = "Ogni alterazione\ndi STATO svanisce!",
  ["_SubstituteBrokeText"] = "Il SOSIA di\n{TARGET} é\11distrutto!",
  ["_SubstituteText"] = "Ha creato un\nSOSIA!",
  ["_SubstituteTookDamageText"] = "Il SOSIA ha subito\nil colpo al posto\11di {TARGET}!",
  ["_SuckedHealthText"] = "Ha prosciugato\n{TARGET}!",
  ["_SuperEffectiveText"] = "é superefficace!",
  ["_SurfingGotOnText"] = "{PLAYER} sale su\n{RAM:wNameBuffer}!",
  ["_SurfingNoPlaceToGetOffText"] = "Non c'é un posto\nper scendere!",
  ["_SwitchOnText"] = "Interruttore ON!",
  ["_TM21ExplanationText"] = "La MT21 contiene\nMEGAASSORBIMENTO.\11Drena meta' del\ndanno inflitto per\11curare i tuoi!",
  ["_TM24ExplanationText"] = "La MT24 contiene\nFULMINE! Insegnalo\11a un POKéMON\nelettro!",
  ["_TM34ExplanationText"] = "Una MT contiene\nuna tecnica da\11inseg nare ai\nPOKéMON! Una MT é\11mono uso! Scegli\nbene il POKéMON!\11La MT34 contiene\nPAZIENZA! Il\11POKéMON subisce e\nrestituisce il\11doppio del danno!",
  ["_TM46ExplanationText"] = "La MT46 é PSICO\nONDA! Usa onde\11psichiche per\ninfliggere danni!",
  ["_TangelaDexEntry"] = "Tutto il corpo é\navvolto da lunghe\nliane simili a\12alghe. Le liane\ntremano mentre\ncammina.",
  ["_TaurosDexEntry"] = "Quando punta un\nnemico, carica\nfuriosamente\12frustando il corpo\ncon le sue code\nlunghe.",
  ["_TeachMachineMoveText"] = "Contiene\n{RAM:wStringBuffer}!\11Insegnare\n{RAM:wStringBuffer}?",
  ["_TentacoolDexEntry"] = "Alla deriva nei\nmari bassi. Chi li\npesca viene spesso\12punito con un\nacido urticante.",
  ["_TentacruelDexEntry"] = "I tentacoli sono\nsolitamente corti.\nNella caccia,\12vengono allungati\nper intrappolare e\nimmobilizzare.",
  ["_TextIDErrorText"] = "{NUM:hTextID, 1,\n2} ERRORE.",
  ["_Thanks1Text"] = "Ehi, grazie!",
  ["_Thanks2Text"] = "Grazie!",
  ["_Thanks3Text"] = "Grazie amico!",
