  ["_ThrewAwayItemText"] = "Hai buttato\n{RAM:wNameBuffer}.",
  ["_ThrewBaitText"] = "{PLAYER} lancia\nun'ESCA.",
  ["_ThrewRockText"] = "{PLAYER} lancia un\nSASSO.",
