  ["_ThrowBallAtTrainerMonText2"] = "Non fare il ladro!",
  ["_TimesUpText"] = "ALTOPARLANTE:\nDin-don! Tempo\11scaduto!",
  ["_TooImportantToTossText"] = "é troppo importan\nte per buttarlo!",
  ["_TooWeakSubstituteText"] = "Troppo debole per\nun SOSIA!",
  ["_TookInSunlightText"] = "assorbe luce\nsolare!",
  ["_TossHowManyText"] = "Quanti?",
  ["_TownMapText"] = "La MAPPA CITTA'.",
  ["_TradeCenterOpponentText"] = "!",
