  ["_TradeTakeCareText"] = "Prenditi cura di\n{RAM:wNameBuffer}.",
  ["_TradeTransferredText"] = "{RAM:wNameBuffer} é\ntrasferito.",
  ["_TradeWavesFarewellText"] = "{RAM:wLinkEnemyTrainerName} saluta\ncon la mano mentre",
