  ["_TransformedText"] = "{USER} si é\ntrasformato in\11{RAM:wNameBuffer}!",
  ["_TryingToLearnText"] = "{RAM:wLearnMoveMonName} prova a\nimparare\11{RAM:wStringBuffer}! Ma non\npuo' cono scere\11piu' di 4 mosse!\nCancellare una\11vecchia mossa per\n{RAM:wStringBuffer}?",
  ["_TurnPageText"] = "Giri pagina?",
  ["_TurnedAwayText"] = "{RAM:wBattleMonNick} si é\ntirato indietro!",
  ["_TurnedOnPC1Text"] = "{PLAYER} accende il\nPC.",
  ["_TurnedOnPC2Text"] = "{PLAYER} accende il\nPC.",
  ["_UnaffectedText"] = "{TARGET} non\nsubisce effetti!",
  ["_UndergroundPathRoute6GirlText"] = "La gente perde\nsempre cose in\11quel PASSAGGIO\nSOTTERRANEO.",
  ["_UndergroundPathRoute7CopyUnusedGirlText"] = "Voglio fare acqui\nsti al centro com\11merciale ma... Ci\nsono troppe facce\11losche li'.",
  ["_UndergroundPathRoute7CopyUnusedGoesUnderSaffronText"] = "Il PASSAGGIO passa\nsotto\11ZAFFERANOPOLI e\nporta a\11LAVANDONIA. Per\nCELESTOPOLI, usa\11l'edificio\ndall'altra parte.",
  ["_UndergroundPathRoute7CopyUnusedMiddleAgedManText"] = "Vuoi fare acquisti\na AZZURROPOLI?\11Esci e vai a\novest!",
  ["_UndergroundPathRoute7CopyUnusedTeamRocketHadAHideoutText"] = "Il TEAM ROCKET\naveva un covo a\11AZZURROPOLI?",
  ["_UndergroundPathRoute7MiddleAgedManText"] = "Ho sentito che un\nPOKéMON\11dormiglione é\napparso a\11AZZURROPOLI.",
  ["_UndergroundPathRoute8GirlText"] = "Il centro\ncommerciale di\11AZZURROPOLI é\nfornitissimo!",
  ["_UnleashedEnergyText"] = "{USER} ha\nscatenato energia!",
  ["_UnusedBenchGuyText1"] = "Vorrei tanto cat\nturare POKéMON.",
  ["_UnusedBenchGuyText2"] = "Sono stanco di\ntutto questo\11svago...",
  ["_UnusedBenchGuyText3"] = "Il manager SILPH é\nnascosto nel\11SAFARI.",
  ["_UnveiledGhostText"] = "La SONDA SILPH ha\nsvelato\11l'identita' del\nFANTASMA!",
  ["_UseNextMonText"] = "Usa il prossimo?",
  ["_UsedCutText"] = "{RAM:wNameBuffer} ha\ntranciato con\11TAGLIO!",
  ["_UsedInsteadText"] = "invece,",
  ["_UsedMove1Text"] = "usa",
  ["_UsedMove2Text"] = "usa",
  ["_UsedStrengthText"] = "{RAM:wNameBuffer} usa\nFORZA.",
  ["_VaporeonDexEntry"] = "Vicina all'acqua.\nLa lunga coda ha\nuna pinna spesso\12scambiata per\nquella di una\nsirena.",
  ["_VendingMachineText1"] = "Un distributore!\nEcco il menu!",
  ["_VendingMachineText4"] = "Ops, soldi\ninsufficienti!",
  ["_VendingMachineText5"] = "{RAM:wStringBuffer} é\nuscito!",
  ["_VendingMachineText6"] = "Non c'é piu'\nspazio per roba!",
  ["_VendingMachineText7"] = "Non ho sete!",
  ["_VenomothDexEntry"] = "Le scaglie simili\na polvere sulle\nali indicano i\12vari tipi di\nveleno che\npossiede.",
  ["_VenonatDexEntry"] = "Vive all'ombra di\nalberi alti dove\nmangia insetti. é\12attratto dalla\nluce di notte.",
  ["_VenusaurDexEntry"] = "La pianta fiorisce\nassorbendo energia\nsolare. Si sposta\12continuamente in\ncerca di luce.",
  ["_VermilionCityBeautyText"] = "Siamo attenti\nall'inquinamento!\11GRIMER si multi\nplica nel fango\11tossico!",
  ["_VermilionCityGambler1DidYouSeeText"] = "Hai visto la M/N\nANNA ormeggiata al\11porto?",
  ["_VermilionCityGambler1SSAnneDepartedText"] = "La M/N ANNA é\npartita! Tornera'\11tra circa un anno.",
  ["_VermilionCityGambler2Text"] = "Sto costruendo un\npalazzo qui. Il\11mio POKéMON sta\nspianando il\11suolo.",
  ["_VermilionCityGymSignText"] = "PALESTRA POKéMON\ndi ARANCIOPOLI\11CAPOPALESTRA:\nLT.SURGE Il\11fulmine americano!",
  ["_VermilionCityHarborSignText"] = "PORTO DI\nARANCIOPOLI",
  ["_VermilionCityMachopStompingTheLandFlatText"] = "Un MACHOP sta\nspianando il\11terreno.",
  ["_VermilionCityMachopText"] = "MACHOP: Guoh!\nGogogoh!",
  ["_VermilionCityNoticeSignText"] = "AVVISO! Il\nPERCORSO 12 é\11bloccato da un\nPOKéMON\11addormentato.\nDeviazione per il\11TUNNEL ROCCIOSO\nper LAVANDONIA.\11POLIZIA\nARANCIOPOLI",
  ["_VermilionCityPokemonFanClubSignText"] = "FAN CLUB POKéMON\nBenvenuti fan dei\11POKéMON!",
  ["_VermilionCitySailor1DoYouHaveATicketText"] = "Benvenuto sulla\nM/N ANNA! Scusa,\11hai un biglietto?",
  ["_VermilionCitySailor1FlashedTicketText"] = "{PLAYER} mostra il\nTICKET. Bene!\11Benvenuto sulla\nM/N ANNA!",
  ["_VermilionCitySailor1ShipSetSailText"] = "La nave é salpata.",
  ["_VermilionCitySailor1WelcomeToSSAnneText"] = "Benvenuto sulla\nM/N ANNA!",
  ["_VermilionCitySailor1YouNeedATicketText"] = "{PLAYER} non ha il\nnecessario TICKET.\11Spiacente! Serve\nun biglietto per\11salire a bordo.",
  ["_VermilionCitySailor2Text"] = "La M/N ANNA é una\nlussuosa nave da\11crociera.\nVisitiamo\11ARANCIOPOLI una\nvolta l'anno.",
  ["_VermilionCitySignText"] = "ARANCIOPOLI Porto\ndei tramonti\11squisiti",
  ["_VermilionGymGentlemanAfterBattleText"] = "La\nporta non si apre?\11LT.SURGE é sempre\nstato prudente!",
  ["_VermilionGymGentlemanBattleText"] = "Ero\nnell'esercito, e\11LT.SURGE era il\nmio sergente!",
  ["_VermilionGymGentlemanEndBattleText"] = "Basta!\nSei bravissimo!",
  ["_VermilionGymGymGuideBeatLTSurgeText"] = "Uff! Quella lotta\nera elettrizzante!",
  ["_VermilionGymGymGuideChampInMakingText"] = "Ehila'! Campione!\nLT.SURGE ha un\11soprannome: il\nFulmine Americano!\11é un esperto di\nPOKéMON elettro! I\11volatili e l'acqua\nrischiano molto!\11Attento anche alla\nparalisi! LT.SURGE\11é molto cauto!\nDovrai violare un\11codice per\narrivargli!",
  ["_VermilionGymLTSurgePostBattleAdviceText"] = "Un piccolo consi\nglio, ragazzo!\11L'elettricita' é\npotente! Ma é\11inutile con i\nPOKéMON terra!",
  ["_VermilionGymLTSurgePreBattleText"] = "Ehi,\nragazzo! Che fai\11qui? Non durerai\nmolto in\11combattimento! Te\nlo assicuro! I\11POKéMON elettro mi\nhanno salvato\11durante la guerra!\nHanno fulminato i\11miei nemici! Faro'\nlo stesso con te!",
  ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "Urca! Sei davvero\nin gamba, ragazzo!\11Prendi la MEDAGLIA\nTUONO!",
  ["_VermilionGymLTSurgeTM24NoRoomText"] = "Ragazzo, fai\nspazio nel tuo\11zaino!",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "La MEDAGLIA TUONO\naccende la\11VELOCITA' del tuo\nPOKéMON! Ti\11permette anche di\nusare FLASH! Sei\11speciale! Prendi\nquesto!",
  ["_VermilionGymSailorAfterBattleText"] = "LT.SURGE\nha messo due\11serrature! Un\nindizio! La\11seconda é sem pre\nvicina alla prima\11aperta!",
  ["_VermilionGymSailorBattleText"] = "Questo\nnon é un posto per\11bambini!",
  ["_VermilionGymSailorEndBattleText"] = "Wow! Che\nsorpresa!",
  ["_VermilionGymSuperNerdAfterBattleText"] = "OK,\nparlo! LT.SURGE ha\11nascosto gli\ninterruttori\11dentro qualcosa!",
  ["_VermilionGymSuperNerdBattleText"] = "Sono un\npeso leggero, ma\11me la cavo con\nl'elettricita'",
  ["_VermilionGymSuperNerdEndBattleText"] = "Folgorato!",
  ["_VermilionGymTrashFailTest"] = "No! C'é solo\nspazzatura. Ehi!\11Le serrature\nelettriche sono\11state azzerate!",
  ["_VermilionGymTrashSuccessText1"] = "Ehi! C'é un\ninterruttore sotto\11la spazzatura!\nAttivalo! La 1ª\11serratura si é\naperta!",
  ["_VermilionGymTrashSuccessText2"] = "Ehi! C'é un altro\ninterruttore sotto\11la spazzatura!\nAttivalo!",
  ["_VermilionGymTrashSuccessText3"] = "La 2ª serratura si\né aperta! La porta\11motoriz zata si\napre!",
  ["_VermilionGymTrashText"] = "No, c'é solo\nspazzatura qui.",
  ["_VermilionMartCooltrainerFText"] = "I POKéMON possono\nessere buoni o\11cattivi a seconda\ndell'allenatore.",
  ["_VermilionMartCooltrainerMText"] = "Ci sono persone\ncattive che usano\11i POKéMON per\ndelitti. Il TEAM\11ROCKET tratta\nPOKéMON rari e\11abbandona quelli\nche non ritiene\11utili.",
  ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "Sono il GURU\nPESCATORE! Adoro\11pescare! Ti piace\npescare?",
  ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "La pesca é uno\nstile di vita! Dai\11mari ai fiumi,\nesci e prendi\11quello grosso!",
  ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "Ciao, {PLAYER}!\nAboccano i pesci?",
  ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "Oh no! Non hai\nspazio per il mio\11dono!",
  ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "Ottimo! Mi piace\nil tuo stile!\11Prendi questo,\ngiovane! {PLAYER}\11riceve un\n{RAM:wStringBuffer}!",
  ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "Oh... Che delu\nsione...",
  ["_VermilionPidgeyHouseLetterText"] = "Cara PIPPI, spero\ndi vederti presto.\11Ho sentito che\nZAFFERANOPOLI ha\11guai col TEAM\nROCKET.\11ARANCIOPOLI sembra\nincolume.",
  ["_VermilionPidgeyHousePidgeyText"] = "PIDGEY: Kurukkoo!",
  ["_VermilionPidgeyHouseYoungsterText"] = "Mando il mio\nPIDGEY a portare\11una lettera a\nZAFFERANOPOLI!",
  ["_VermilionPokecenterFishingGuruText"] = "Anche allo stesso\nlivello, i POKéMON\11hanno abilita'\nmolto diverse. Un\11POKéMON alleva to\né piu' forte di\11uno selvatico.",
  ["_VermilionPokecenterGuyText"] = "é vero che un\nlivello piu' alto\11rende piu'\nforte... Ma ogni\11POKéMON ha punti\ndeboli verso altri\11tipi. Quindi non\nesiste il POKéMON\11asso assoluto.",
  ["_VermilionPokecenterSailorText"] = "Il mio POKéMON era\navvelenato! é an\11dato K.O. mentre\ncamminavamo!",
  ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "Non\nvolevo per dere\11con nessuno!",
  ["_VictoryRoad1FCooltrainerFBattleText"] = "Chissa'\nse sei\11all'altezza!",
  ["_VictoryRoad1FCooltrainerFEndBattleText"] = "Ho\nperso!",
  ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "Lo\nammetto, sei piu'\11bravo di me!",
  ["_VictoryRoad1FCooltrainerMBattleText"] = "Vedo\nche vali! Fammi\11vedere quanto\nvali!",
  ["_VictoryRoad1FCooltrainerMEndBattleText"] = "Ci\nsperavo...",
  ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "Ti sei\nmeritato la VIA\11VITTORIA!",
  ["_VictoryRoad2FCooltrainerMBattleText"] = "Avanti!\nTi concio per le\11feste!",
  ["_VictoryRoad2FCooltrainerMEndBattleText"] = "Mi\nhanno suonato!",
  ["_VictoryRoad2FHikerAfterBattleText"] = "Se ti\nblocchi, prova a\11spostare qualche\nmasso!",
  ["_VictoryRoad2FHikerBattleText"] = "La VIA\nVITTORIA é il test\11finale per gli\nallenatori!",
  ["_VictoryRoad2FHikerEndBattleText"] = "Aiyah!",
  ["_VictoryRoad2FMoltresBattleText"] = "Gyaoo!",
  ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "Anche\n{RIVAL} é passato\11di qui!",
  ["_VictoryRoad2FSuperNerd1BattleText"] = "Ah,\nvuoi sfidare i\11SUPERQUATTRO?",
  ["_VictoryRoad2FSuperNerd1EndBattleText"] = "Mi hai\npreso!",
  ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "Posso\nbatterti in quanto\11a conoscenza\nPOKéMON!",
  ["_VictoryRoad2FSuperNerd2BattleText"] = "Se\npassi di qui, puoi\11incontrare i\nSUPERQUATTRO!",
  ["_VictoryRoad2FSuperNerd2EndBattleText"] = "No!\nIncredibile!",
  ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "Molti\nallenatori\11rinunciano qui.",
  ["_VictoryRoad2FSuperNerd3BattleText"] = "La VIA\nVITTORIA é troppo\11dura?",
  ["_VictoryRoad2FSuperNerd3EndBattleText"] = "Ben\nfatto!",
  ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "Mi\nhai mostrato\11quanto valgo!",
  ["_VictoryRoad3FCooltrainerF1BattleText"] = "Ti\nmostrero' quanto\11vali!",
  ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "Sono\nfuriosa!",
  ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "Lottando\nduro, si diventa\11forti!",
  ["_VictoryRoad3FCooltrainerF2BattleText"] = "Gli\nallenatori\11cerchano rivali\npiu' forti!",
  ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "Oh!\nChe forza!",
  ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "Hai\nbattuto GIOVANNI\11del TEAM ROCKET?",
  ["_VictoryRoad3FCooltrainerM1BattleText"] = "Ho\nsentito voci di un\11bimbo prodigio!",
  ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "Le\nvoci erano vere!",
  ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "Tutti\nqui vanno alla\11LEGA POKéMON!\nAttento!",
  ["_VictoryRoad3FCooltrainerM2BattleText"] = "Solo i\nprescelti passano\11di qui!",
  ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "Non ci\nposso credere!",
  ["_VictreebelDexEntry"] = "Vive in colonie\nenormi nel\nprofondo della\12giungla, anche se\nnessuno é mai\ntornato da quel\12posto.",
  ["_VileplumeDexEntry"] = "Piu' i petali sono\nampi, piu' polline\ntossico\12contengono. La\ngrossa testa é\npesante e dura da\12reggere.",
  ["_ViridianBlackboardBurnText"] = "Una scottatura\nriduce potenza e\11velocita' e causa\ndanni continui.\11Resta anche dopo\nla lotta. Usa\11ANTIBRUCIATURA!",
  ["_ViridianBlackboardFrozenText"] = "Se congelato, un\nPOKéMON resta\11immobile! Non si\nscongela neppure\11dopo la lotta. Usa\nANTIGELO!",
  ["_ViridianBlackboardPoisonText"] = "Da avvelenato, la\nsalute cala\11sempre. Il veleno\nresta anche dopo\11la lotta. Usa un\nANTIDOTO per\11guarirlo!",
  ["_ViridianBlackboardPrlzText"] = "La paralisi puo'\nfallire le mosse!\11Resta anche dopo\nla lotta. Usa\11l'ANTIPARALISI per\ncurarlo!",
  ["_ViridianBlackboardSleepText"] = "Un POKéMON non\nattacca se dorme!\11Resta addormentato\nanche dopo la\11lotta. Usa la\nSVEGLIA per\11svegliarlo!",
  ["_ViridianCityFisherReceivedTM42Text"] = "{PLAYER} riceve la\nMT42!",
  ["_ViridianCityFisherTM42ExplanationText"] = "La MT42 contiene\nSOGNIDORO...\11...Ronf...",
  ["_ViridianCityFisherTM42NoRoomText"] = "Hai gia' troppa\nroba con te.",
  ["_ViridianCityGambler1GymAlwaysClosedText"] = "Questa palestra é\nsempre chiusa.\11Chissa' chi é il\nCAPOPALESTRA?",
  ["_ViridianCityGambler1GymLeaderReturnedText"] = "Il CAPOPALESTRA é\ntornato!",
  ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "Oh nonno! Non\nessere cattivo!\11Non ha ancora\nbevuto il caffé.",
  ["_ViridianCityGirlWhenIGoShopText"] = "Quando vado a\nPLUMBEOPOLI, devo\11fare il sentiero\ndel BOSCO\11SMERALDO.",
  ["_ViridianCityGymLockedText"] = "Le porte della\npalestra sono\11chiuse",
  ["_ViridianCityGymSignText"] = "PALESTRA POKéMON\ndi SMERALDOPOLI",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "Ahh, ho bevuto il\ncaffé e sto bene!\11Ora puoi passare!\nHai fretta?",
  ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Usi il POKéDEX,\nvedo. Catturando\11un POKé MON si\naggiorna\11automaticamente.\nChe c'é? Non sai\11come catturarli?\nTe lo mostro io.",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "Non puoi passare!\nQuesta é\11proprieta'\nprivata!",
  ["_ViridianCityOldManTimeIsMoneyText"] = "Il tempo é\ndenaro... Cammina.",
  ["_ViridianCityOldManYouNeedToTheTargetText"] = "Prima devi indebo\nlire il POKéMON.",
  ["_ViridianCityPokecenterGuyText"] = "I CENTRI POKéMON\ncurano i POKéMON\11stanchi, feriti o\nesausti!",
  ["_ViridianCitySignText"] = "SMERALDOPOLI Il\nVerde Paradiso\11Eterno",
  ["_ViridianCityTrainerTips1Text"] = "CONSIGLI UTILI\nCattura POKéMON e\11amplia la tua\ncollezione! Piu'\11ne hai, piu' é\nfacile lottare!",
  ["_ViridianCityTrainerTips2Text"] = "CONSIGLI UTILI Le\nmosse dei POKé MON\11dipendono dai\nPUNTI POTERE, PP.\11Ripristinali ripo\nsando al CENTRO\11POKéMON!",
  ["_ViridianCityYoungster1Text"] = "Quelle POKé BALL\nalla cintura! Hai\11dei POKéMON! E'\nbello poterli\11portare e usare\novunque e sempre!",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "Vuoi sapere dei 2\ntipi di POKéMON\11bruco?",
  ["_ViridianForestLeavingSignText"] = "USCITA BOSCO\nSMERALDO\11PLUMBEOPOLI PIU'\nAVANTI",
  ["_ViridianForestNorthGateGrampsText"] = "Hai notato i\ncespugli lungo la\11strada? Possono\nessere tagliati da\11una mossa\nspeciale.",
  ["_ViridianForestNorthGateSuperNerdText"] = "Molti POKéMON vi\nvono solo nei\11boschi e grotte.\nDevi cercare ovun\11que per trovarli!",
  ["_ViridianForestSouthGateGirlText"] = "Vai al BOSCO\nSMERALDO? Attento,\11é un labirinto!",
  ["_ViridianForestSouthGateLittleGirlText"] = "RATTATA é piccolo,\nma il suo morso é\11feroce! Ne hai\nuno?",
  ["_ViridianForestTrainerTips1Text"] = "CONSIGLI UTILI Se\nvuoi evitare\11lotte, stai\nlontano dall'erba\11alta!",
  ["_ViridianForestTrainerTips2Text"] = "CONSIGLI UTILI\nContatta il\11PROF.OAK dal PC\nper far valutare\11il POKéDEX!",
  ["_ViridianForestTrainerTips3Text"] = "CONSIGLI UTILI Non\nrubare POKéMON\11altrui! Cattura\nsolo quelli\11selvatici!",
  ["_ViridianForestTrainerTips4Text"] = "CONSIGLI UTILI\nIndebolisci i\11POKéMON prima di\ncatturarli! Se\11sani, pos sono\nfuggire!",
  ["_ViridianForestUseAntidoteSignText"] = "Per il veleno, usa\nl'ANTIDOTO! Nei\11POKéMON MART!",
  ["_ViridianForestYoungster1Text"] = "Sono venuto qui\ncon degli amici!\11Cercano lotte con\ni POKéMON!",
  ["_ViridianForestYoungster2AfterBattleText"] = "Ssh!\nSpaventerai gli\11insetti!",
  ["_ViridianForestYoungster2BattleText"] = "Ehi!\nHai POKé MON!\11Forza, lottiamo!",
  ["_ViridianForestYoungster2EndBattleText"] = "No!\nCATERPIE non ce la\11fa!",
  ["_ViridianForestYoungster3AfterBattleText"] = "Accidenti!\nNe caturero' di\11piu' forti!",
  ["_ViridianForestYoungster3BattleText"] = "Ehi!\nNon puoi farti\11valere se sei un\nallenatore!",
  ["_ViridianForestYoungster3EndBattleText"] = "Eh?\nHo finito i\11POKéMON!",
  ["_ViridianForestYoungster4AfterBattleText"] = "A\nvolte trovi roba\11per terra! Cerco\nquello che ho\11perso io!",
  ["_ViridianForestYoungster4BattleText"] = "Ehi,\naspetta! Tanta\11fretta?",
  ["_ViridianForestYoungster4EndBattleText"] = "Mi\narrendo! Sei bravo\11in questo!",
  ["_ViridianForestYoungster5Text"] = "Ho finito le POKé\nBALL per cattura\11re i POKéMON!\nPortane sempre di\11scorta!",
  ["_ViridianGymCooltrainerM1AfterBattleText"] = "Serve\npotenza per\11reggere il ritmo\ndel nostro CAPO!",
  ["_ViridianGymCooltrainerM1BattleText"] = "Heh!\nTi stara' finendo\11il fiato!",
  ["_ViridianGymCooltrainerM1EndBattleText"] = "Ho\nesaurito la\11spinta!",
  ["_ViridianGymCooltrainerM2AfterBattleText"] = "Il\nCAPO mi sgridera'!",
  ["_ViridianGymCooltrainerM2BattleText"] = "I veri\ntalenti vincono\11con stile!",
  ["_ViridianGymCooltrainerM2EndBattleText"] = "Ho\nperso la presa!",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "Puoi\nandare alla LEGA\11POKéMON solo\nbattendo il CAPO!",
  ["_ViridianGymCooltrainerM3BattleText"] = "La\npalestra fu chiusa\11a lungo, ma ora il\nCAPO é tornato!",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "Sono\nstato battuto?",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "La MEDAGLIA TERRA\nfa' ubbidire i\11POKéMON di ogni\nlivello! é la\11prova della tua\nmaestria! Con essa\11puoi entrare nella\nLEGA! é il mio\11dono per la tua\nsfida!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "Avendo perso, non\nposso guar dare i\11subordinati! Il\nTEAM ROCKET é\11finito per sempre!\nDedicchero' la mia\11vita allo studio!\nCi rivedremo un\11giorno! Addio!",
  ["_ViridianGymGiovanniPreBattleText"] = "Fwahahaha!\nQuesto é il mio\11covo! Volevo\nrisurreci tare il\11ROCKET qui! Ma mi\nhai ripreso! E\11sia! Stavolta non\nmi trattengo!\11Affronterai\nGIOVANNI , il piu'\11grande!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "Ha! Una lotta\nintensa! Hai\11vinto! Ecco la\nprova con la\11MEDAGLIA TERRA!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER} riceve la\nMT27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "La MT27 é ABISSO!\nStende i POKéMON\11con un sol colpo!\nLa feci quando\11gestivo la\npalestra, molto\11tempo fa...",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "Non hai spazio per\nquesto!",
  ["_ViridianGymGuidePostBattleText"] = "Incredibile!\nGIOVANNI era il\11CAPOPALESTRA qui?",
  ["_ViridianGymGuidePreBattleText"] = "Ehila'!\nCampione! Neanche\11io so chi sia il\nCAPO di QUI! Sara'\11il piu' duro di\ntutti i capi! Ho\11sentito che amano\ni POKéMON di tipo\11terra!",
  ["_ViridianGymHiker1AfterBattleText"] = "Non\nsono ancora degno!",
  ["_ViridianGymHiker1BattleText"] = "Rrrroar!\nMi sto infuriando!",
  ["_ViridianGymHiker1EndBattleText"] = "Wargh!",
  ["_ViridianGymHiker2AfterBattleText"] = "Se i\nmiei POKéMON\11fossero bravi a\nKarate come me...",
  ["_ViridianGymHiker2BattleText"] = "Il\nkarate é la forma\11suprema di arti\nmarziali!",
  ["_ViridianGymHiker2EndBattleText"] = "Atcho!",
  ["_ViridianGymHiker3AfterBattleText"] = "La LEGA\nPOKéMON? Tu? Non\11montarti",
  ["_ViridianGymHiker3BattleText"] = "Sono il\nRE del KARATE! Il\11tuo destino é qui!",
  ["_ViridianGymHiker3EndBattleText"] = "Ayah!",
  ["_ViridianGymRocker1AfterBattleText"] = "Conosci\nl'identita' del\11nostro CAPO?",
  ["_ViridianGymRocker1BattleText"] = "Io e i\nPOKéMON facciamo\11musica\nmeravigliosa!",
  ["_ViridianGymRocker1EndBattleText"] = "Siete in\nperfetta armonia!",
  ["_ViridianGymRocker2AfterBattleText"] = "Aspetta!\nSono stato\11distratto!",
  ["_ViridianGymRocker2BattleText"] = "I tuoi\nPOKéMON tremaranno\11alla mia frusta!",
  ["_ViridianGymRocker2EndBattleText"] = "Ahi!\nFrustata!",
  ["_ViridianMartClerkParcelQuestText"] = "Conosci il PROF.\nOAK, giusto? Il\11suo ordine é\narrivato. Glielo\11porti? {PLAYER}\nprende il PACCO di\11OAK!",
  ["_ViridianMartClerkSayHiToOakText"] = "Ok! Salutami il\nPROF.OAK!",
  ["_ViridianMartClerkYouCameFromPalletTownText"] = "Ehi! Vieni da\nBIANCAVILLA?",
  ["_ViridianMartCooltrainerMText"] = "No! Le POZIONI\nsono esaurite.",
  ["_ViridianMartYoungsterText"] = "Questo negozio\nvende molti\11ANTIDOTI",
  ["_ViridianNicknameHouseBaldingGuyText"] = "Inventare i nomi é\nbello ma duro. I\11nomi semplici sono\ni piu' facili da\11ricordare.",
  ["_ViridianNicknameHouseLittleGirlText"] = "Anche il mio papa'\nadora i POKéMON.",
  ["_ViridianNicknameHouseSpearowText"] = "SPEARY: Tetweet!",
  ["_ViridianNicknameHouseSpearySignText"] = "SPEAROW Nome:\nSPEARY",
  ["_ViridianPokecenterCooltrainerMText"] = "C'é un CENTRO\nPOKéMON in ogni\11citta' davanti. E\nnon si paga\11assolutamente\nnulla!",
  ["_ViridianPokecenterGentlemanText"] = "Puoi usare quel PC\nnell'angolo. Me\11l'ha detto la\nreception. Che\11carini!",
  ["_ViridianSchoolBlackboardText1"] = "La lavagna de\nscrive i cambi di\11STATO dei POKéMON\ndurante la lotta.",
  ["_ViridianSchoolBlackboardText2"] = "Quale voce vuoi\nleggere?",
  ["_ViridianSchoolHouseBrunetteGirlText"] = "Uff! Studio per\nmemorizzare tutti\11i miei appunti.",
  ["_ViridianSchoolHouseCooltrainerFText"] = "Bene! Leggi\nattentamente la\11lavagna!",
  ["_ViridianSchoolNotebookText1"] = "Guarda il qua\nderno! Prima\11pagina... Le POKé\nBALL ser vono per\11catturare i\nPOKéMON. Si\11portano fino a 6\nPOKéMON. Chi li\11alleva e fa\nlottare é un\11allenatore\nPOKéMON.",
  ["_ViridianSchoolNotebookText2"] = "Seconda pagina...\nUn POKéMON sano é\11duro da catturare,\nindeboliscilo!\11Veleno, ustioni e\ndanni aiutano!",
  ["_ViridianSchoolNotebookText3"] = "Terza pagina...\nGli allenatori\11cercano sfide. Si\nlotta sempre in\11palestra.",
  ["_ViridianSchoolNotebookText4"] = "Quarta pagina...\nL'obiettivo é bat\11tere gli 8 CAPO.\nFallito cio',\11si\affrontano... I\nSUPERQUATTRO della\11LEGA POKéMON!",
  ["_ViridianSchoolNotebookText5"] = "RAGAZZA: Ehi! Non\nguardare i miei\11appunti!",
  ["_VitaminNoEffectText"] = "Non avra' alcun\neffetto.",
  ["_VitaminStatRoseText"] = "{RAM:wStringBuffer} di\n{RAM:wNameBuffer} é\11aumentato.",
  ["_VoltorbDexEntry"] = "Solitamente nelle\ncentrali\nelettriche. Spesso\12scambiato per una\nPOKé BALL, ha\nfulminato molte\12persone.",
  ["_VulpixDexEntry"] = "Alla nascita ha\nsolo una coda. La\ncoda si divide\12dalla punta man\nmano che cresce.",
  ["_WannaTrade1Text"] = "Cerco {RAM:wInGameTradeGiveMonName}!\nVuoi scambiarlo\11con {RAM:wInGameTradeReceiveMonName}?",
  ["_WannaTrade2Text"] = "Ciao! Vuoi scam\nbiare il tuo\11{RAM:wInGameTradeGiveMonName} per\n{RAM:wInGameTradeReceiveMonName}?",
  ["_WannaTrade3Text"] = "Ciao! Hai un\n{RAM:wInGameTradeGiveMonName}? Vuoi\11scambiarlo per\n{RAM:wInGameTradeReceiveMonName}?",
  ["_WardensHouseDisplayMerchandiseText"] = "Vecchi oggetti\nPOKéMON.",
  ["_WardensHouseDisplayPhotosAndFossilsText"] = "Foto e fossili di\nPOKéMON.",
  ["_WardensHouseWardenGaveTheGoldTeethText"] = "{PLAYER} da' i\nDENTI D'ORO al\11GUARDIANO!",
  ["_WardensHouseWardenGibberish1Text"] = "GUARDIA: Hif fuff\nhefifoo! Ha lof ha\11feef ee hafahi ho.\nHeff hee fwee!",
  ["_WardensHouseWardenGibberish2Text"] = "Ah howhee ho hoo!\nEef ee hafahi ho!",
  ["_WardensHouseWardenGibberish3Text"] = "Ha? He ohay heh ha\nhoo ee haheh!",
  ["_WardensHouseWardenHM04ExplanationText"] = "GUARDIA: La MN04\ninsegna FORZA!\11Permette ai\nPOKéMON di\11spostare i massi\nfuori dalla lotta.\11Ah, hai trovato la\nCASA SEGRETA? Se\11lo fai, vinci una\nMN. Sia la rara MN\11SURF",
  ["_WardensHouseWardenHM04NoRoomText"] = "Il tuo zaino é\npieno zeppo!",
  ["_WardensHouseWardenReceivedHM04Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_WardensHouseWardenTeethPoppedInHisTeethText"] = "Il GUARDIANO si é\nmesso i denti!",
  ["_WardensHouseWardenThanksText"] = "GUARDIA: Grazie,\nragazzo! Nessuno\11capiva una parola.\nNon potevo lavo\11rare cosi'. Prendi\nqualcosa per il\11disturbo.",
  ["_WarpToLastPokemonCenterText"] = "Vai all'ultimo\nCENTRO POKéMON.",
  ["_WartortleDexEntry"] = "Spesso si nasconde\nin acqua in\nagguato. Per\12nuotare veloce\nmuove le orecchie\nper mantenere il\12bilanciamento.",
  ["_WasBlownAwayText"] = "{TARGET} é stato\nspazzato via!",
  ["_WasSeededText"] = "{TARGET} é stato\nparassitato!",
  ["_WeedleDexEntry"] = "Comune nei boschi,\nmangia foglie. Ha\nun pungiglione\12velenoso e acuto\nsulla testa.",
  ["_WeepinbellDexEntry"] = "Spruzza la\nPOLVERVELENO per\nbloccare il nemico\12e poi lo finisce\ncon un getto di\nACIDO.",
  ["_WeezingDexEntry"] = "Dove due gas\nvelenosi si\nincontrano, 2\12KOFFING possono\nfondersi in un\nWEEZING.",
  ["_WhatDoYouWantText"] = "Che cosa vuoi\nfare?",
  ["_WhatGoesAroundComesAroundText"] = "Chi la fa\nl'aspetti!",
  ["_WhatText"] = "Cosa?",
  ["_WhatToDepositText"] = "Che cosa vuoi\ndepositare?",
  ["_WhatToTossText"] = "Che cosa vuoi\nbuttare via?",
  ["_WhatToWithdrawText"] = "Che cosa vuoi\nritirare?",
  ["_WhenYouChangeBoxText"] = "Cambiando BOX, i\ndati saranno\11salvati. Va bene?",
  ["_WhereWouldYouLikeText"] = "Dove vorresti\nandare?",
  ["_WhichFloorText"] = "Quale piano\npreferisci?",
  ["_WhichMoveToForgetText"] = "Quale mossa deve\nessere\11dimenticata?",
  ["_WhichPrizeText"] = "Quale premio vuoi?",
  ["_WigglytuffDexEntry"] = "Il corpo é soffice\ne gommoso. Se\narrabbiato, aspira\12aria e si gonfia\nad enormi\ndimensioni.",
  ["_WildMonAppearedText"] = "Appare {RAM:wEnemyMonNick}\nselvatico!",
  ["_WildRanText"] = "{RAM:wEnemyMonNick}\nselvatico fugge!",
  ["_WillBeTradedText"] = "{RAM:wNameOfPlayerMonToBeTraded} e\n{RAM:wNameBuffer} saranno\11scambiati.",
  ["_WithExpAllText"] = "con EXP.TUTTI,",
  ["_WithdrawHowManyText"] = "Quanti?",
  ["_WithdrewItemText"] = "Hai ritirato\n{RAM:wNameBuffer}.",
  ["_WokeUpText"] = "{USER} si é\nsvegliato!",
  ["_WontObeyText"] = "{RAM:wBattleMonNick} non\nobbedisce!",
  ["_WouldYouLikeToSaveText"] = "Vuoi SALVARE il\ngioco?",
  ["_WrongMon1Text"] = "Cosa? Non é\n{RAM:wInGameTradeGiveMonName}!\11Trovane uno e\ntorna qui!",
  ["_WrongMon2Text"] = "Mhm? Questo non é\n{RAM:wInGameTradeGiveMonName}. Pensa\11a me se ne trovi\nuno.",
  ["_WrongMon3Text"] = "...Questo non é un\n{RAM:wInGameTradeGiveMonName}. Se ne\11trovi uno,\nscambialo con me!",
  ["_YeahText"] = "Si'!",
  ["_YourNameIsText"] = "Giusto! Ti chiami\nproprio {PLAYER}!",
  ["_ZapdosDexEntry"] = "Un volatile\nleggendario che\nappare tra le\12nuvole scagliando\nenormi scariche di\nfulmini.",
  ["_ZubatDexEntry"] = "Crea colonie in\nluoghi bui. Usa\nultrasuoni per\12identificare e\navvicinare i suoi\nbersagli.",





  ["MelanieText1"] = "Curo i POKéMON\nferiti. Ho curato\11questo BULBASAUR\nfino a farlo\11guarire. Ora ha\nbisogno di un\11bravo allenatore.",
  ["MelanieText2"] = "Ho un'idea! Vuoi\nprenderti cura di\11questo BULBASAUR?",
  ["MelanieText3"] = "Abbi cura di\nBULBASAUR!",
  ["MelanieText4"] = "Come sta il tuo\nBULBASAUR?",
  ["MelanieText5"] = "Oh... Che\npeccato...",
  ["OAK: Look, {PLAYER}! Do\nyou see that ball\non the table?"] = "OAK: Guarda {PLAYER}!\nVedi quella sfera\nsul tavolo?",
  ["SilphCo2FSilphWorkerFPleaseTakeThisText"] = "Aaaaah! No! Aiuto!\nAh, non sei del\11TEAM ROCKET.\nPensavo...\11Perdonami! Prendi\nquesto, ti prego!",
  ["SummerBeachHouseSurfinDudeText1"] = "Uau! Il tuo\nPIKACHU sa usare\11SURF! Allora non\nsono il solo...\11Fantastico! Ora\npuoi fare SURF\11insieme a me! Ti\nva?",
  ["SummerBeachHouseSurfinDudeText2"] = "Vieni a fare SURF\nquando vuoi,\11amico!",
  ["SummerBeachHouseSurfinDudeText3"] = "Vuoi fare SURF?",
  ["SummerBeachHouseSurfinDudeText4"] = "Oggi c'e' una gran\nbella onda!",
  ["_MrPsychicsHouseMrPsychicNoMoreText"] = "...Aumm...",
  ["_MrPsychicsHouseMrPsychicText"] = "...Aspetta! Non\ndire una parola!\11Volevi questo!",
  ["_MtMoonJessieJamesText1"] = "Fermati li'!",
  ["_MtMoonJessieJamesText2"] = "Quel fossile e'\ndel TEAM ROCKET!\11Arrenditi subito o\npreparati a\11combattere!",
  ["_MtMoonJessieJamesText3"] = "Un ragazzino ci ha\nbattuti?",
  ["_MtMoonJessieJamesText4"] = "Il TEAM ROCKET\nparte alla carica\11alla velocita'\ndella luce!",
  ["_MtMoonPokecenterMagikarpSalesmanOfferText"] = "UOMO: Salve! Ho\nun'offerta\11speciale per te!\nTi daro' un\11fantastico\nMAGIKARP per soli\11500¥! Che ne dici?",
  ["_OaksLabChooseMonText"] = "OAK: Eh? {RIVAL}?\nPerche' sei gia'\11qui? Ti avevo\ndetto di venire\11piu' tardi... Beh,\npazienza! Aspetta\11un attimo. Guarda,\n{PLAYER}! Vedi\11quella sfera sul\ntavolo? Si chiama\11POKé BALL.\nContiene un\11POKéMON. Puoi\nprenderla! Forza,\11e' tua!",
  ["_OaksLabOak1GoAheadItsYours"] = "Forza, e' tuo!",
  ["_OaksLabOak1YouShouldTalkToIt"] = "OAK: Dovresti\nparlargli per\11vedere come sta.",
  ["_OaksLabOakGivesText"] = "OAK: {PLAYER},\nquesto e' il\11POKéMON che ho\ncatturato. Puoi\11tenerlo tu. L'ho\ncatturato da poco,\11quindi e' ancora\nselvatico.",
  ["_OaksLabPikachuDislikesPokeballsText1"] = "OAK: Cosa?",
  ["_OaksLabPikachuDislikesPokeballsText2"] = "OAK: Guarda qui!\nE' strano, ma\11sembra che il tuo\nPIKACHU odi le\11POKé BALL. Tienilo\nfuori con te. Lo\11rendera' felice!\nPuoi parlargli per\11vedere come sta.",
  ["_OaksLabPikachuText"] = "OAK: Forza, e'\ntuo!",
  ["_OaksLabReceivedText"] = "{PLAYER} riceve\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalIllGetABetterPokemonThanYou"] = "{RIVAL}: Uffa!\nPrendero' un\11POKéMON migliore\ndel tuo!",
  ["_OaksLabRivalTakesText1"] = "{RIVAL}: Non se ne\nparla! {PLAYER}, io\11voglio questo!",
  ["_OaksLabRivalTakesText2"] = "{RIVAL} prende il\nPOKéMON!",
  ["_OaksLabRivalTakesText3"] = "OAK: {RIVAL}! Ma\ncosa fai?",
  ["_OaksLabRivalTakesText4"] = "{RIVAL}: Nonno, io\nvoglio questo!",
  ["_OaksLabRivalTakesText5"] = "OAK: Ma io... Ah,\ne va bene. Prendi\11pure quello. Tanto\nvolevo darne uno\11anche a te...\n{PLAYER}, vieni\11qui.",
  ["_OaksLabThatsAPokeball"] = "Questa e' una POKé\nBALL!",
  ["_OfficerJennyText1"] = "Ho appena preso\nquesto SQUIRTLE\11che creava\nproblemi. Ha\11bisogno di un\nbravo allenatore\11che lo educhi.",
  ["_OfficerJennyText2"] = "Hai la MEDAGLIA\nTUONO!? Devi\11essere un bravo\nallenatore! Ho\11preso questo\nSQUIRTLE che dava\11sempre problemi.\nVorresti\11allenarlo?",
  ["_OfficerJennyText3"] = "OK! Abbi cura di\nSQUIRTLE!",
  ["_OfficerJennyText4"] = "Oh... Che cosa\nfaro' adesso?",
  ["_OfficerJennyText5"] = "Come sta andando\ncon SQUIRTLE?",
  ["_PalletTownOakComeWithMe"] = "Vieni con me!",
  ["_PalletTownOakThatWasCloseText"] = "C'e' mancato poco!\nPOKéMON selvatici\11vivono nell'erba!",
  ["_PalletTownOakWhewText"] = "Uff...",
  ["_PokemonTowerJessieJamesText1"] = "Fermati li'!",
  ["_PokemonTowerJessieJamesText2"] = "Il vecchio laggiu'\nvoleva lamentarsi,\11cosi' gli daremo\nuna lezione.\11Arrenditi subito o\npreparati a\11combattere!",
  ["_PokemonTowerJessieJamesText3"] = "Te ne pentirai,\nragazzetto!",
  ["_PokemonTowerJessieJamesText4"] = "Sembra che il TEAM\nROCKET decolli di\11nuovo!",
  ["_RocketHideoutJessieJamesText1"] = "Non fare un solo\npasso, moccioso!",
  ["_RocketHideoutJessieJamesText2"] = "Come hai osato\numiliarci sul\11MONTE LUNA?! E'\nora della resa dei\11conti!",
  ["_RocketHideoutJessieJamesText3"] = "Maledetto\nmoccioso!",
  ["_RocketHideoutJessieJamesText4"] = "Sembra che il TEAM\nROCKET decolli di\11nuovo!",
  ["_Route24DamianText1"] = "Non sono bravo ad\nallenare i\11POKéMON. Penso che\ndovrei liberare il\11mio CHARMANDER...\nSe mi prometti che\11ne avrai cura, te\nlo regalo. Va\11bene?",
  ["_Route24DamianText2"] = "Abbi cura del mio\nCHARMANDER!",
  ["_Route24DamianText3"] = "Ah... Allora e'\nmeglio liberarlo.",
  ["_Route24DamianText4"] = "Come sta il mio\nCHARMANDER?",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "Moccioso!\nChe sfacciato!",
  ["_SSAnneKitchenCook2Text"] = "Ho visto una sfera\nmolto strana nel\11cestino.",
  ["_SilphCo7FSilphWorkerM1ThankYouText"] = "Ah! Ehi! Non sei\ndel TEAM ROCKET!\11Sei venuto a\nsalvarmi?\vGrazie\11mille! Voglio che\ntu abbia questo\11POKéMON per averci\nsalvati.",
  ["_SilphCo9FNurseText"] = "Non arrenderti!",
  ["_SilphCo9FNurseText2"] = "Grazie mille!",
  ["_SilphCo9FNurseYouLookTiredText"] = "Sembri molto\nstanco! Dovresti\11riposarti un po'!",
  ["_SilphCoJessieJamesText1"] = "Fermati li',\nmoccioso!",
  ["_SilphCoJessieJamesText2"] = "Il nostro CAPO e'\nin una riunione!\11Non disturbarlo!",
  ["_SilphCoJessieJamesText3"] = "Come sempre...",
  ["_SilphCoJessieJamesText4"] = "TEAM ROCKET,\npronti a decollare\11alla velocita'\ndella luce! Di\11nuovo...",
  ["_StoppedEvolvingText"] = "Uh? {RAM:wStringBuffer} ha\nsmesso di\11evolversi!",
  ["_StrengthsAndWeaknessesText"] = "Tutti i tipi di\nPOKéMON hanno\11punti di forza e\ndi debolezza\11contro gli altri\ntipi.",
  ["_SummerBeachHousePoster1Text1"] = "Appunti del\nMAESTRO\11SURFISTA... Quando\nentro nel tubo, la\11musica parte a\npalla!",
  ["_SummerBeachHousePoster1Text2"] = "30 anni di onde!\nMAESTRO SURFISTA",
  ["_SummerBeachHousePoster2Text1"] = "CONSIGLI SURF 1\nDopo un salto,\11allinea la tavola\ncon l'onda per un\11effetto super!",
  ["_SummerBeachHousePoster2Text2"] = "CASA SULLA\nSPIAGGIA ESTIVA\11POKéMON Benvenuti!",
  ["_SummerBeachHousePoster3Text1"] = "CONSIGLI SURF 2\nFare piu'\11rotazioni in un\nsalto e' troppo\11forte!",
  ["_SummerBeachHousePoster3Text2"] = "Il mare unisce\ntutti i surfisti!",
  ["_SummerBeachHousePrinterText1"] = "E' una specie di\nmacchinario...",
  ["_SummerBeachHousePrinterText2"] = "STAMPANTE DELLA\nCASA SULLA\11SPIAGGIA ESTIVA\nPOKéMON...",
  ["_SummerBeachHousePrinterText3"] = "Mostra i tuoi\nrecord. Vuoi\11STAMPARE?",
  ["_SummerBeachHousePrinterText4"] = "STAMPANTE DELLA\nCASA SULLA\11SPIAGGIA ESTIVA\nPOKéMON... Mostra\11i tuoi record.\nVuoi STAMPARE?",
  ["_SummerBeachHousePrinterText5"] = "STAMPA completata!",
  ["_SummerBeachHousePrinterText6"] = "Errore di stampa!",
  ["_VermilionGymTrashFailText"] = "No! C'e' solo\nspazzatura qui.\11Ehi! Le serrature\nelettroniche si\11sono riattivate!",
  ["_ViridianCityOldManLosingMyTouchText"] = "Non ha funzionato\ncome pensavo. Sto\11perdendo il mio\ntocco... Ho finito\11anche le POKé\nBALL. Andro' a\11comprarne altre al\nBAZAR.",
  ["_ViridianCityOldManYouNeedToWeakenTheTargetText"] = "Prima di tutto,\ndevi indebolire il\11POKéMON.",
  ["_ViridianForestCooltrainerFAfterBattleText"] = "Ho\ncercato\11dappertutto, ma\nnon ho trovato\11nessun PIKACHU!",
  ["_ViridianForestCooltrainerFBattleText"] = "Ehi,\nhai un PIKACHU?",
  ["_ViridianForestCooltrainerFEndBattleText"] = "Oh,\nno! Davvero?",
  ["_ViridianForestYoungster5AfterBattleText"] = "METAPOD\ne' forte perche'\11la sua miglior\ndifesa e'\11l'ATTACCO!",
  ["_ViridianForestYoungster5BattleText"] = "Saro'\nil migliore. Non\11potrai mai\nbattermi!",
  ["_ViridianForestYoungster5EndBattleText"] = "Dopo\ntutto quello che\11ho fatto...",
  ["_ViridianForestYoungster6Text"] = "Ho finito le POKé\nBALL per catturare\11altri POKéMON! E'\nsempre meglio\11avere qualche\nscorta!",

  ["FanClubChairPrintText1"] = "Ciao, {PLAYER}! Hai\ngia' visto le\11mie\vfoto di #MON?\nLe ho messe in\11cornice e appese\nla' sulla\vparete.\11Ah, gia'! Vuoi che\nti faccia\11una\vfoto dei\ntuoi\vPOKéMON",
  ["FanClubChairPrintText2"] = "No? Che delusione",
  ["FanClubChairPrintText3"] = "Ecco fatto",
  ["FanClubChairPrintText4"] = "Possiamo STAMPARE\nin un altro\11momento",
  ["SSAnneKitchenCook7EelsAuBarbecueText"] = "Spiedini di\nanguilla! Temo che\11gli invitati\nfaranno\vuna\11rivolta",
  ["SSAnneKitchenCook7PrimeBeefSteakText"] = "Bistecca di manzo!\nMa avremo\11abbastanza\nbistecche",
  ["SSAnneKitchenCook7SalmonDuSaladText"] = "Insalata di\nsalmone! Eppure\11gli invitati\nprotesteranno\11perché\vé di nuovo\npesce",
  ["TMNotebookText"] = "É un volantino\nsulle MT. ... Ci\11sono 50 MT in\ntotale. Esistono\11anche 5 SM che si\npossono usare piu'\11volte. SILPH SPA",
  ["TeachingHMsText"] = "Quando un POKéMON\nimpara una MO,\vla\11mossa non\npotra'\vpiu'\11essere\ndimenticata. É\11bene pensarci bene\nprima di insegnare\11una mossa\vMO",
  ["ViridianCityFisherYouCanHaveThisText"] = "Uffa! De me ne\nsono addormentato\11al sole. Ho\nsognato che un\11DROWZEE si\nmangiava\vi miei\11sogni...\vCos'é\nquesto? Da dove\11spunta questa MT?\nChe paura! Tieni,\11prendi questa MT",
  ["_FanClubChairPrintText1"] = "Ciao, {PLAYER}! Hai\ngia' visto le\11mie\vfoto di #MON?\nLe ho messe in\11cornice e appese\nla' sulla\vparete.\11Ah, gia'! Vuoi che\nti faccia\11una\vfoto dei\ntuoi\vPOKéMON",
  ["_FanClubChairPrintText2"] = "No? Che delusione",
  ["_FanClubChairPrintText3"] = "Ecco fatto",
  ["_FanClubChairPrintText4"] = "Possiamo STAMPARE\nin un altro\11momento",
