  ["_OaksLabRivalMyPokemonHasGrownStrongerText"] = "{RIVAL}: Nonno, il\nmio POKéMON é\11cresciuto un\nsacco!\vGuardati\11questo",
  ["_PokemonFanClubClefairyFanBetterText"] = "Bah! Il mio\nCLEFAIRY é due\11volte piu' carino\ndi quel\vpesce",
  ["_PokemonFanClubClefairyFanNormalText"] = "Non vuoi ammirare\nl'adorabile\11coda\vdel mio\nCLEFAIRY",
  ["_PokemonFanClubClefairyFanText"] = "Il passatempo del\nostro PRESIDENTE\11ora é\nfotografare\vi\11POKéMON. Mi ha\ndato una foto\11STAMPATA del\vmio\nCLEFAIRY",
  ["_PokemonFanClubClefairyText"] = "CLEFAIRY: Fiffii",
  ["_PokemonFanClubSeelFanText"] = "Ho bisogno di un\ncavo per\11connettere e\nSTAMPARE una\11foto\vdel mio SEEL",
  ["_SSAnneKitchenCook7EelsAuBarbecueText"] = "Spiedini di\nanguilla! Temo che\11gli invitati\nfaranno\vuna\11rivolta",
