  ["_SavingText"] = "Salvataggio in\ncorso",
  ["_SilphCo2FSilphWorkerFPleaseTakeThisText"] = "Aaaaah! No! Fermo!\nAiuto! Ah, non sei\11un membro del TEAM\nROCKET.\vPensavo...\vPerdonami.\11Tieni, prendi\nquesto",
  ["_TeachingHMsText"] = "Quando un POKéMON\nimpara una MO,\vla\11mossa non\npotra'\vpiu'\11essere\ndimenticata. É\11bene pensarci bene\nprima di insegnare\11una mossa\vMO",
  ["_ViridianCityFisherYouCanHaveThisText"] = "Uffa! De me ne\nsono addormentato\11al sole. Ho\nsognato che un\11DROWZEE si\nmangiava\vi miei\11sogni...\vCos'é\nquesto? Da dove\11spunta questa MT?\nChe paura! Tieni,\11prendi questa MT",
